# -*- coding: utf-8 -*-
"""
数字宫格关卡（levels/nine_grid.py）

任务：1m×1m 九宫格（3x3，左下位置6恒空），7 块数字面板(1~7)随机布局，
机器人按 1→7 顺序依次到达各面板中心（踩中微动开关），限时 15 分钟。
评分：顺序正确每格 10 分（70），限时完成 +30。

方案要点（2026-09-08 定稿；2026-09-11 导航改 v3 视觉伺服，详见
docs/关卡算法/数字宫格攻略.md §3.2b）：
  视觉  颜色主判（HSV 七色，1红..7粉）+ HOG+SVM 黑色数字仲裁（只否决）；
        面板中心：未裁切取四边形对角线交点（透视不变量）；被画幅裁切时
        对角线交点失效（实测偏差 150~800px），改用颜色掩膜凸包面积质心。
  导航  **v3 视觉伺服（默认）**：地板会形变 → 机体俯仰/相机高度大幅变化
        （按 ±15° 考虑，可见地面带 4 倍摆动），因此导航主链只用相对量：
        搜索（头部五档 + 按死推提示转向 / 盲走）→ 对准（像素 yaw，小转角
        闭环、死区 3.5°）→ 接近（目标框宽 ≥920px ≈ 进 35cm）→ 低头到达
        （颜色占比**峰值跟踪 + 分段前压**：跌破峰值 55% 即判压过该格）→
        蹭步确认 → 死推位姿锚到格心。
        地图（布局扫的 digit_cell + 动作模型死推位姿）只作"往哪转/盲走多远"
        的粗提示；GN 地图定位降级为可选校正（USE_MAP_CORRECTION，失败只记
        日志、不触发恢复链）。现场应急：VIS_NAV_ENABLED=False 回 v2 地图路径。
  定位（v2 地图路径，保留为回退/诊断）  地图 GN：布局已知后 9 个格心即
        "地图"；每步用名义动作模型预测位姿，以可见面板的「投影像素 ↔ 检出
        像素」残差迭代修正。未裁切用面板中心投影 ↔ 对角线交点；已裁切用
        "预测四角投影∩画幅的面积质心 ↔ 凸包质心"。IRLS + Cauchy 鲁棒核 +
        弱先验正则（σ=8cm/8°）。**注意：它依赖冻结的相机常数，地板形变下
        会整片超门控——这正是 v3 改视觉伺服的原因。**
  运动  小幅度动作白名单（单步 2cm 前进、~2cm 横移、3.2cm 后退）；远距
        批量上限 VIS_BATCH_MAX_STEPS=5（10cm）。本场地禁用
        go_forward / go_forward_fast（5cm 步幅在小面板+打滑地板上易摔倒，
        `_act` 硬门拒绝）。转向用「在线 EMA 估计小转实际角（误差源 = 像素
        yaw 或地图方位），连续 2 批 <0.5°/次→升级大转」+ 大转防振荡。
  容错  卡滞检测（框宽不涨/定位不改善 → 后退脱困）、目标丢失（头部扫找回
        → 回退半步 → 重搜）、分格时间预算 + **单格硬熔断**（VIS_CELL_HARD_*：
        时间/拍照/动作三重护栏，任一触发即"本格记未确认、立即返回"）
        + 全局看门狗 + 预算不足自动收缩低头段迭代、到达确认（颜色出现→
        消失主判 + 蹭步压微动开关）。绝不跳格：跳格断 70 分计分链（ESP32
        顺序错只日志不断链，借道穿越其他面板计分安全）。

到达确认为什么不改回"低头色占比绝对阈值"：参考实现的每色阈值（0.002~0.17）
在本机俯角下判不到（实测峰值仅 0.13）——v3 用**尺度无关**的"峰值跟踪 + 相对
跌落"，与颜色/光照/俯仰无关。历史结论"低头色占比不可用"是旧相机模型
（39cm/41.4°，可见地面带 15.8cm 起）下的结论，现在几何已修正。

布局扫描 v2（2026-09-11，无站位依赖）：机器人从前一关卡进入，初始位姿
未知不可控，因此布局扫不用任何场地系先验——每帧观测经"机器人系单应"
（from_pose((0,0), 高度, 俯仰, head_pulse=头部档)；头部偏航已并入相机朝向，
故宽扫档 ±40.5°/±63° 的观测不会被当成中位档映射——见
core.ground_homography.from_pose 的 head_in_pose）转为机器人系地面坐标，
跨帧按 digit 聚合（**未裁切观测优先**，同数字跨帧离散 >SPREAD_MAX_CM 剔除），
再在 (安装偏移, 相机高度) 参数网格上做格阵拟合（lattice_assign：假设-共识找
格阵基 + **4 个真旋转**硬约束（手性论证见模块内注释）+ 刚体残差门 + 覆盖率门
+ 入口侧/列序谓词 + 格6恒空优先）。胜出布局即数字→格，胜出组合中位数即自标定
常数；随后用"机器人系点 ↔ 场地格心"2D 刚体拟合**直接解出位姿**（不再解单应
再 decompose），GN 定位从此自续。格阵歧义/缺数字/自举自检不过时自动前进一步
重扫（平移视差消歧、带进近排），最多 3 轮。扫描终止判据 = 未裁切观测覆盖
≥LAYOUT_MIN_CLEAN_DIGITS 个数字**且两档俯仰都已有观测**（只扫一档会让
"安装偏移 vs 名义俯仰角"退化，实测 (1200,25°) ≡ (1040,10°)）。

现场依赖：
  1) 无标定依赖（布局扫 v2 已去除；archive/result/ninegrid_homography.json
     与 tools/calib_ninegrid.py 保留为诊断工具）；
  2) COLOR_THRESHOLDS 现场复标（tools/debug_vision.py ninegrid 子命令）；
  3) SVM 仲裁依赖 scikit-learn/skimage/joblib（缺失自动降级纯颜色）。

注意：localize() 不切换物理俯仰，按 state 当前俯仰拍照解算；调用方负责
用 state.set_pitch 保证俯仰与期望视野一致（GN 按 pitch 档投影）。
"""

import math
import time
from collections import namedtuple
from itertools import combinations

import cv2
import numpy as np

try:
    import cv2
except Exception:
    cv2 = None

from core.camera_config import (
    HEAD_CENTER, HEAD_LEFT, HEAD_RIGHT, HEAD_WIDE_LEFT, HEAD_WIDE_RIGHT,
    SERVO_DEG_PER_US, CAMERA_INTRINSIC, CAMERA_DISTORTION,
    CAMERA_WIDTH, CAMERA_HEIGHT,
    CAM_PITCH_MOUNT_OFFSET_DEG, CAM_HEIGHT_STANDING_CM,
)
from core.ground_homography import (
    GroundHomography, grid_cell_center, cell_index,
    CAMERA_TO_BODY_FORWARD_CM, GRID_CELL_CM,
)
from core.robot_core import (RobotState, lock_camera_controls,
                                auto_calibrate_exposure,
                                CAM_AUTO_EXPOSURE_ENABLED)
from vision.nine_grid_detector import (NineGridDetector, ID_TO_COLOR,
                                       build_color_mask,
                                       normalize_illumination)

# 相机光心高度缺省值：来自 camera_config（机器人自身属性）；layout_scan
# 运行时用格阵拟合参数网格自标定刷新（self._cam_height_cm）
CAM_HEIGHT_CM = CAM_HEIGHT_STANDING_CM
PITCH_NAV = 1200      # 前视导航/布局预扫（下沿 53.5°；转弯不拍到自身）
PITCH_DOWN = 1040     # 低头：可见地面带 **3.8~85.7cm**（近距/脚下判定；2026-09-24 复算）
PANEL_HALF_CM = 14.0  # 面板色块半边长（33cm 格含缝，色块约 28cm）——P3 实测校准

# =====================================================================
# 到达与对准容差（面板 33cm，微动开关区≈中心 2/3≈±5.5cm）
# =====================================================================
ALIGN_TOL_DEG = 8.0      # 航向差小于此视为对准
ENTER_ALIGN_TOL_DEG = 15.0  # 进入段容忍的航向差上限（粗对齐即可，横移纠偏）
ENTER_BEARING_GATE_CM = 12.0  # 进入段纵向小于此不再按 bearing 转向（方位角病态）
FAR_DIST_CM = 18.0       # > 此值允许 one_step 批量（配合 3 步上限 ≈6cm）
MID_DIST_CM = 20.0       # > 此值 APPROACH，否则 ENTER（切低头）
# 为什么 20cm 就切低头：导航档（pitch 1200）可见地面从 **18.5cm** 起（2026-09-24
# 按现行常数复算：h=56cm、有效俯角 45.5°），目标面板在 20cm 处远边仅 34cm、
# 且其它面板都在身后——继续用导航档会"整帧 0 个面板"。
# 低头档（1040）可见地面从 **3.8cm** 起（旧注释写 15.8cm，是按 h=39cm 的旧常数
# 推的，已作废），能持续看到目标面板的可见条。
ENTER_MIN_CM = -10.0     # 中心退到脚后此值内仍算"到位"（防过冲判据）
ENTER_TOL_CM = 4.0       # 中心进入 [ENTER_MIN, ENTER_TOL] 转 CONFIRM
LAT_TOL_CM = 4.0         # 横偏容差；超过用横移纠正
CONFIRM_LAT_MAX_CM = 6.0
TURN_NEAR_LIMIT_CM = 20.0  # 距目标中心小于此先退格再转（防面板边缘转向）

# =====================================================================
# 动作白名单与名义位移模型（预测用；实测标定值见 levels/goodluck.py）
# =====================================================================
# 本场地禁用 go_forward / go_forward_fast：5cm 步幅在 33cm 小面板+打滑地板上
# 容易重心前扑摔倒（现场结论）。前进一律用 go_forward_one_step（2cm），
# 远距允许小批量（≤3 次=6cm）。白名单外的动作由 _act 直接拒绝。
DISABLED_ACTIONS = ("go_forward", "go_forward_fast")

FORWARD_ONE_STEP_CM = 2.0   # go_forward_one_step（唯一前进原语）
BACK_ONE_STEP_CM = 3.2      # back_one_step
LEFT_MOVE_CM = 1.9
RIGHT_MOVE_CM = 2.2
TURN_LEFT_DEG = 22.0
TURN_RIGHT_DEG = 25.7
BATCH_MAX_STEPS = 3         # 单次批量 one_step 上限（3×2cm=6cm；打滑地板保守值）
BATCH_MAX_ANGLE_DEG = 4.0   # 批量直行允许的最大航向差

# =====================================================================
# 运动原语的**现场实测值**（runbook §2 测量 1；2026-09-25 P1 落地）
# =====================================================================
# 为什么必须单独列出来：`ACTION_MODEL` 里的小转此前写的是**名义 ±2.0°/步**，
# 而实测是左 **8.625°** / 右 **5.200°**（差 330%/160%）。旧代码拿 `ACTION_MODEL`
# 去规划步数 ⇒ `n = floor(|yaw| / 2.0)` 会把 16.5° 的偏差算成 6 步，真机一次转
# **51.75°**（转过头 3 倍）→ 丢目标 → 重搜。
#
# ★ 使用纪律（《需求规格-2026-09-25-统一决策重写》§7.7）：
#   这两个常量**只允许**两个用途：(a) 下发动作；(b) 遥测/测试里的期望值。
#   **不许进任何判据**（不许再做 `n = f(角度/步长)` 的除法）。统一决策一次决策
#   只下发一个原语，因此不需要"每步多少度"这种规划常数。
TURN_LEFT_SMALL_DEG = 8.625     # turn_left_small_step（20 步 ×2 组）
TURN_RIGHT_SMALL_DEG = 5.200    # turn_right_small_step（20 步 ×2 组）

# (类型, 名义增量)：fwd 前向 cm（负=后退）、lat 右向 cm、turn 右转度（右正）
ACTION_MODEL = {
    "go_forward_one_step": ("fwd", FORWARD_ONE_STEP_CM),
    "back_one_step": ("fwd", -BACK_ONE_STEP_CM),
    "left_move": ("lat", -LEFT_MOVE_CM),
    "right_move": ("lat", RIGHT_MOVE_CM),
    "turn_left": ("turn", -TURN_LEFT_DEG),
    "turn_right": ("turn", TURN_RIGHT_DEG),
    "turn_left_small_step": ("turn", -2.0),
    "turn_right_small_step": ("turn", 2.0),
    "stand": (None, 0.0),
}

# 动作名 → 日志用中文名（只用于打印；动作名本身仍是 ACTION_MODEL 里的键）
_ACTION_LABEL_CN = {
    "go_forward_one_step": "前进一步",
    "back_one_step": "后退一步",
    "left_move": "左移",
    "right_move": "右移",
    "turn_left": "左大转",
    "turn_right": "右大转",
    "turn_left_small_step": "左小转",
    "turn_right_small_step": "右小转",
    "stand": "站立",
}


def _action_cn(name, times=1):
    """动作名 → 日志可读文案（如 (turn_left_small_step, 6) → '左小转×6'）"""
    label = _ACTION_LABEL_CN.get(name, str(name))
    return label if int(times) <= 1 else f"{label}×{int(times)}"


# 档位 → 中文（日志用；与用户示意图的绿/蓝/橙一一对应）
_ZONE_CN = {"move": "绿·直行", "lat": "蓝·横移", "rot": "橙·旋转"}

# =====================================================================
# 自适应小转向（继承参考方案：在线估计 + 失效升级）
# =====================================================================
SMALL_TURN_INIT_DEG = 2.0     # 小转单次角度初估（P3 实测覆盖；goodluck 实测不可靠）
TURN_EMA_ALPHA = 0.3          # 指数滑动平均
TURN_EMA_ALPHA_FAST = 0.5     # 前几批用快收敛，抵消初值偏差
TURN_EMA_FAST_UPDATES = 2     # 快收敛批次数
MIN_EFFECTIVE_TURN_DEG = 0.5  # 每次实际转角低于此 = 被地面吞掉
SMALL_TURN_FAIL_BATCHES = 2   # 连续多少批失效才升级大转（单批噪声不误判）
SMALL_TURN_MAX_STEPS = 6      # 一轮小转批量上限
BIG_TURN_THRESHOLD_DEG = 30.0  # 超此角度直接大转（小转批量太慢）
BIG_TURN_OSC_ACCEPT_DEG = 15.0  # 大转振荡时接受残余航向差的上限（<半步长）

# =====================================================================
# 定位（Gauss-Newton 地图定位）门控
# =====================================================================
GN_MAX_ITERS = 10
GN_PIXEL_GATE = 12.0      # 单帧解残差 RMS 上限（px；裁切观测噪声 ~2px，留裕量）
GN_PIXEL_GATE_MERGED = 15.0  # 头部扫合并帧的残差上限（斜视角中心偏差更大）
GN_OUTLIER_PX = 25.0      # 单点残差超此剔除后重解（误检防护；勿把裁切点剔光）
GN_JUMP_CM = 12.0         # 解算位姿相对预测的最大跳变（预算+裕度）
GN_JUMP_DEG = 30.0        # 最大航向跳变
GN_CAUCHY_C_PX = 4.0      # IRLS 鲁棒核尺度（px）：大残差（裁切野值）近零权重
GN_PRIOR_SIGMA_XY_CM = 8.0    # 弱先验正则（cm）：低观测时抑制位姿乱跑
GN_PRIOR_SIGMA_TH_DEG = 8.0   # 弱先验正则（度）
GN_RMS_OK_PX = 3.0        # 多起点早停阈值：RMS 已足够好就不再试其它起点

# =====================================================================
# 视觉伺服导航 v3（2026-09-11：抗地板形变，导航不依赖相机常数）
# =====================================================================
# 现场约束（用户）：本关地板会形变，机器人在板上行走时机体俯仰/相机高度会
# 大幅变化（按 ±15° 考虑）。量化：h=50cm、竖直半视场 26.8° 时，有效俯角
# 42°/57°/72° 的可见地面带分别是 19~184 / 5~86 / 0~50 cm（4 倍范围摆动）
# —— 任何"冻结相机常数的度量投影"（GN 地图定位、"位姿覆盖中心"判据）在这种
# 形变下都不可用（sim 实测：随机游走 ±15° 时旧导航 0/7）。
# 故导航主链改为**相对量视觉伺服**（做法同参考实现
# reference code/九宫格视觉导航：yaw=-(dx/W)·FOV、proximity=框宽、
# 到达=低头颜色"出现→消失"）；地图（布局扫结果 digit_cell + 动作模型死推位姿）
# 只用于"往哪个方向找目标"的粗提示（±30° 足够）与每格到达后的位姿重置。
VIS_NAV_ENABLED = True          # False → 退回 v2 地图路径（现场应急开关）
USE_MAP_CORRECTION = False      # True → 每格尝试一次地图 GN 校正（失败只打日志）
CAMERA_FOV_H_DEG = 60.0         # yaw = -(dx/W)*FOV：**伺服增益**，不是角度标称值
# ★ 关于 yaw 的正确认识（2026-09-24 定稿，此前一轮走过弯路，勿重蹈）：
#
#   `yaw` **不是**一个可信的角度数值，而是"横向像素偏移"换来的**伺服误差**，
#   单位只是"名义度"。它与真实相机方位角的比值实测 ≈ **0.734**
#   （20cm 处 0.696、55cm 处 0.752、130cm 处 0.719 —— 随距离缓变）。
#   成因：名义 FOV 60° ≠ 真实 2·atan(1296/1944.9)=67.36°，且用线性代替 atan。
#
#   为什么**不要**去"修正"它：
#   闭环在零点处两套公式同为零 ⇒ 收敛点不受影响；而这个 0.734 倍率事实上是
#   **整族 yaw 域阈值共同的隐含增益标定**（死区 VIS_ALIGN_TOL_DEG、
#   大转分界 VIS_BIG_TURN_DEG、变差判据 VIS_ALIGN_WORSEN_DEG、
#   改善判据里的 0.5°、小转规划下限 …）。
#   2026-09-24 实测（16 种子、实测原语）把控制侧换成"去畸变+atan"的精确公式：
#       到达 112/112 → **72/111**，真值落点最大 4.3cm → **128cm**，超半格 0 → 35；
#   即使把死区从 12° 补偿到 15/16/17°（对齐线性公式的等效真实角度 16.3°），
#   也只回到 35/48 ~ 43/48（基线 56/56）。⇒ 单独"修准"yaw 会让这族门限互相失配。
#   ⇒ **结论：yaw 保持线性公式，把它当无量纲伺服误差用；不要试图给它标定角度。**
#   若哪天真要用真实角度，必须**整族阈值一起重标**，属独立立项。
#   纯数学对照（供查证）：`tests/test_nine_grid_yaw.py`。
#   相关背景：评审《分区控制律与地图核验方案》Q2 —— "作为伺服增益无所谓（闭环
#   吸收），但不要用它去反推角度数值"。
# 对准死区 = **一个真实动作分辨率**（2026-09-13 真机"在死区里打转"复盘）：
# 现场实测小转一次 ≈10°（目视；打滑本就大，不可能更准），而旧死区收到 3.5°
# **小于一个步长** → 每轮都规划 1 步、每步过冲 6~10°、永远进不了死区：
#     yaw +4° →（转 1 步，实际 -10°）→ -6° →（转 1 步）→ +4° → … 无限振荡
# 6 轮后对准放弃 → 回到搜索再转 → 现场看到的就是"在死区莫名其妙打转"，
# 最后转向叠加盲走把机器人带出场地（2026-09-13 手工重跑实录）。
# 结论：**死区必须 ≥ 一个步长**（12° ≈ 10° + 打滑裕量），不追求度数精度。
# 也试过"用在线单步估计自适应取死区"（clip(1.2×估计, 4°, 12°)）：仿真里小转被
# 地面吞掉后估计崩到 0.8°，死区跟着收到 4° → 与 22° 大转步长严重失配 → 反而
# 把标称场景（无变形的基线）打挂（面板5 未确认）。**现场只有一个可靠数字：
# 小转一步 ≈10°，所以死区就取一个步长，不自适应**。
# 落点精度交给低头段的**厘米级横移纠偏**（VIS_ARRIVE_LAT_VIA_SIDESTEP：
# 2.2cm/步）+ 920px 交棒点——角度的分辨率被机械步长卡死，位置的分辨率没有。
VIS_ALIGN_TOL_DEG = 12.0        # 对准死区（≥ 一个真实小转步长）
VIS_BIG_TURN_DEG = 30.0         # 大/小转角分界（参考 BIG_TURN_THRESHOLD=30）
# **真机小转一步的真实角度（现场目视实测 ≈10°，2026-09-13；带打滑裕量取 11°）**
# 只用于"死区 ≥ 一个步长"这条不变量的自检，**不参与任何控制计算**。
# 为什么单独立成一个常量：现场唯一可靠的数字就是"小转一步多大"，而它决定了
# 死区的下限。详见文件末尾 `_check_align_invariant()`——死区小于一个步长会产生
# "规划 1 步 → 过冲 → 反向再规划 1 步 → 再过冲"的极限环（现场"在死区里莫名
# 打转"+6 轮后对准放弃→回搜索再转）。这条不变量以前只写在注释里，结果死区被
# 改成 3.5°（远小于 10° 的步长）而没有任何东西拦住——现在由代码强制。
FIELD_SMALL_TURN_STEP_DEG = 11.0
# 小转角闭环的规划下限（°/步）：规划步数 n = floor(|yaw| / max(EMA估计, 此值))。
# 为什么需要下限：真机/仿真都出现"小转被地面吞掉"→ EMA 估计崩到 0.3°/次 →
# n 被算成 SMALL_TURN_MAX_STEPS，一次请求 6 步 → 过冲 → 再算 n → 振荡。
# 有下限后最多请求 6 小步（≈12°），且**每轮都重新拍帧复测 yaw**，过冲由下
# 一轮吸收——收敛靠闭环，不靠这个常数准。
VIS_SMALL_TURN_MIN_STEP_DEG = 0.8

# =====================================================================
# 三档分区横向控制律（v3 对准，2026-09-23）—— 默认**关闭**，见 VIS_ZONE_ENABLED
# =====================================================================
# 动机：现行二值判据（|yaw| ≤ VIS_ALIGN_TOL_DEG 就前进，否则转）把"角度分辨率"
# 当成唯一修正手段。但真机小转一步实测是**左 8.625° / 右 5.200°**（runbook §2），
# 死区 12° 对右转只有 2.3 个步长、对左转 1.4 个 ⇒ 一步跨不出去就会
# "转一步过冲 → 反号再转 → 再过冲"，现场表现就是"在死区里打转"。
# 而**横移一步是厘米级的**（实测 2.497 / 2.200 cm/步），精度远好于角度量化。
# 所以把修正手段按精度排成三档：
#
#   ★ 与用户给的图一一对应：
#     绿（直行）= 方位角很小的中央梯形。图像里两腰是直线，而"方位角恒定"
#        对应的正是**过光心的竖直平面** ⇒ 形状必然是上窄下宽的等腰梯形。
#     蓝（横移）= 方位角已明显（> MOVE_DEG）但**够近**，横移才有权威。
#     橙（旋转）= 方位角太大，**或太远** —— 这就是图里蓝/橙之间那条**水平分界线**。
#
#   ★ "够近"用尺度不变量 near = 框宽 / 画幅高，不用像素行：
#     框宽是**投影不变量**（∝1/深度，同 _arrive_visual 的 dx_cm），除以画幅高后
#     无量纲 ⇒ 换俯仰档、地板形变都不改阈值。物理依据：横移一步改变的"跨越偏差"
#     恒为 2.2~2.5cm（与距离无关），但它改变方位角的效果 ∝ 1/距离 ⇒ 1m 外一步
#     只改 ~1.4°，效率极低，该改用旋转。
#
#   ★ 曾试过用"跨越偏差厘米数"当门（off_cm = 像素偏移/框宽×PANEL_WIDTH_CM）：
#     几何上更正确（恒定地面宽度走廊，反投影自检 X 极差 0.0000cm），但**离线
#     实测更差** —— 面板被画幅裁切时框宽只剩可见窄条 ⇒ off_cm 被系统性高估，
#     而现场 74% 的观测是裁切的 ⇒ 过度纠偏。三种阈值组合都没打赢二值基线。
#     故两个门都只用方位角 + near。
VIS_ZONE_MOVE_DEG = 6.0         # 〔旧规则〕方位角 ≤ 此值（度）→ 直行（绿）
VIS_ZONE_ROT_DEG = 12.0         # 〔旧规则〕方位角 ≤ 此值（度）**且够近** → 横移（蓝）
VIS_ZONE_ROT_NEAR = 0.35        # 〔旧规则〕"够近"门槛 = 框宽/画幅高（见 _near_of）
# ---- ★ 现行规则：按用户 2026-09-24 的示意图，**从画面像素直接判档** ----
# 示意图就是相机画面本身：横轴 = 画面左右，纵轴 = 画面上下（下 = 近）。
#   绿（中央梯形，上窄下宽）→ 直行
#   蓝（画面底部两块梯形）  → 横移
#   橙（其余）              → 旋转
# 与旧规则的差别**全在边界形状**：
#   ① 旧规则的边界是**竖直线**（|yaw| ≤ 常数 ⇔ 画面横向偏移恒定 ⇔ 地上"等方位角"
#      的射线束）⇒ 近处只管住很窄一条、远处放得很宽 —— 与图正好反着。
#      图里的边界是**斜线**（上窄下宽）⇔ 地上近似**等宽度走廊**（见下方换算）。
#   ② 旧规则的"够近"用框宽/画幅高（near ≥ 0.35 ⇔ 实测地面距离 ~65cm）；
#      图里蓝区上沿是**一条水平线**，实测换算只有 **~16cm**。
#      ⇒ 用户指出的"还很远就横移"正是这条线画得太高（旧门 65cm vs 图 16cm）。
#
# 五个参数**全部从图里量出来**（tools/_tmp_diagram_measure.py：按颜色分割 →
# 逐行取边界 → 直线拟合 → 在画幅顶边/蓝区上沿/画幅底边求值，化成画幅比例，
# 故换分辨率不用改）：
#   绿梯形半宽  顶边 0.0548 → 底边 0.1199
#   蓝外沿半宽  蓝区上沿 0.2746 → 画幅底边 0.3623
#   蓝区高度    0.2445（从画幅底边往上量）
# 换算成"地上左右差几厘米"（低头档 1040：俯角 59.9°、h=56cm）：
#   绿 = 离中心线 ±6.7cm(85cm 处) ~ ±8.0cm(3.5cm 处) ⇒ 近似**恒定 ±7cm 走廊**
#   蓝外沿 = ±20.7cm(15.9cm 处) ~ ±24.3cm(3.5cm 处) ⇒ 近似**恒定 ±22cm 走廊**
#   蓝区上沿 = 地面距离 **15.9cm**
# 一句话：目标在中心线 ±7cm 内 → 直行；比 16cm 更近且偏在 ±22cm 内 → 横移；
# 其余（偏太多，或既不在走廊里又还比 16cm 远）→ 旋转。
#
# ★ **只决定"做哪种动作"，不决定"做几次"**（用户 2026-09-24 明确）：
#   直行次数按框宽分档、旋转次数按每步实测角算、横移一次一步 —— 都留在原处。
VIS_ZONE_GREEN_TOP = 0.0548       # 绿：画幅**顶边**处的半宽 / 画幅宽
VIS_ZONE_GREEN_BOT = 0.1199       # 绿：画幅**底边**处的半宽 / 画幅宽
VIS_ZONE_BLUE_TOP = 0.2746        # 蓝外沿：**蓝区上沿**处的半宽 / 画幅宽
VIS_ZONE_BLUE_BOT = 0.3623        # 蓝外沿：画幅**底边**处的半宽 / 画幅宽
VIS_ZONE_BLUE_HEIGHT = 0.2445     # 蓝区高度 / 画幅高（从底边往上量）
# ---- 紫区：**只看当前状态**的到达判据（用户 2026-09-24 方案）----
# 示意图底部中央那块紫 = "面板已经在我脚下、而且基本对正"的区域：
#   横向边界 = 绿走廊，**故意绑死**（用户定）：一旦比走廊宽/窄，就会出现
#              "没到位却只能直行"或"该横移却判到达"的死区 —— 对不上得不偿失。
#   高度     = **自己的参数**（用户明确要求）：它决定"多近才算站上去"，
#              不能被蓝区高度（横移范围）带着走。实测教训：共用一个参数时把它
#              调成 0.60（≈脚下 40cm）后，判据在每格离格心 33cm 处就成立了
#              （28 格全部提前成立）；改回 0.2445（≈脚下 16cm）时是 3.0~6.8cm。
VIS_ZONE_PURPLE_HEIGHT = 0.2445   # 紫区高度/画幅高（从底边往上量）
# ★★ 2026-09-25 实测校准（P1 重写）：紫区**必须覆盖"格心附近"那块地面**，
#    否则到达判据在单格预算内**不可达**。
#
# 病：紫区高度沿用示意图量出的 0.2445 ⇒ 紫带上沿只到画幅底边上方约 4cm 地面。
#     低头档 1040 + 相机高 57cm 的实测（目标正前方，逐档量紫/橙份额）：
#        距离 15cm → 紫 0.323（差 0.027）｜12cm → 0.332｜10cm → 0.339｜8cm → 0.365★
#        6cm  → 0.410 但橙 0.103（>0.10 门，**差 0.003 被卡**）｜4cm → 0.468 且橙 0.063★
#     ⇒ 判据只在 **≤4cm** 成立。而"框宽→距离"几乎不可用（实测 70cm=688px、
#       30cm=924px、≤15cm 起裁切饱和在 ~1000px），单步 2.652cm ⇒ 从 40cm 走到
#       4cm 要 ~14 次前进决策，7 格就是 100+ 帧，直接撞 140 张/格上限。
#     旧实现之所以"能到"，是因为它用的是**旧到达判据**（色占比回落，峰值出现在
#       离格心 14~19cm），而不是这条紫区判据——紫区判据在旧代码里从未当过主判据。
#
# 校准：紫带上沿抬到画幅底边上方 **0.62** ⇒ 覆盖到约 16cm 地面（与旧判据的
#     峰值距离同量级，落在±半格 16.7cm 之内），判据在 ~16cm 处成立，
#     单格只需 ~8 次前进决策。
# ⚠️ 真机复核项：该值由**仿真几何**标定（h=57cm、俯角 59.9°）。现场若相机高度/
#     俯角不同，必须用测量 2（近距剖面）重标——见需求规格 §10 风险 1。
VIS_ZONE_PURPLE_HEIGHT = 0.62
# ---- 到达门的三个份额阈值：全部由实测定（老办法 28 次真到达 vs 5 次假到达；工具
# tools/_tmp_region_ratio.py）。单位 = **目标色像素的份额**：
#   紫区份额：真到达 min 0.446 / 中位 0.621 ｜ 假到达 全部 **0.000** ⇒ 取 0.35
#   橙区份额：真到达 max 0.018 ｜ 假到达 中位 0.707（3 格 0.61~1.00）⇒ 取 0.10
#   左右溢出不对称 |蓝左−蓝右|：真到达 中位 0.099 / P90 0.199 / max 0.251，
#       换算 ≈ 每 1cm 横向偏差对应 0.078 不对称 ⇒ 取 0.25（≈横向 3.2cm）。
#       这一条对应"要站在格子中央才能触发压感"（用户要求），
#       并且是**状态量**：偏心时色块溢到左右蓝区的量不对称，不用任何历史。
VIS_ARRIVE_PURPLE_MIN = 0.35      # 紫区份额下限
VIS_ARRIVE_ORANGE_MAX = 0.10      # 橙区份额上限（色块不该还留在远处）
VIS_ARRIVE_ASYM_MAX = 0.55        # 左右溢出不对称上限
# ★ 2026-09-25 由 0.25 改为 **0.55**（P1 重写；依据是**扫门实测 + 落地精度复核**）：
#
# ① 这个量是**角度量**，不是距离量 —— 同一横偏在不同距离读数差 2~3 倍（实测）：
#      横偏   @4cm   @10cm  @20cm
#       0cm   0.012  0.021  0.012
#       2cm   0.159  0.123  0.069
#       4cm   0.293  0.226  0.125
#       6cm   0.403  0.303  0.169
#    ⇒ 固定阈值天然随距离漂移，"多少算偏心"没有唯一答案。
# ② 它**永远到不了 0.5 以上多少**：面板 28cm 比绿走廊（±7cm）宽，超出走廊的部分
#    全算橙 ⇒ 判据上限被几何压住，0.25 实际只容许 ±1.7cm 横偏，而蓝档把机器人
#    稳定在 ±5cm 量级 ⇒ 到达判据几乎永不成立。
# ③ 扫门实测（3 种子 21 格）：0.25→10/21、0.40→?、**0.55→20/21**、0.70 与 0.55 同。
# ④ 落地精度复核（0.55 + stride 1，3 种子）：落点 [7.0,8.4,6.1,7.4,6.9,10.1,8.8]cm
#    —— **全部 ≤10.1cm**，都在半格 16.7cm 内，且多数在微动开关半宽 5.5cm 附近。
#    ⇒ 放宽不对称门**没有**换来"压偏也判到达"。
# ⚠️ 更正确的做法是用"几何横偏 cm"（由 (机体方位角, 像宽/画幅) 反解，实测误差
#    ~1cm，只差 `col_forward` 的 13px≈0.7° 常数偏置）——留作后续升级，届时这个
#    经验门可以整条去掉。
VIS_ARRIVE_REGION_ENABLED = True  # 统一循环用区域判据；False = 退回旧峰值回落
# 到达门前置条件：目标观测相对**机体系中线**的横向偏移上限（画幅比例）
#   0.12 ≈ 311px @2592（机体系方位角口径 ~7°）—— 与绿走廊的"近处半宽 0.1199"
#   同量级：站在走廊里才允许宣布到达。
#   ⚠️ 设 0 表示关闭该前置条件（仅用于对照实验，不许当默认）。
VIS_ARRIVE_CENTER_MAX = 0.12
# ★ 到达门前置条件二：目标色**整帧占比下限**（目标必须"够大"= 真的压在脚下）
#   为什么必须有（P1 实测定位到的假到达机制）：目标**边缘斜视的残缺投影**会让
#   四个整帧份额全部失真 —— 远侧一半出画幅 ⇒ 橙区拿 0（本该 0.48）、紫区拿 0.637
#   ⇒ 门在离目标 **66cm** 处成立。实测两侧取值：
#       真到达：整帧占比 0.078~0.150（低头 1040，距格心 ≤10cm）
#       骗门帧：0.042
#   取 0.065（两侧都留余量）。设 0 关闭该判据（仅用于对照实验，不许当默认）。
VIS_ARRIVE_MIN_COVER = 0.065
#   ⚠️ 2026-09-25 实测更正：加了下面的形状门之后，本条**已不再是主要约束** ——
#   把 0.065 放到 0.055/0.045/0.020 三档，结果**逐位相同**（24/28、拍照 2386、
#   中位 8.2、最大 10.5、超半格 0）；而**只留形状门**会退化到 27/28 但**超半格 2**
#   （出现 75.5cm 落点）。⇒ 两条门是**互补**的（占比管"够不够大"、形状管"是不是
#   斜切片"），保留两条最稳；本条的具体阈值不敏感。
# 形状门（**实际有效的那条**）：目标观测 bbox 的**宽/高比上限**。
#   标定工具 `tools/_tmp_arrive_gate_probe.py`（把门全放开、逐帧记特征、用真值打标签）：
#       真到达（11 帧）宽/高 **1.53 ~ 2.07**（中位 1.66）
#       假到达（ 5 帧）宽/高 **2.25 ~ 2.49**   ← 全是又扁又斜的残缺投影
#   ⇒ 取 **2.15**。设 0 关闭。
VIS_ARRIVE_MAX_BW_OVER_BH = 2.15
# 邻近门（bbox 宽度下限）：标定出两簇不重叠（真 1158~1336 ｜ 假 272~1106），
# 但**实测在其它门存在时它不增加价值**：1000 与"关闭"结果逐位相同
# （23/28、2464、8.4、10.5、0）；1060/1100 反而把到达率从 23 压到 16。
# ⇒ **默认 0（关闭）**，常量保留供复现这次标定。
VIS_ARRIVE_MIN_BOX_PX = 0.0
# ---- ★ 格的同一性核验（用户方案 ②-a）----
# 到达门那六个量都是**单帧整帧统计**，在"站在别的格子上、看到一块完整且居中的
# 同色面板"时**全部正常**（实测有一帧六量全合规、真值却离目标 100cm）。
# 只有"这一帧的几何能否被地图解释"能分辨 ⇒ 用 `_map_anchor` 解实测位姿后，
# 要求它落在目标格附近。
VIS_ARRIVE_ONCELL_ENABLED = True    # 总开关
# ★ 横向上限（cm）：**单块面板**即可判，不需要锚/对应点集 ⇒ 近距离也稳。
#   实测门成立帧：真到达 2.5~6.5cm（中位 4.7）｜ 假到达 5.3~159.5cm（中位 29.9）
#   —— 单看这两行像是干净可分，**但实际 A/B 是否决 0 次、指标逐位不变**：
#   7 帧假到达里**有 6 帧横向只有 5~12cm**（它们本来就在目标格正下方偏一点，
#   只是**纵向**不在格上），只有 1 帧是 159.5cm 那种离谱值。
#   ⇒ 它只能拦住"横向离谱"的少数情形，**不是主判据**；默认 **0（关闭）**，
#   常量保留以便需要时显式开启（会拦住极端的横向错位）。
VIS_ARRIVE_LATERAL_MAX_CM = 0.0
# 头部扫（凑对应点用）：中位解不出锚时依次试这些头部档。
# 依据：对应点数强烈依赖头部档（实测站在格心低头档：cell0 中位2/右6；
#       cell3 中位5/右9；cell8 中位7/左10）⇒ 换个头部档常能凑够 ≥5 对。
# **只动头部、不动身体** ⇒ 位姿与几何不变，锚解出的位姿与到达时刻可比。
# ⚠️ **默认置空 = 关闭**：实测（8 种子）开启后拍照 613→**632/局（+19）**，
#    而到达/中位/最大/超半格**逐位不变**（46/56、8.5、10.8、0）⇒ 花了帧没换来收益。
#    机理：核验路径上"色块判据成立"的帧本来就少（整局 6 次量级），
#    且这些帧的**真值都在半格内**（不是假到达），所以多解出几次锚也无从否决。
#    ⇒ 保留实现与常量以便复现/A-B，但**不进默认**。
VIS_ARRIVE_ONCELL_HEAD_SWEEP = ()
VIS_ARRIVE_ONCELL_TOL_CM = 16.7     # 距格心容差（= 半格；压感区半宽 5.5cm，
#                                     但锚本身有位姿误差，取半格更稳）
VIS_ARRIVE_ONCELL_REQUIRE = False   # 锚**不可用**时是否也拒绝
#   False（默认）= 诚实弃权：锚解不出来就按老规矩放行。
#   理由：锚的可用率实测只有 ~15.8%（整关），若设 True 会把大量正常到达一起误杀。
#   设 True 只在"宁可不判到达也不要假到达"的场合用（需配 A/B 数据）。
# 旧的"高/宽比下限"（0.46）：**方向不对，已废弃**（只挡掉 5 帧假到达里的 2 帧）。
# 保留常量与说明仅为记录这次更正，默认 0 = 关闭。
VIS_ARRIVE_MIN_ASPECT = 0.0
# 替代判据（**实测更差，默认关闭**）：目标观测的凸包面积下限（原生 px²）。
#   真到达 418288 ｜ 骗门帧 210950（差 2 倍，看着更干净），但实测**反而更差**：
#   超半格 5、出现 78~80cm 落点 —— 因为同一色面板在**邻格**被近距离看到时 hull
#   同样很大，面积判不出"是不是脚下这一块"。保留常量只为可复现那次否证。
VIS_ARRIVE_MIN_HULL_AREA = 0.0
VIS_ZONE_PX_ENABLED = True               # True=用上面五参数；False=退回旧三阈值（对照用）
# 来源一：**整关仿真 + 实测运动原语**的 36 组网格扫描（tools/_tmp_zone_eval.py
#   --sweep，4 局共 28 格）。基线（二值 12° 死区）到达 21/28；全场最优即本组
#   6.0/12.0/0.35 → **27/28**（动作 705→911，拍照 1126→1168）。
#   次优 6/12/0.5 与 6/18/0.5 都是 26/28 但动作更少（~740）。
# 来源二：运动学级对照（tools/_tmp_zone_sim.py，50 组初值网格）。
#   那里 6/18/0.35 最好（31/50 vs 基线 25/50），与整关仿真不一致——因为运动学
#   模型没有"接近/到达"两段与识别噪声。**以整关仿真为准**（它的口径更接近真机）。
# 二值律的失败**残余都在 150~170cm**（方向搞反后一路转出去），分区律把大部分
# 救回来（残余降到 3~7cm）——横移档的价值：它不靠"转对方向"吃饭，只靠"看目标
# 偏在哪边就往哪边挪"，对方向标定免疫。
VIS_ZONE_ENABLED = False        # False → 完全走原二值死区路径（默认，见下方理由）
# ---- 迟滞（2026-09-24 新增，评审 Q3/§6.6 要求）----
# 作用：**省拍照**，不是防发散。每次分区切换 = 一次决策 + 可能一次拍照（0.7s）。
# 做法：**只放宽"离开"条件，不放宽"进入"条件**——
#   进入窄区（move）仍要求 |yaw| ≤ VIS_ZONE_MOVE_DEG；
#   已经处于 move 时，要 |yaw| > VIS_ZONE_MOVE_DEG + VIS_ZONE_HYST_DEG 才离开。
# 这样切换频率降为原来的 1/(1+HYST/带宽)，而"进入"语义不被污染。
# 取 2.0°：一个真实小转步长是 5.2~8.6°，迟滞小于一个步长就等于没有迟滞；
# 取太大（>半步长）会让窄区实际变宽、把 6° 门悄悄改成 9°。2° 是"能吸收
# 单帧噪声、又不改变门的名义值"的最小可用量。
VIS_ZONE_HYST_DEG = 2.0
# ---- 收尾段禁用旋转（2026-09-24 新增，评审 Q3/§6.7 硬要求）----
# 定量理由（现场实测）：小转一步 = 左 8.625° / 右 5.200°；画幅中心 1° ≈ 34.2px
# ⇒ 一步 = 295 / 177 px；295px 在 Z=64.5cm 处 = **9.8cm**，而本关微动开关
# 有效区只有 **±5.5cm** ⇒ **靠旋转永远无法把落点做进开关区**。
# 落点精度只能来自厘米级横移（2.2~2.5cm/步）。因此当目标已"够近"
# （near ≥ VIS_ZONE_ROT_NEAR）时，把 'rot' 档降级为横移档；远离时旋转仍然有效
# （旋转步长与深度无关，远距横移几乎没有权威——评审 Q3 条件 3）。
VIS_ZONE_NO_ROT_TAIL = False    # 默认关闭：先做成可 A/B 的开关，按实测决定

# =====================================================================
# MAP-ANCHOR：地图锚定的逐帧自标定（2026-09-24 新增）
# =====================================================================
# 用户构想 ②：**"对照 map 核验识别结果"**。要把它做成非退化的判据，关键是
# 换一个提法——**地图不是待拟合的未知量，而是假设**：
#
#   地图说"数字 d 在格 c"（`digit_cell` 是组合信息，不是位姿）；
#   本帧又看到 d 在像素 p。于是得到对应 (格心_c → p)。
#   用 **RANSAC** 在这批对应上求共识：
#     内点 = 与地图相容的识别结果；
#     外点 = **明显违背地图**的识别结果（用户说的"不是偏差，而是对不上"）。
#
# 这一步同时解出**本帧真实位姿与真实相机高度**，因为 `GroundHomography` 的
# 分解本来就给出相机中心：**不需要任何冻结的相机常数** ⇒ 天然抗地板形变。
# 本轮数值实测（`$TEMP\ng_anchor_probe.py`）：
#   · 观测质心加 2px 噪声 ⇒ 位姿误差 0.24cm，反解相机高度 56.1cm（真值 56.0）
#   · **真实相机常数与标称完全不符**（h=41 而非 56、俯仰偏移 +15°）
#     ⇒ 位姿误差 **0.08cm**，反解高度 **41.1cm**
#   · 9 对点里注入 1~2 个假货 ⇒ 外点残差 29~215px、内点 ≤3.6px，**全部抓对**
#
# ★★ 但**可用性很窄**，必须如实说明（本轮整关仿真实测，见方案文档 §1.5）：
#   每格开始时在 HEAD_CENTER+PITCH_NAV 拍一帧，"未裁切且在 map 里"的面板数
#   逐格是 7,1,0,0,1,0,0（只有第一格站在场外时才有 7 个）；全帧口径
#   **≥4 的帧只占 9~18%，≥5 的只占 3~5%**。原因：压到上一格后邻格只有
#   33cm ⇒ 投影像宽 >1600px 被画幅裁切；更近的还会被检测器的
#   MAX_AREA_FRAME_FRAC=0.35 当 "too_big" 整块丢弃。
#   ⇒ **MAP-ANCHOR 是"长距帧的核验/定位器"，不是全程可用机制。**
#   ⇒ 锚不可用时**必须诚实弃权**（返回 None），绝不用退化输入硬解。
MAP_ANCHOR_ENABLED = False      # 总开关（默认关：可用率只有 9~18% 的帧）
MAP_ANCHOR_REPORT_ONLY = True   # True = 只算、只记遥测，不改变任何决策
MAP_ANCHOR_MIN_PTS = 5          # 参与解算的最少对应数（4 能解但无法核验且会退化）
MAP_ANCHOR_MIN_INLIERS = 5      # 共识下限（**不是 4**）：4 点单应是恰定解、自身残差
                                # 恒为 0、没有任何冗余 ⇒ 既无法核验、数值上也会
                                # 外推出荒谬解（实测 4 点时 `ground_pose()` 直接抛
                                # "相机未俯视地面"）。5 点给出 2 个残差自由度。
MAP_ANCHOR_INLIER_PX = 6.0      # 内点门限（原生 px）；内点实测 ≤3.6px、外点 ≥29px
MAP_ANCHOR_H_RANGE_CM = (25.0, 90.0)   # 反解相机高度的合理区间
MAP_ANCHOR_COL_DIFF_MAX = 0.05  # H 前两列模长相对差上限（真单应的性质）
MAP_ANCHOR_POSE_TOL_CM = 60.0   # 反解位姿离场地中心的最大允许距离（荒谬解守卫）
MAP_ANCHOR_MAX_COMBOS = 80      # 4 子集枚举上限（C(9,4)=126 → 抽稀到 80）
# 裁切面板角点判据：`hull_poly` 顶点距画幅边 ≥ 此值（原生 px）才认为是"真角点"。
# 取 12：detector 的贴边判据是 work 分辨率 8px × scale(≈2) = 16 原生 px，
# 这里取略小一点，宁可多收一个顶点（错的那个会被 RANSAC 判为外点）。
MAP_ANCHOR_CORNER_MARGIN_PX = 12.0
# ★ 为什么默认关闭：
#   2026-09-23 实测（tools/_tmp_recalib2.py，8 局 56 格）：在**实测运动常量**下
#   分区律与二值判据的到达数完全相同（42/56 / 40/56 / 45/56，三组配置各自
#   逐位相同；默认常量的整关仿真也都是 7/7、206 拍照、176 动作）。
#   ⇒ **分区律目前没有可测出的增益**，所以不给它改默认行为。
#
#   ★ 已排除的两个"假原因"（都曾是本开关关闭的理由，现已作废）：
#     ① "收益只在实测常量下体现 / 49-56 vs 54-56" —— 那个旧对照**无效**：
#        tools/_tmp_recalib.py 没接管 `_zone_of`，两次跑的是同一条路径。
#     ② "中间档不可达" —— **确实发生过，已修**：`_approach_visual` 的快捷判据
#        原写死 `abs(yaw) <= VIS_ALIGN_TOL_DEG(12°)`，在咨询分区之前就放行前进，
#        导致 yaw 落在 6~12°（蓝档该生效的区间）时 `_zone_of` 根本没被问到
#        （实测：返回 'lat' **0 次**）。改成走同一套 `_zone_of` 后，'lat'
#        25 次 / 'move' 12 次 / 'rot' 45 次，中间档可达。
#        修完后默认路径仍逐位不变（7/7、206、176），75 个测试全绿。
#
#   另一条并行阻塞（未解决）: 把关卡运动常量换成实测值（Hindsight 记的冻结矩阵
#   2.652 / 8.625 / 5.2）后，仿真基线从 7/7 掉到 5/7；扫了 17 组规划常量
#   （tools/_tmp_recalib.py）最好 20/21（种子3/7/11），8 种子口径 42~45/56，
#   仍不如名义常量的 49/56。所以那一步也不该现在做。
#
#   ⇒ 下一步该做的是"**让分区律有增益**"，而不是继续调它的阈值：目前它发出的
#     横移动作与到达段自己的厘米级纠偏（VIS_ARRIVE_LAT_VIA_SIDESTEP）功能重叠，
#     所以看不出差别。要么把到达段的纠偏收进分区律统一调度，要么让分区律承担
#     到达段目前做不了的事（例如远距离的低效横移改用旋转）。
#
#   ⚠️ **已解（2026-09-24）**：原记录"扫 VIS_ZONE_ROT_NEAR ∈ {0.35,0.0,0.5,0.9,9.0}
#     结果逐位相同，而 'lat' 确实执行了 25 次/局 ⇒ 该对照装置可疑"——**装置没问题**，
#     'lat' 计数随阈值变化是 63/67/11/0；无差异的真正原因是**蓝档动作是死代码**：
#     `_align_visual` 旧的首判据是 `abs(yaw) <= VIS_ALIGN_TOL_DEG or (...)`，
#     |yaw| 落在 6~12°（蓝档该生效的区间）时第一个析取项已经成立 ⇒ 函数立刻
#     "已对准"返回 ⇒ 后面的横移档（`_act`）**在数学上不可达**（走到那里必须
#     |yaw| > 12°，而那时 `_zone_of` 只会给 'rot'）。全部 'lat' 都来自
#     `_approach_visual` 的"咨询"，咨询完就把结果丢了。
#     **e43a803 只打通了 APPROACH 段的咨询，ALIGN 段（本函数首判据）没打通。**
#     实测：开启分区后 2 局 14 格里 `_act` 的动作计数与关闭时**逐项完全相同**
#     （`tools/ab_ninegrid.py --arms zone_off zone_on`）。
#     已修：首判据改为统一走 `_zone_of`，见下方 `_zone_of_h` 与 `_align_visual`。
#   ⇒ **推论**：`VIS_ZONE_MOVE_DEG/ROT_DEG/ROT_NEAR` 的标定结论（36 组扫描
#     21/28→27/28、`_tmp_zone_sim.py` 的运动学级结论）**不能**作为"分区律有用/
#     无用"的证据——蓝档从未执行过。要下结论必须用 `tools/ab_ninegrid.py`
#     重跑（它带活性断言，会拒绝"两臂计数相同"的无效对照）。
#   相关复算脚本：tools/ab_ninegrid.py（入版本库）/ _tmp_recalib.py / _tmp_recalib2.py

PANEL_WIDTH_CM = 28.0           # 色块宽（像素↔厘米换算基准；与 PANEL_HALF_CM 同源）
# 到达触发：目标框宽（px）——"目标已进入 ~35cm"的**相对深度**代理
# （2026-09-11 由 820 收紧到 920，真机"踩不到微动开关"的根因之一）。
# 换算（针孔 + 沿轴深度）：box_px ≈ fx·W / Z，Z = d·cosθ + h·sinθ
#   fx = 1944.9px（camera_config 内参）、W = 28cm（色块宽；33cm 格含缝，
#   现场口径"面板 33cm"含缝，用 33 算只差 15%）、θ = 有效俯角
#   （pitch1200 = 名义27° + 安装18.5° = 45.5°）、h = 相机高 56cm
#   （camera_config 现值 = 现场双帧拟合 + 布局扫运行时自标定；用户口径的
#    39cm 是该文件的**历史粗值**，按 39 算 Z 会小 22cm、框宽虚大 ~40%）。
#   目标在 35cm 处：Z = 35·cos45.5° + 56·sin45.5° = 24.5+39.9 = 64.4cm
#   → 28cm 色块跨视轴的像宽 ≈ 1944.9×28/64.4 = 845px；实测 918px（色块自身
#   有沿轴尺寸 + 斜视投影 + 径向畸变，实测比针孔估算大 ~8%）。
# 实测（sim，目标正前方、h=56cm、安装偏移 18.5°，pitch1200 正对色块 bbox 宽）：
#   60cm→744  50cm→810  45cm→845  40cm→880  35cm→918  32cm→940
#   30cm→956（≤30cm 起 bbox 贴画幅下沿被裁切，框宽饱和失真 → 不能再细）
# 取 920px ⇔ ≈35cm（离裁切拐点 32cm 还有 2cm 裕量）：
#   - 旧值 820px ⇔ ≈48cm，交棒太早 → 低头段还得盲推 ~50cm 才压到格心，
#     这 50cm 里横向偏差没人纠（旧代码只在"从未见到颜色"时纠横），
#     压过去时偏半个开关区是常态 —— 这就是"踩不到按钮"；
#   - 35cm 交棒把盲推距离砍掉 ~13cm，且 pitch1040 在 34cm 处色块仍完整可见
#     （实测 box 902px、占比 0.0996、未裁切），低头段一开始就有视觉反馈。
# 框宽不是精细距离（近距接近饱和），精细到达仍由低头颜色"峰值→回落"判定。
VIS_ARRIVE_BOX_PX = 920.0
VIS_BATCH_MAX_STEPS = 5         # 远距批量上限（5×2cm=10cm，仍是小步幅）
# 低头到达判据（**尺度无关**版本，2026-09-11 实测重设计）：
# 参考实现用每色绝对占比阈值（0.002~0.17），但我们的相机俯角大、色块占比峰值
# 只有 ~0.13（实测红1：0.047 → 峰值 0.130 → 0.015），照抄阈值会永远判不到
# "看到"。改为记录**本次接近的占比峰值**：峰值超过绝对下限后，占比跌到峰值
# 的 VIS_COLOR_DROP_FRAC 以下即判"已压过"——与颜色/光照/俯仰无关。
VIS_COLOR_SEEN_MIN = 0.02       # "看到过颜色"的绝对下限（防噪声）
VIS_COLOR_DROP_FRAC = 0.55      # 占比跌破峰值的此比例 → 判定压过该格
# ---- 前压到底的兜底回落判据（2026-09-24 新增，默认关闭）----
# 病因（真值位姿逐帧对齐实测，见方案文档 §1.2.1）：PITCH_DOWN 的实际俯角是 59.9°，
# 画幅下沿对应地面 **3.5cm** ⇒ 站在 28cm 面板中心时远侧那一半**仍在画面里**
# ⇒ 占比只能降到峰值的 **0.67**，**永远到不了 0.55**；于是前压封顶 45cm、
# 死推兜底又没接住 ⇒ 本格记未确认（seed 11 面板1 真值离格心仅 3.5cm、
# seed 7 面板2 仅 4.1cm，两次都是这个签名）。
# 处置：**不动 0.55 的名义值**（它管的是"色块真的消失"），只在"前压预算已经
# 用掉 VIS_ARRIVE_TAIL_PRESS_FRAC 以上、占比也真的回落了一大截"时再放行一次。
# 这样既不提前停（不牺牲落点精度），又能把"已经站到格心上却判不出来"救回来。
# 取 0.75：比可达下限 0.67 留 8 个百分点的裕量；比峰值低 25% 才算"真的在回落"。
# 取 0.80（16 种子实测最优，且比 0.75 更好）。**已设为默认**（唯一一处改默认行为的
# 改动）：见下方 A/B 实测表——它在**每一个**指标上都优于 0.55 基线，包括落点精度。
#   ┌ 口径 ──────────────┬ 到达 ──────┬ 拍照 ─┬ 落点中位 ─┬ 落点最大 ─┬ 超半格 ┐
#   │ 实测原语 16 种子 0.55│ 87/111     │ 3446  │ 2.6cm     │ 38.8cm    │ 4      │
#   │ 实测原语 16 种子 0.80│ **111/112**│ 2946  │ 2.8cm     │ **11.3cm**│ **0**  │
#   │ 名义原语 4 种子  0.55│ 22/28      │ 1132  │ 2.4cm     │ 45.0cm    │ 3      │
#   │ 名义原语 4 种子  0.80│ **28/28**  │ 767   │ 3.0cm     │ **8.8cm** │ **0**  │
#   └─────────────────────┴────────────┴───────┴───────────┴───────────┴────────┘
# 它只可能"救回"已经站到格心上却判不出来的那些格：判据要求前压已用掉 90% 预算，
# 因此**不会提前停**。唯一的代价是落在 5.5~8.8cm 区间的格从 5 个变成 7 个
# （都仍在半格内，且原本那 5 个里有 3 个是 16.7cm 以上的灾难落点）——这一条
# **必须真机复核**（仿真不建模微动开关，行程余量只能现场量）。
# 一键回退：把 `VIS_ARRIVE_TAIL_ACCEPT_FRAC` 改回 `0.0`。
VIS_ARRIVE_TAIL_ACCEPT_FRAC = 0.80   # 0 = 关闭（旧行为，逐位可复现）
VIS_ARRIVE_TAIL_PRESS_FRAC = 0.9     # 前压达到 PRESS_MAX_CM 的此比例后才允许兜底
# 实测（sim 红1/紫6 等）：占比曲线 0.06 → 峰值 0.13 → 平稳回落；取 0.55 是
# "跌掉 45%" 的保守证据，同时避免机器人刚好停在峰值附近时判不出来。
VIS_ARRIVE_MAX_ITERS = 30       # 低头段迭代上限（时间预算护栏）
# 迭代上限与"分段前压"对齐：前压封顶 45cm、精压段 2cm/帧 → 最多 23 帧，
# 再加 VIS_LAT_MAX_CORRECTIONS(3) 次纠横帧 + 首帧 = 27 ≤ 30，够用不空转。
# ---- 分段前压（2026-09-11 真机"踩不到微动开关"根因，重设计） ----
# 旧实现的收尾是"一次死推兜底"：低头段迭代走完就直接看死推距离（≤15cm 即
# 判成功）。它有三个毛病：① 15cm 已经大于微动开关有效区（±5.5cm）；② 这段
# 盲推里**横向偏差不纠**（旧代码只在"从未见到颜色"时纠横，而交棒时颜色早就
# 见到了）；③ 段中不复查颜色，压过头/没压到都看不出来。
# 改为**分段前压 + 每段复查占比峰值**：每段只压 2~6cm，段间必拍一帧复查
# （占比跌破峰值 → 立即判到位；占比还在涨 → 继续压；横向偏差超容差 → 先
# 小幅纠横再压）。总前压距离封顶 VIS_ARRIVE_PRESS_MAX_CM。
#
# ★ 2026-09-24：45 → **60cm**（本轮最大的一处收益，实测驱动，见方案 §1.2）。
#   旧值 45cm 的推导（"交棒 ≈35cm + 面板半径 14cm ≈ 44cm"）漏了一件事：
#   **占比峰值稳定出现在离格心 14~19cm 处**（36 次真值几何实测，中位 16.1cm），
#   而不是在格心上；峰值之后还要再走完这 16cm 才能到格心。交棒实测在 45~48cm，
#   于是 45cm 预算**恰好在格心处用尽**，判据以 0.4%~3.7% 之差漏判（占比谷值/峰值
#   实测 0.551/0.571/0.608 vs 要求 <0.55）⇒ 本格记未确认 ⇒ 重搜 ⇒ 盲走 39~42cm
#   ⇒ 落点变成 45cm。**"压不到位"是假象，机器人其实每次都压到格上了**
#   （最近真值距离 0.77 / 3.93 / 0.84cm）。
#   60cm 依据：交棒 ≈48cm + 峰值后行程 ≈16cm ≈ 64cm，取 60 并保留
#   VIS_ARRIVE_PRESS_PLAUSIBLE_CM=70 这道"越界一整格"的上限不变
#   （60cm 前压自 48cm 交棒起算 = 越过格心约 12cm，仍远在 33.3cm 格内）。
#   实测（tools/ab_ninegrid.py）：
#     实测原语 16 种子 87/111 → **112/112**，拍照 3446→2828，落点最大 38.8→4.3cm；
#     名义原语  4 种子 22/28  → **28/28**， 拍照 1132→892， 落点最大 45.0→5.7cm；
#     超半格落点 4/3 → **0/0**。
VIS_ARRIVE_PRESS_MAX_CM = 60.0
VIS_ARRIVE_PRESS_COARSE_STEPS = 3   # 占比还在涨时每段步数（3×2cm=6cm，赶路）
VIS_ARRIVE_PRESS_FINE_STEPS = 1     # 到峰/过峰后每段步数（2cm，精压）
# ---- 到达证据门（2026-09-13 假到达根因修复，语义修正） ----
# 背景（真机"到 2 之后找 3 异常"的正解所在，实测复现）：形变阶跃 +15° 场景里
# 面板 3 **在离格心 89.5cm 处被判"到达"**。抓到的当帧证据是：
#   ratio 0.0419 →（连续 3 帧）→ 0.0088  ⇒ 跌破峰值 55% ⇒ 判"压过"
#   而那个"色块"观测是：clip、bbox 1100×380、hull 210162 —— **h/w = 0.35**，
#   它只是恰好擦过画幅下沿的**细长条**，随后被 2 次横移推出画幅。
# 也就是说：**"占比峰值→回落"描述的只是"整帧该颜色像素变少了"**，而颜色变少
# 有三种完全不同的物理原因（① 机器人真的压过；② 目标从画幅侧边滑出；
# ③ 另一个同色面板/地板色块离开视野），旧判据把 ②③ 也当成了 ①。
# 修法：**"压过"必须由一次"面板级"的视觉证据支持** —— 即本次接近里至少有一帧
# 看到过一块**形状与尺度都像面板**的同色区域（不是擦边条）。
# 门限取值（三场景全量实测，见 tools/diag_arrive.py 的"证据"列）：
#   合法到达（BASE/RW/STEP 全部确认格）: 峰值帧色块/画幅 ∈ [0.118, 0.184]
#   唯一的假到达（STEP 面板3）          : 峰值帧色块/画幅 = 0.042（h/w = 0.35）
# 取 0.08 = 落在分离带中间，两侧各留 ~2 倍余量（首版取 0.12 会把合法值 0.118
# 误杀——**这个值必须贴着实测下界取，不能"取个好看的整数"**）。它是**投影
# 不变量**（不依赖光照、不依赖相机俯仰、不依赖位姿），所以抗形变。
# 为什么用"峰值帧的面板面积"而不是"当前帧的形状"：机器人**真正压上去**时
# 色块面积会大到 12~18% 画幅，这一点与光照无关；而"形状"在临门那几帧会退化
# 成画幅下沿的粗边（实测 clip、h/w 0.29~0.46），拿形状当判据会把合法到达
# 一起误杀（首版就踩了这个坑）。所以证据取**占比峰值那一帧**的面板级面积：
# 语义上与"峰值"同步，尺度上不引入新依赖。而"当前帧是不是擦边条"只用来否决
# **横移控制**（见 _arrive_visual）——擦边条的凸包质心不是面板中心的合理估计。
VIS_ARRIVE_EVIDENCE_MIN_ASPECT = 0.5   # 证据区域的 h/w 下限（擦边条 ≈0.35）
VIS_ARRIVE_EVIDENCE_MIN_COVER = 0.08   # 证据区域面积占画幅比下限（假到达 0.042）
# ★ 2026-09-23 修正：上一条只对**未裁切**观测生效（见 _arrive_visual 的用法）。
#   理由（真值集量化，tests/fixtures/nine_grid_truth 的 73 条）：
#     真面板 h/w 实测跨度 0.222~2.989，其中 **17/68（25%）落在 <0.5**；
#     而这 17 条里有 **15 条是 clip==1**（被画幅裁切）。
#   裁切后的 bbox 量的是"可见残片"而不是面板，拿它算长宽比没有意义——
#   一块真面板被下沿切掉大半，可见部分自然又宽又扁。
#   原来的用法（一律拿 bbox 的 h/w 判"是不是擦边条"，判到就**跳过横移纠偏**）
#   会让这 15 条真面板在该纠横时不做纠横，一路盲压。
#   改法：只对未裁切观测做擦边条判定。裁切观测保留原有的"质心不可信"保护
#   （它本来就只对**未**裁切观测改用 center_px，见下方 px 的取法），
#   所以这里放开不会把"用擦边条质心做横移"那个历史 bug 放回来。

# 前压物理合理性上限（与视觉判据**独立**的第二道防线）：交棒 ≈35cm（见
# VIS_ARRIVE_BOX_PX）+ 一格 34cm ≈ 70cm —— 一次接近里前压超过这个距离，说明
# "落下去的"是更远处的东西，不是目标被压过。它只用**本格内累积的前压量**
# （每格到达后 _reanchor_pose 重置，格内只累积几步 2cm 的模型误差），
# 因此**不受长期位姿漂移影响**，可以放心用来否决视觉判据。
VIS_ARRIVE_PRESS_PLAUSIBLE_CM = 70.0
# 死推兜底（15/12cm → 6/5cm）：只在**分段前压已执行完**之后使用。判据收紧到
# 微动开关真实有效区：面板 33cm 的中心 2/3 ≈ ±5.5cm；蹭步（back3.2+forward2.0）
# 净 -1.2cm，故纵向 ≤6cm、横向 ≤5cm 才算"蹭步后仍能压到开关"。旧值 15cm 会把
# "离格心 15cm"也判成到位（真机现象：日志判成功、按钮没响、白丢 10 分）。
VIS_ARRIVE_FALLBACK_CM = 6.0    # 视觉判据走不完时，死推距离兜底（纵向 cm）
VIS_ARRIVE_FALLBACK_LAT_CM = 5.0   # 同上（横向 cm）
# 死推到位即停压（2026-09-13 形变阶跃场景新增的**第二个独立判据**）：
# "颜色峰值回落"在相机俯仰被地板形变改掉时会失效（deform 阶跃 +15° 实测：
# 前压 44cm 占比仍不回落 → 该判据根本发不出声），而**格内相对死推距离**
# （每格到达后由 _reanchor_pose 重置，格内只累积几步 2cm 的模型误差）与俯仰
# 无关。任一判据成立即判到位，遥测里写清是哪一条（诚实遥测）。
# 取 2.0cm：蹭步 = back3.2 + forward2.0（净 -1.2cm），停在格心前 2cm、蹭步后
# 再退 1.2cm ⇒ 落点 ≈ 格心 -3.2cm，仍在开关有效区（±5.5cm）内。
VIS_ARRIVE_STOP_FWD_CM = 2.0
# ★ 2026-09-24 实测（WS2）：上面这两条**死推**判据在当前默认下**从未触发过**
#   （16 种子 112 格：`stop` 0 次、`fallback` 0 次）——到达总是先由色占比判据
#   （含前压兜底）解决。它们只在旧配置（`PRESS_MAX=45` + 兜底关）下才发声：
#   4 种子 28 格里命中 3 次，其中 1 次真值落点 17.4cm（假到达）、2 次 ≤0.6cm。
#   ⇒ 结论：**保留它们作为"视觉全盲"时的最后手段，但不改行为**（改了也测不出
#   差别，属不可观测改动）。命中事件与"命中时的真值落点"已进遥测
#   （`_dr_hits` / `_dr_hit_landing`，见 `_note_dr_hit`），供现场复核。
#
# ---- 几何到达判据（WS4，2026-09-24 新增；默认关）----
# 在低头段每 VIS_ARRIVE_ANCHOR_EVERY 帧用 MAP-ANCHOR 解一次**实测位姿**，
# 直接判 `‖实测位姿 − 目标格心‖ ≤ VIS_ARRIVE_ANCHOR_TOL_CM`。
# 它不依赖色占比（B3 已证其几何前提在 PITCH_DOWN 下不成立），也不依赖死推
# （B1 已证其可靠窗口只有 ~7 个动作、而到达段要 30~50 个动作）。
# 前置条件：MAP-ANCHOR 在**近距离**也要可用 —— 这正是 WS3 角点升级要解决的
# （≥4 对应的帧 14.7% → 46.1%）。开关默认关，按 16 种子 A/B 决定。
# 注意算力：ARRIVE 段每次锚要多做一次**全色** detect_panels。
# **2026-09-24 真机实测**（tools/measure_frame_cost.py，RPi5 上）：
#     拍照 0.572s ／ 色占比 0.043s ／ 单色检测 0.050s ／ **全色检测 0.089s** ／
#     锚解算 0.040s（10 个对应点；RANSAC 在 80 子集处封顶，恒 ~0.04s）
#   ⇒ **全色只是单色的 1.8×（不是 7×：公共的降采样/光照归一化/HSV 才是大头）**；
#     每 3 帧一次 ⇒ 每帧只多 0.043s（+6.8%）。单格 70s 可拍 98~110 帧，
#     而实际单格最多 ~40 张 ⇒ **算力不是瓶颈**（拍照本身占每帧的 90%）。
VIS_ARRIVE_ANCHOR_ENABLED = False
VIS_ARRIVE_ANCHOR_TOL_CM = 5.5      # 微动开关有效区半宽
VIS_ARRIVE_ANCHOR_EVERY = 3         # 每 k 帧锚一次（算力节流）

# =====================================================================
# 三档分区 ＋ 统一决策（★ 用户方案，2026-09-24 实现；默认关，待 A/B）
# =====================================================================
# 用户澄清的四个概念（不能混为一谈）：
#   老办法   = 二值：对准了就直行 / 没对准就转
#   三档分区 = 看目标落在画面哪个区域 → 直行 / 横移 / 旋转
#   三阶段   = 对准 → 接近 → 到达，**三段各有各的切换判据**
#   统一决策 = 不分三段，用同一套逻辑一路走到目标
# 用户提的是 **三档分区 ＋ 统一决策**；而"三档分区塞进三阶段"当然不好
# （2026-09-24 实测：那个组合下三臂都 112/112，分区律纯属多花 3~6% 拍照）。
# 本开关打开后用 `_go_to_panel_unified`（P1 新循环）替换三段式调用链。
#
# ⚠️ 现状（2026-09-25，P1 进行中，**尚未达标，故暂不设为默认**）：
#   P1 的新循环已具备全部形态（像素域判档 / 一次决策一个原语 / 不用 yaw 数值 /
#   不用死推提示 / 纯视觉重捕获），但**到达判据的三个阈值尚未重新标定**，
#   打开后 seed 3 只有 1/7（旧链路 7/7）。缺口的定量证据：
#     · 旧阈值是在**旧控制律**下标的（`_arrive_visual` 的接近序列），
#       换控制律后前提变了 —— 这正是"不能直接继承标定结果"的又一例；
#     · 紫区高度 0.2445 只覆盖画幅底边上方约 4cm 地面 ⇒ 判据在 ≤4cm 才成立，
#       而单步 2.652cm ⇒ 单格要走 ~14 次前进决策，撞穿 140 张/格上限；
#       已把紫区抬到 0.62（覆盖约 16cm），紫份额在 40cm 处即达 0.345；
#     · 剩下的卡点是**左右不对称门**：本相机下横向灵敏度实测 ≈ **6.4/cm**
#       （0cm→0.026、3cm→0.226、6cm→0.403），0.25 只容许 **±1.7cm** 横偏，
#       而蓝档把机器人稳定在 ±5cm 量级 ⇒ 判据几乎永不成立（实测横偏 7.7% 画幅
#       ≈ 5.4cm 时不对称已达 0.3+）。
#   ⇒ 达标前**不许**把它翻成默认（会打挂 tests/test_nine_grid_sim.py 与
#     tests/test_nine_grid_deform.py 的 7/7 断言）。重标定清单见需求规格 §7.4。
UNIFIED_NAV_ENABLED = False
# 统一决策把它们合成一个循环 ⇒ 上限必须 ≥ 这个量级，否则会在"还没走到"时就用尽，
# 外层 RETRY 只能拿 back_one_step 兜（第一版 60 时就踩了这个坑）。
UNIFIED_MAX_ITERS = 150
# 连续多少次"检不出目标面板"才认输去重搜。
UNIFIED_LOSS_TOLERATE = 4
# ★ 看不到目标时的"转身面向它"（2026-09-24 实测补上的一步，见 _drive_unified）：
#   提示方位（`_search_hint`：锚优先、死推兜底）超过此值 ⇒ 认为目标不在**居中
#   头位**的视野里（真实半视场 33.7°）⇒ 先按提示转身，而不是往前压。
#   取 20°：小于真实半视场 33.7°，这样"其实在视野边缘"的情况不会多转一次；
#   又比"死区 12°（名义）/16.3°（真实）"大一档，避免把正常对准当成丢失。
VIS_UNIFIED_TURN_MIN_DEG = 20.0
# 连续转身多少次仍然看不到 ⇒ 放弃单纯转身，改用完整重搜（头部五档扫 + 盲走）。
# 取 4：提示方位最大 180°，一步大转 25.7° ⇒ 最多 5 步就能转过来；4 次"转身"
# 已经覆盖 103°，再多说明提示本身不可信（死推漂了/目标被挡），该换手段。
VIS_UNIFIED_TURN_MAX = 4
# ★ 重捕获（P1）：目标不见了怎么办 —— 纯视觉、逐步转、有上限
#   为什么需要它：统一决策**不用死推提示**（用户明确放弃），而"上一格跑完时目标
#   经常在 180° 身后、距离可达 2 格"（实测面板3 距上一格 79cm）。若只做几小步
#   自转就放弃，整局会在第 2 格之后连续丢格。
#   机理：**地图方位 → 逐步转过去 → 每一步都拍照复测**。方位只用来决定"往哪边转"，
#   转多少完全由视觉闭环决定（转多了下一步反向吸收）——这不违反"不用死推"：
#   `self.pose` 是布局扫/到达锚定的结果，且**只用于选方向**，不产生任何"到位"结论。
VIS_REACQ_MAX_TURN_DEG = 720.0   # 单次重捕获允许累计转过的角度（2 整圈；见下）
VIS_REACQ_MAX_FRAMES = 90        # 单次重捕获拍照上限
# 为什么是 720°／90 帧（实测定的，不是拍的）：
#   上一格跑完时目标常在**正后方**。旧值（420°/40 帧 + 每 4 帧才转一步）实测只能
#   转过 ≈55°，于是"目标在身后"的整格**一步未动就放弃**——seed 3 有 4/7 格是这种
#   （逐格真值轨迹：起点=终点，一格都没走）。
#   算账：小转一步实测左 8.625°/右 5.200° ⇒ 转 180° 要 21~35 步；每 2 帧转一步
#   ⇒ 42~70 帧。取 90 帧/720°（=2 整圈）覆盖最坏情况（提示方向错、要绕一圈）。
#   ⚠️ 与"单格 360° 转向预算"的关系：预算是防"在原地打转"，重捕获是**有目标方向**
#   的搜索 ⇒ 二者分别记账（见 `_unified_reacquire`）。
VIS_REACQ_STRIDE = 1             # 每丢几帧转一步
# ★ 单向扫描上限 + 反向（2026-09-25 实测新增）
#   实测（seed7 digit3 逐帧真值轨迹）：重捕获**单向转了 83 帧**目标才进视野
#   （转过 ~240°），而一旦看到目标，逼近只用了 **12 帧**就收敛到 3.7cm
#   —— 即整格的时间几乎全花在"朝错方向盲扫"上。
#   机理：`_bearing_to_target_deg` 读的是 pose 航向，而航向不修（第三轮已否证
#   "到达后视觉修航向"）⇒ 方位可能把机器人带向反方向；单向 720° 的额度太大，
#   错方向也要转满一大圈才回来。
#   对策：**单向最多扫 VIS_REACQ_SWEEP_CAP_DEG，没看到就反向**。
#   实测**否证**：加反向之后到达 24→23、拍照 2386→2512（更差）⇒ 反向没有救回
#   那几格、反而多花帧。**故默认关闭**（=720 即"不反向"）；常量保留供复现该否证。
VIS_REACQ_SWEEP_CAP_DEG = 720.0
# ★★ 取 1（每帧都转），这是本轮**最大的单点收益**，实测（3 种子 21 格）：
#     stride=2（旧）→ 到达 10/21、落点 [7.0,8.4,65.6,32.8,14.1,64.9,53.3]、拍照 1709
#     stride=1（新）→ 到达 **20/21**、落点 [7.0,8.4,6.1,7.4,6.9,10.1,8.8]、拍照 1407
#   为什么：转 180° 要 21~35 步，stride=2 就吃掉 42~70 帧、正好卡在 110 帧的
#   重捕获上限附近 ⇒ **扫不完就被判失败**（实测失败格恰好停在 117≈110+头部5 帧，
#   而单格 140 帧的硬熔断从未触发 ⇒ 不是预算不够，是这个节流把它卡死了）。
#   每步都复测本来就是我们要的闭环语义；"隔几帧再转"省下的是动作，赔上的是整格。
# 90 帧的来历：70 帧时只有 15/21（两格仍扫不完），90 帧起稳定 20/21 且 110/130
# 完全不再改善 ⇒ 取最小充分值 90。
# ---- 到达后的**视觉航向重解**（P1 实测卡点：`_reanchor_pose` 只锚位置、不修航向）----
VIS_HEADFIX_MAX_OFFAXIS_DEG = 20.0   # 只用 |机体方位| ≤ 此值的面板参与解算
#   依据：`CAMERA_FOV_H_DEG=60` 是伺服增益不是真实 FOV ⇒ 偏轴越远误差越大
#   （实测 ±28° 处差 ~10°、±48° 处差 ~27°；近轴 ±0.3°）。
VIS_HEADFIX_MAX_DELTA_DEG = 45.0     # 解出的修正量超过此值判为误检，拒绝采纳
#   依据：正常逐格累积误差是数度级（实测一格 8°）；一次要修 45° 以上说明
#   面板认错或位置本身就错，此时**保持原样**比乱修安全。
VIS_HEADFIX_GAIN = 0.39          # 画面读数(°)/真实方位(°) —— **实测标定**，不是拍的
#   为什么需要它：`_body_yaw_deg` 用的是 `CAMERA_FOV_H_DEG=60` 这条**伺服增益**，
#   而画面真实横向标定是 ~154.8px/°（±33.7° 半视场 / 1296px）⇒ 60/154.8 = 0.388。
#   实测（固定站位只改真航向，跟同一个面板）：真航向 −20/0/+20° 时
#     几何方位 +20.00/0.00/−20.00，而 `_body_yaw_deg` 读 −7.36/+0.32/+7.99
#     ⇒ 比值 −7.36/20 = 0.368、7.99/20 = 0.400 ⇒ 取 0.39。
#   ⚠️ 偏差 0.03 就足以把"修 15°"变成"修 11°或 19°"⇒ 拿它当**修复量**用之前
#   必须先按上面口径现场重标（真机 FOV 与这 154.8px/° 不同）。这也是本项目
#   `test_nine_grid_yaw.py` 反复强调的那条：yaw 是**增益**，不是角度。
#   用它修航向是**近轴小量**下的近似（|方位| ≤ VIS_HEADFIX_MAX_OFFAXIS_DEG）。
# ---- 前进的快慢两档（**整帧色占比**分界，见 `_go_to_panel_unified` 的说明）----
# 实测 `whole`↔距离：60cm→0.056｜50→0.072｜40→0.092｜35→0.103｜30→0.115
#                    25→0.126｜20→0.137｜15→0.147（此后随裁切不再增）
VIS_FWD_COV_MID = 0.085          # < 此值（≈42cm 以外）走大步
VIS_FWD_COV_NEAR = 0.115         # < 此值（≈30cm 以外）走中步；≥ 此值恒 1 步
VIS_FWD_FAR_STEPS = 5            # 远距一次前进步数（5×2.652 ≈ 13cm）
VIS_FWD_MID_STEPS = 3            # 中距一次前进步数（3×2.652 ≈ 8cm）
# ---- 前进无效脱困（用色占比判，不用框宽）----
# 现场/仿真共识：地板打滑或顶住时"前进一步"不产生位移。判据必须用**单调量**，
# 框宽在近距裁切后会反向塌陷，只能产生误报（实测把一格推过格心 28cm）。
VIS_STALL_COV = 0.004            # 占比增量低于此值视为"这一步没走近"
VIS_STALL_PATIENCE = 2           # 连续几次没走近才后退脱困（单次抖动不误判）

# 纠横：**每次最多 3 步（6.6cm），且"看到色块之后"也继续纠**（2026-09-13 实测）。
# ① 执行方式用横移而不是小转：小转 2° 在 35cm 上前压只能挪 1.2cm，纠 7cm 要 6 次；
# ② 窗口不限制在"看到色块之前"：形变随机游走场景实测，把窗口收回
#    peak < VIS_COLOR_SEEN_MIN 后，面板 6/7 直接丢（占比已在涨、横偏还没纠完就
#    开始前压 → 压出去时偏半个开关区）。这与现场"踩不到微动开关"同源。
# dx_cm 是投影不变量，相机俯仰被形变改掉时会失真——所以次数有上限
# （VIS_LAT_MAX_CORRECTIONS），纠过头由下一帧复测接管，不会一路横着走。
VIS_LAT_MAX_CORRECTIONS = 4     # 低头段横向纠偏次数上限（防抖动）
VIS_STALL_BOX_PX = 5.0          # 前进无效判据（参考 proximity_change<5）
VIS_MIN_RATIO_CHANGE = 0.002    # 低头段占比变化下限（参考；紫6 取 0）
VIS_LAT_TOL_CM = 3.0            # 低头段横向容差（由 dx/box_w*PANEL_WIDTH_CM 换算）
# 纠横执行方式开关（可回退）：True = 横移（left/right_move，cm 级、直接消
# 偏差）；False = 旧行为（turn_*_small_step，度级——小转 2° 在 35cm 上前压
# 只能挪 35·sin2° ≈ 1.2cm，纠 10cm 偏差要 8 次，等于没纠）。
# 换算式 dx_cm = (px − W/2)/box_w · PANEL_WIDTH_CM 是投影不变量（抗形变），
# sim 实测精度：真值横偏 5/10cm（@30cm）→ 估 4.7/9.2cm。
VIS_ARRIVE_LAT_VIA_SIDESTEP = True
VIS_ARRIVE_LAT_MAX_STEPS = 3    # 单次纠横步数上限（3×2.2cm≈6.6cm，防纠过头）
VIS_SEARCH_MAX_ROUNDS = 4       # 搜索轮次上限（每轮 = 头部五档扫 + 转一步）
VIS_SEARCH_PROBE_STEPS = 3      # （保留）早前的前进探测步数
VIS_SEARCH_BLIND_CM = 25.0      # 盲走判据：死推纵向大于此值时先走近再由视觉接管
VIS_SEARCH_BLIND_MAX_STEPS = 10  # 单轮盲走上限（10×2cm=20cm）
# 单格盲走**总量**上限（2026-09-13 真机"其它异常行动"）：搜索靠"死推提示"决定
# 往哪转/往哪走，而提示来自死推位姿——位姿在长时间盲走+转向后会发散（仿真形变
# 阶跃场景实测：一次失败的搜索盲走约 1m，随后位姿与真相差 111.9cm）。盲走越多
# 位姿越离谱、下一格的提示越不可用：宁可本格记未确认，也不要在场上瞎走。
# 60cm ≈ 2 格——目标在 2 格内都没进过视野，就不是"再走走"能解决的。
VIS_SEARCH_BLIND_TOTAL_CM = 60.0
VIS_SEARCH_MAX_FRAMES = 26      # 单格搜索拍照硬上限（时间预算护栏）
# ---- 单格转向护栏（2026-09-13 真机"一直转 → 冲出场地"复盘，安全项） ----
# 现场现象：机器人在某一格内持续转向（对准与搜索互相接管），最后转出场外。
# 旧实现只在时间/拍照数/动作数上设了上限，而**转向是最便宜的动作**（不拍照、
# 不耗帧）：没有"转够了就停"的概念，它可以在死区里空转很久。
# 对策：单格累计**命令**转角（含搜索/对准/大转/纠横的所有 turn_*）超预算即
# 熔断本格，并**拒绝执行**那最后一次转向（见 _act）——宁可本格记未确认。
# 360° 依据（180° → 360°，2026-09-13 形变随机游走实测修正）：一格里**正常**
# 的转向总量 = 对准 ≤60°（几个 10° 小步）+ 搜索换视角最多两轮大转
# （每轮 ≤129°）≈ 320°；取"整圈" 360° 只拦"已经在原地打转"的情形，
# 正常最坏路径不误伤（仿真单格实测最大 180°）。早期取 180° 会在"目标在身后、
# 一轮搜索没扫到"时误熔断——deform 随机游走场景面板 4 就是这样丢的。
VIS_TURN_BUDGET_DEG = 360.0     # 单格累计命令转角上限（一整圈）
VIS_TURN_STALL_TURNS = 4        # 连续 N 次转向后 |yaw| 都没变小 → 打转判据
VIS_ALIGN_MAX_FLIPS = 3         # 死区外左右来回摆 N 次 → 判定打转（直接收手）
VIS_ALIGN_WORSEN_DEG = 5.0      # 单次转向把 |yaw| 转大超过此值 = "变差"
# ---- 离场护栏（同上，安全项） ----
# 场地是 1m×1m 台面（格心 16.7~83.3cm），起点在台面南侧 (50,-20)（见 __init__）。
# 外框取"台面 ± 1 格"（33cm）：拦的是**彻底失控**（已经跑到台面外一整格），
# 不是防跌落预案。为什么不收得更紧：死推位姿本身在形变下实测能偏 30cm+
# （到达判据"颜色峰值回落"在俯仰 ±15° 时会误判，_reanchor_pose 又把位姿锚到
# "以为"的格心——deform 随机游走实测落点残差最大 36.6cm）。真按 ±18cm 收，
# 会拿一个已经不可信的位姿把好局误熔断（该场景实测：面板4 之后整局被误中止）。
# **真正管住"继续动"的是上面三条**：转向预算 360°、停转/来回摆判据、前压封顶。
# 越界即站立并**中止整局**（不再搜索下一格）——走下台面的代价远大于丢分。
VIS_FIELD_X_CM = (-33.0, 133.0)
VIS_FIELD_Y_CM = (-48.0, 133.0)


def _check_align_invariant():
    """导入时自检：**对准死区必须 ≥ 一个真实小转步长**（设计不变量）

    为什么要在 import 时硬失败，而不是写在注释里：
    2026-09-13 真机"在死区里莫名其妙打转、最后转出场地"的根因就是这个不变量
    被破坏了——死区当时是 3.5°，而现场小转一步 ≈10°：
        yaw +4° →（规划 1 步，实际转过 10°）→ yaw −6° →（再规划 1 步）→ +4° …
    每轮都过冲、永远进不了死区；6 轮后对准放弃 → 回搜索再转 ⇒ 人看到的就是
    "打转"。这不是"参数没调好"，是**两个常数之间的关系**错了，所以只有代码
    断言能拦住下一次。

    同时校验死区不能超过"大/小转角分界"（否则大转兜底永远用不上、精度失控）。
    """
    if VIS_ALIGN_TOL_DEG < FIELD_SMALL_TURN_STEP_DEG:
        raise AssertionError(
            f"VIS_ALIGN_TOL_DEG({VIS_ALIGN_TOL_DEG}°) < 现场小转一步"
            f"({FIELD_SMALL_TURN_STEP_DEG}°，见该常量注释)：死区小于一个步长时"
            "闭环必然过冲振荡（真机现场表现='在死区里打转'）。"
            "要改小死区，必须先用现场日志证明小转一步真的变小了。")
    if VIS_ALIGN_TOL_DEG > VIS_BIG_TURN_DEG:
        raise AssertionError(
            f"VIS_ALIGN_TOL_DEG({VIS_ALIGN_TOL_DEG}°) > "
            f"VIS_BIG_TURN_DEG({VIS_BIG_TURN_DEG}°)：死区比大转分界还大，"
            "对准会直接接受任意姿态")


_check_align_invariant()

# =====================================================================
# 容错预算
# =====================================================================
TARGET_TIME_BUDGET_S = 110.0   # 单格软预算（15min/7格 ≈ 128s，留裕量）
TOTAL_TIME_BUDGET_S = 780.0    # 全局看门狗 13min（给上下场留 2min）
# ---- 单格硬熔断（2026-09-11 真机"终点不停"后新增，安全项） ----
# 现场现象：走到第 7 块面板后机器人仍在继续行动；日志显示它并没有"越界"，
# 而是第 7 格一直没确认到位，于是"搜索→对准→接近→低头→蹭步"整条链在单格内
# 反复重试，直到格预算耗尽——人看着就是"到了终点不停"。
# 旧实现的问题：超时只在**子循环入口**判（`while time.time() < t_end`），而真机
# 拍照 ~0.7s/张（2026-09-13 实测，见 VIS_CAPTURE_COST_S），一次 `_see_target_any`
# （头部五档）也有 ~4s，嵌套后单格实际能跑到 150s+，且过冲量随嵌套层数叠加。
# 对策（三重护栏，任一触发即"本格记未确认、立刻返回"）：
#   1) 时间：VIS_CELL_HARD_TIMEOUT_S，且在**每次拍照前**判（最细粒度，过冲
#      最多 1 张照片 ~0.7s，而不是一个子循环 4s+）；
#   2) 拍照数 VIS_CELL_HARD_FRAMES /   3) 动作数 VIS_CELL_HARD_ACTIONS：
#      与时钟无关的确定性护栏——即使某环节出现"不拍照也不动作"的空转或
#      "疯狂动作"的失控，也一定在有限步内退出（防新增死循环的保险丝）。
# 取值依据（时间 70s）：
#   - 总预算：全局 780s，布局扫真机实测 60~90s，剩 ~690s / 7 格 ≈ 98s/格；
#     70s 给"搜索/对准/接近/低头"四段各留失败重试余量，同时保证**最坏情况**
#     （7 格全熔断）90 + 7×70 = 580s < 780s，绝不拖过看门狗；
#   - **实测余量充足**（2026-09-13 订正）：整局 206 张 × 0.70s ≈ 2.4 分钟，
#     即使全部 7 格都跑到 70s 上限也只有 490s+90s < 780s。历史上"真机 2~4s/张"
#     的估计**偏高约 4 倍**（疑似把网络 RTT 当成了拍照耗时），曾据此误判"整局会
#     撞看门狗、单格只够 21 张"——按实测这个担心不成立。70s 仍是硬上限，
#     它管的是"某个环节卡死"，不是"正常流程不够用"。
#   - 仿真（sim，7 格全程只花 ~13s，单格最长 ≈3s；见 test_nine_grid_sim 的
#     [进度] 行）：70s 在仿真里永不触发。
VIS_CELL_HARD_TIMEOUT_S = 70.0
# 全局剩余时间按剩余格数分摊的比例（自适应收缩）：硬熔断 = min(70s,
# 剩余时间/剩余格数 × 0.9)。这样即使每格都被熔断，累计也不会超过全局看门狗
# （分摊是望远镜求和：Σ 剩余/剩余格数 = 剩余时间），0.9 再留 10% 余量。
# 下限 45s：避免最后一格因前面拖时而只剩几秒、连一次搜索都跑不完。
VIS_CELL_HARD_BUDGET_FRAC = 0.9
VIS_CELL_HARD_TIMEOUT_MIN_S = 45.0
VIS_CELL_HARD_FRAMES = 140     # 单格拍照硬上限（基线整局 206 张、单格最多 ~38 张）
VIS_CELL_HARD_ACTIONS = 300    # 单格动作硬上限（基线整局 176 次、单格最多 ~55 次）
# ---- 单格"拍照数"预算（与时间预算绑定，让真机不会把时间耗在拍照上） ----
# 为什么需要它：旧护栏 VIS_CELL_HARD_FRAMES=140 是死判据（单格最多 ~38 张，永不
# 触发），拦不住"某环节反复拍照把单格时间耗光"。做法是把"本格还剩多少时间"
# 换算成"还允许拍几张"：frame_budget = 本格硬预算秒数 ÷ 单张耗时估计。
# 单张耗时估计由 state.capture_cost_s 提供（真机默认见 VIS_CAPTURE_COST_S；
# 仿真里 SimNineGridRobot 声明一个极小值 ⇒ 该闸不会先于时间闸触发，回归可比）。
#
# **实测（2026-09-13 现场直接量，不要再用猜的）**：
#     fswebcam 2592x1944 -S 3 × 6 次 = 0.74/0.61/0.66/0.61/0.63/0.61s（均值 0.62s）
#     走代码路径 RobotState.capture_frame()（fswebcam + cv2.imread）= **0.70s**
# 历史文档里"真机 2~4s/张"的估计**偏高约 4 倍**（很可能是把 RTT/弱链路读数当成
# 了拍照耗时）。这个高估会把拍照预算压到 70/3×0.9 ≈ 21 张/格，而实测单格需求
# 最多 61 张 ⇒ **预算会先把本来能跑完的好格砍掉**。故按实测取 0.9s（留 ~30%
# 裕量覆盖进程/内存竞争），得到 ≈70 张/格，与 70s 时间闸等价而不更严。
# 换机器人/换相机请重测（tools/field_probe_ninegrid.py 可复用其锁相机链路）。
VIS_CAPTURE_COST_S = 0.9       # 机器人单张耗时（秒；2026-09-13 实测 0.70s + 裕量）
VIS_CAPTURE_COST_SAFETY = 0.9  # 再留 10% 裕量（动作/转头也吃时间）
STALL_EPS_CM = 0.5             # 卡滞判据：前进单步距目标改善低于此
STALL_CONSEC = 2               # 连续多次触发即卡滞
RETRY_LIMIT = 2                # 单格 CONFIRM 失败重试上限
ENTER_FAIL_LIMIT = 3           # 进入段连续定位失败上限
RECOVER_LIMIT = 5              # 单段定位丢失恢复上限（逐级升级，超过放弃本段）
LOC_BUDGET_PER_TARGET = 40     # 单格定位次数软护栏（超限只告警，真机时间诊断用）


# =====================================================================
# 格阵拟合（布局扫 v2：机器人系相对几何，无站位/标定依赖）
# =====================================================================
# 数学原理：可见面板是已知 3×3 刚性格阵（间距 GRID_CELL_CM，格6恒空）经未知
# 刚体变换（平移+旋转）后的带噪子集。拟合三步：
#   1) 枚举"某对面板=相邻格"假设，其余面板在该假设格阵基下整数化，
#      残差 ≤LATTICE_INLIER_CELL 格距者为内点（对角/跨格假设被共识自动否决）；
#   2) 取内点最多的假设为格阵基（要求**全部输入数字**都是内点，否则判失败）；
#   3) 枚举 **4 个真旋转**（不含镜像）作为格号朝向候选，硬约束过滤：
#      无重复占格 / 覆盖门（每块板都在自己格号 0.35 格距内）/ 刚体残差门
#      （干净子集 RMS）/ 入口侧谓词 / 列序谓词；"格6 恒空"优先但不硬杀
#      （全灭时降级并告警，避免约定不符直接崩溃）。
#
# 为什么只枚举真旋转（手性论证，2026-09-11 修复 P0）：
#   像素→机器人系（GroundHomography.from_pose((0,0),…)）与像素→场地系
#   （project_ground_to_pixel）用的是同一套投影模型，两个坐标系都是
#   x 右 / y 前 / z 上的右手系；格阵基 e2 = CCW90(e1) 也是右手构造，
#   因此"格阵整数坐标 → 场地格号"的真解必然是真旋转（det = +1 族），
#   镜像候选在几何上不可能成立。历史 bug：D4 把镜像一并枚举，镜像候选能
#   通过全部旧约束并被选中 → 布局被转置且位姿自举崩溃。真实照片实测分离度
#   （2701 干净点集）：真旋转 RMS 0.62cm vs 镜像 18.75cm。
LATTICE_INLIER_CELL = 0.35      # 格阵基整数化/覆盖门残差上限（格距单位）
LATTICE_RMS_MAX_CM = 8.0        # 干净子集刚体拟合 RMS 上限（cm）
# 阈值依据（2026-09-11 现场照片实测）：真旋转族 0.6~4.5cm（含参数网格量化：
# 偏移步 2.5° 在 1m 处 ≈4cm），镜像族 17.4~18.8cm → 取 8cm 兼顾现场裕量与
# 区分度（真/镜像相差 2 倍以上）。过紧会让现场"3 轮重扫后直接失败丢整关"。
LATTICE_RMS_MAX_ALL_CM = 0.35 * GRID_CELL_CM   # 无干净子集时的退化门（≈11.7cm）
LATTICE_CLIPPED_WEIGHT = 0.3    # 仅由裁切观测支撑的数字，刚体拟合中的权重
LATTICE_CENTER_PRIOR_X_CM = 50.0  # 入口居中先验（场地系 x，cm）
LATTICE_CENTER_MARGIN_CM = 10.0   # 居中度差距小于此且解不同 → 判歧义（重扫）

# ---- 参数网格自标定（见 NineGridLevel._lattice_grid_fit） ----
# 偏移下界必须含 0：2026-09-11 现场照片实测，pitch1040 的最优偏移落在 10°
# 边界上（有效俯角 ≈51.5°），网格下界留 0 才不会把真值卡在边界。
LAYOUT_OFFSET_MIN_DEG = 0.0
LAYOUT_OFFSET_MAX_DEG = 40.0
LAYOUT_OFFSET_STEP_DEG = 2.5
LAYOUT_HEIGHT_MIN_CM = 36.0
LAYOUT_HEIGHT_MAX_CM = 70.0
LAYOUT_HEIGHT_STEP_CM = 5.0
LAYOUT_VOTE_MIN_FRAC = 0.6      # 胜出布局须占全部成功组合的比例
LAYOUT_VOTE_MIN_COMBOS = 10     # 且组合数下限（防少数组合碰巧一致）
# 像素域五参数精修门（见 _pixel_pose_calib）：重投影 RMS 上限 = 导航的 GN 门控
# （GN_PIXEL_GATE）——自标定常数必须让导航级残差合格，否则真机会定位风暴。
# 门用**中位残差**而不是 RMS：真实照片里少数面板会因光照/阴影/半合并使
# 观测中心偏几十 px，RMS 被它们抬高（实测中位 ~20px 而 RMS ~110px），
# 但参数估计由多数好观测驱动，故用稳健的统计量判定。
PIXEL_CALIB_MED_MAX_PX = 40.0
SPREAD_MAX_CM = 8.0             # 簇内离散告警阈值（cm；超出说明该数字观测不可信）
# 歧义修复（E）交换余量：歧义数字的观测点必须"离竞争格比离本格近"这么多 cm
# 才考虑交换格号（约 1/4 格距，远大于现场观测 1~2cm 的跨帧离散）。
AMBIG_SWAP_MARGIN_CM = 8.0
CLUSTER_RADIUS_CM = 6.0         # 同数字跨帧观测聚类半径（cm）：取最大一致簇
LAYOUT_MIN_CLEAN_DIGITS = 6     # 提前结束扫描所需的"未裁切观测覆盖数字数"
POSE_BOOTSTRAP_RMS_MAX_CM = 0.35 * GRID_CELL_CM  # 位姿自举刚体残差上限
# 取"覆盖门同量级"（0.35 格距 ≈11.7cm）：布局若已被 lattice_assign 接受
# （每点 ≤0.35 格距、干净子集 RMS ≤LATTICE_RMS_MAX_CM），自举就不该用更严的
# 门把它否掉——否则会出现"布局通过但位姿被拒"的自相矛盾流程。区分"布局错"
# 靠的是覆盖门 + 手性 RMS 门 + 规则/入口侧/列序谓词，不靠本门。
POSE_BOOTSTRAP_X_RANGE = (-10.0, 110.0)   # 自举位姿合理性门（场地系 cm）
POSE_BOOTSTRAP_Y_RANGE = (-45.0, 105.0)   # 入口在场外，y 允许负值

# 布局扫一次拟合的完整结果（cells=None 表示失败；见 _lattice_grid_fit）
# pose = 像素域精修得到的位姿 (x, y, θ)（None = 未收敛，回退刚体自举）
LatticeFit = namedtuple(
    "LatticeFit",
    "cells info offset_deg cam_height_cm pts_robot clean weights "
    "rms_clean_cm rms_all_cm spread_cm res_max_cm warnings pose")


def _pixel_pose_calib(entries, p0, off0, h0, iters=12):
    """像素域五参数联合精修 (x, y, θ, 安装偏移, 相机高度) → (pose5, rms_px)

    为什么需要：格阵刚性判据只约束"这批点是不是 33.3cm 格阵"，(安装偏移,
    相机高度) 存在一条**等价退化谷**——sim 实测 (18.5°, 56cm) 与 (19.5°, 59cm)
    的刚体 RMS 都是 0.30cm，但导航用的投影对谷内位置很敏感：高度差 3cm 会让
    GN 残差从 <1px 涨到 16~23px，直接触发"定位风暴"（拍照数爆表）。
    像素域目标用的是完整投影模型（含裁切感知观测），谷被消掉。

    entries: [(格心场地坐标, 观测像素, head_pulse, 裁切?, pitch_pulse), ...]
    与导航同一残差定义 + Cauchy 鲁棒 + 弱先验（观测少时仍可解）。
    无效（面板跑到相机背后/参数越界）返回 (None, None)。
    """
    ent = [(np.asarray(g, dtype=np.float64), np.asarray(px, dtype=np.float64),
            int(head), bool(cl), int(pitch))
           for g, px, head, cl, pitch in entries]
    if len(ent) < 4:
        return None, None, None
    w_obs = np.array([1.0 if not cl else 0.6 for _g, _px, _h, cl, _p in ent])
    sig = np.array([20.0, 20.0, np.radians(20.0), 12.0, 20.0])  # 弱先验 σ
    ref = np.array([p0[0], p0[1], p0[2], float(off0), float(h0)], dtype=np.float64)

    def resid(p):
        out = np.empty((len(ent), 2))
        for k, (g, px, head, cl, pitch) in enumerate(ent):
            # 有效性守卫：观测点当初是在画幅内被检出的，若预测中心跑到画幅外
            # 很远（或面板跑到相机背后），这一步长把参数推到了不自洽处 →
            # 视为无效，由线搜索缩步。否则优化器会"收敛"到把面板甩出画外的
            # 大残差解（实测真实照片集上出现干净残差 2.6e4 px 的假收敛）。
            qc = project_ground_to_pixel(g, p[0], p[1], p[2], pitch, head,
                                         pitch_offset_deg=p[3],
                                         cam_height_cm=p[4])[0]
            if not np.all(np.isfinite(qc)) or not (
                    -1500.0 <= qc[0] <= CAMERA_WIDTH + 1500.0
                    and -1500.0 <= qc[1] <= CAMERA_HEIGHT + 1500.0):
                return None
            if cl:
                q = clipped_quad_centroid(g, p[0], p[1], p[2], pitch, head,
                                          pitch_offset_deg=p[3],
                                          cam_height_cm=p[4])
            else:
                q = qc
            if q is None:
                return None
            q = np.asarray(q, dtype=np.float64)
            if not np.all(np.isfinite(q)):
                return None
            out[k] = q - px
        return out

    p = ref.copy()
    r = resid(p)
    if r is None:
        return None, None, None
    steps = np.array([0.5, 0.5, np.radians(0.5), 0.5, 1.0])
    dmax = np.array([3.0, 3.0, np.radians(3.0), 3.0, 3.0])
    for _it in range(iters):
        per = np.linalg.norm(r, axis=1)
        # Cauchy 权重按观测给（与 _gn_run 同一鲁棒核）
        w = w_obs / (1.0 + (per / GN_CAUCHY_C_PX) ** 2)
        J = np.zeros((r.size + 5, 5))
        for j in range(5):
            e = np.zeros(5)
            e[j] = steps[j]
            r1 = resid(p + e)
            r2 = resid(p - e)
            if r1 is None or r2 is None:
                return None, None, None
            J[:r.size, j] = ((r1 - r2) / (2.0 * steps[j])).ravel()
        for j in range(5):                      # 弱先验行
            J[r.size + j, j] = 1.0 / sig[j]
        rp = np.concatenate([r.ravel(), (p - ref) / sig])
        wf = np.concatenate([np.repeat(w, 2), np.ones(5)])
        try:
            d = np.linalg.solve(J.T @ (J * wf[:, None]) + 1e-8 * np.eye(5),
                                -(J.T @ (rp * wf)))
        except np.linalg.LinAlgError:
            return None, None, None
        d = np.clip(d, -dmax, dmax)
        ok = False
        for _ls in range(6):
            cand = p + d
            if (-15.0 <= cand[3] <= 55.0 and 25.0 <= cand[4] <= 100.0
                    and abs(cand[0] - ref[0]) <= 60.0
                    and abs(cand[1] - ref[1]) <= 60.0
                    and abs(_wrap_angle(cand[2] - ref[2])) <= np.radians(40.0)):
                rc = resid(cand)
                if rc is not None:
                    p, r, ok = cand, rc, True
                    break
            d = d * 0.5
        if not ok:
            break
        if np.max(np.abs(d[:3])) < 1e-3 and abs(d[3]) < 0.02 and abs(d[4]) < 0.02:
            break
    per = np.linalg.norm(r, axis=1)
    cl = np.array([c for _g, _px, _h, c, _p in ent])
    rms_all = float(np.sqrt(np.mean(per ** 2)))
    med_clean = (float(np.median(per[~cl]))
                 if int(np.count_nonzero(~cl)) >= 3 else float(np.median(per)))
    return p, rms_all, med_clean


def _fit_failure(info, warnings=None):
    """构造失败的 LatticeFit（cells=None）；见 _lattice_grid_fit"""
    return LatticeFit(cells=None, info=info, offset_deg=0.0, cam_height_cm=0.0,
                      pts_robot={}, clean=set(), weights={}, rms_clean_cm=None,
                      rms_all_cm=None, spread_cm={}, res_max_cm=None,
                      warnings=list(warnings or []), pose=None)


def _rigid_fit_2d(gs, ps, w=None):
    """p ≈ R·g + t 的 2D **加权**刚体最小二乘（R 为真旋转）。

    gs: (N,2) 场地格心；ps: (N,2) 机器人系点；w: (N,) 权重（缺省 1）。
    返回 (R, t, rms_cm, per_point_cm)。R 把场地系映射到机器人系，故
    机器人在场地系的位置 = -Rᵀ·t（机器人系原点 p=0 的场地坐标）。
    """
    gs = np.asarray(gs, dtype=np.float64)
    ps = np.asarray(ps, dtype=np.float64)
    ww = np.ones(len(gs)) if w is None else np.asarray(w, dtype=np.float64)
    sw = float(ww.sum())
    gm = (gs * ww[:, None]).sum(axis=0) / sw
    pm = (ps * ww[:, None]).sum(axis=0) / sw
    Hm = ((gs - gm) * ww[:, None]).T @ (ps - pm)
    U, _S, Vt = np.linalg.svd(Hm)
    d = np.sign(np.linalg.det(Vt.T @ U.T))
    Rm = Vt.T @ np.diag([1.0, d]) @ U.T
    tt = pm - Rm @ gm
    per = np.linalg.norm(ps - ((Rm @ gs.T).T + tt), axis=1)
    return Rm, tt, float(np.sqrt(np.mean(per ** 2))), per


def ambiguity_repair(cells, pick, ambig, margin_cm=None):
    """歧义修复（E）：用格阵共识复核颜色有歧义、形状又没定案的面板

    输入：cells = {数字: 格号}（格阵投票胜出解）；pick = 该解的拟合明细
    （含 med=各数字机器人系点、clean=可信数字集合）；ambig = {数字: {竞争数字}}。
    做法：
      1. 只用**无歧义且可信**的数字拟合刚体变换（场地格心 → 机器人系点）；
      2. 对每个歧义数字 d 与其竞争数字 c（两者都已在 cells 里）：比较 d 的观测点
         到"格(d)"与"格(c)"预测位置的距离，若后者近出一个余量以上 ⇒ 交换二者格号；
      3. 交换后用全点重算残差，**只有残差变小才接受**（否则回退）。
    返回 (cells, notes)：notes 为人类可读的修复记录（无修复时为空）。
    几何不可判（置信数字 <3、缺观测、候选不在解里）时原样返回——宁可不动。
    """
    margin_cm = AMBIG_SWAP_MARGIN_CM if margin_cm is None else margin_cm
    notes = []
    if not ambig or not cells or pick is None:
        return cells, notes
    med = pick.get("med") or {}
    pairs = []
    for d, cands in ambig.items():
        if d not in cells or d not in med:
            continue
        for c in cands:
            if c in cells and c != d and c in med and (c, d) not in pairs:
                pairs.append((d, c))
    if not pairs:
        return cells, notes
    clean = set(pick.get("clean") or ())
    base_amb = {d for pr in pairs for d in pr}
    ref = [d for d in cells if d in med and d in clean and d not in base_amb]
    if len(ref) < 3:                      # 可信参照不足：换用全部非歧义数字
        ref = [d for d in cells if d in med and d not in base_amb]
    if len(ref) < 3:
        return cells, notes

    def _resid(cells_now):
        ds = sorted(d for d in cells_now if d in med)
        gs = np.array([grid_cell_center(cells_now[d]) for d in ds])
        ps = np.array([med[d] for d in ds])
        w = np.array([1.0 if d in clean else LATTICE_CLIPPED_WEIGHT for d in ds])
        _R, _t, _rms, per = _rigid_fit_2d(gs, ps, w)
        return float(np.sqrt(np.mean(np.asarray(per) ** 2)))

    # 参照刚体变换：只用参考数字（歧义数字的观测不参与，避免"自己证明自己"）
    gs = np.array([grid_cell_center(cells[d]) for d in sorted(ref)])
    ps = np.array([med[d] for d in sorted(ref)])
    R, t, _rms, _per = _rigid_fit_2d(gs, ps, np.ones(len(ref)))

    def _pred(cell):
        return R @ grid_cell_center(cell) + t

    new_cells = dict(cells)
    for d, c in pairs:
        pd, pc = np.asarray(med[d]), np.asarray(med[c])
        d_own = float(np.linalg.norm(pd - _pred(cells[d])))
        d_other = float(np.linalg.norm(pd - _pred(cells[c])))
        # 对称检查：竞争数字 c 的观测也应更靠近格(d)，否则不动（可能只是噪声）
        c_own = float(np.linalg.norm(pc - _pred(cells[c])))
        c_other = float(np.linalg.norm(pc - _pred(cells[d])))
        if d_other + margin_cm >= d_own or c_other + margin_cm >= c_own:
            continue
        cand = dict(new_cells)
        cand[d], cand[c] = new_cells[c], new_cells[d]
        if _resid(cand) < _resid(new_cells):
            notes.append(
                f"数字 {d}↔{c} 交换格号（{new_cells[d]}↔{new_cells[c]}）："
                f"观测点距对格 {d_own:.1f}cm、距竞争格 {d_other:.1f}cm"
                f"（余量 {margin_cm:.0f}cm），交换后残差下降")
            new_cells = cand
    return new_cells, notes



def lattice_assign(points_by_digit, spacing_cm=GRID_CELL_CM, weights=None,
                   clean=None):
    """机器人系相对几何格阵拟合：{digit: (x,y)} → ({digit: cell}, info, ranked)

    points_by_digit: 各面板在**机器人系**地面坐标（像素经名义高度/俯仰/
    头部角的单应映射，与场地系无关）。
    weights: {digit: w} 刚体拟合权重（缺省 1.0；仅裁切观测支撑的数字应降权，
    见 LATTICE_CLIPPED_WEIGHT）。
    clean:   可信（未裁切）数字集合；刚体残差门优先在它上面判（<3 个时退化
    为全点门）。手性/参数错时镜像族会在这里被拒。
    返回 (cells|None, info, ranked)：
      cells  = 数字→格号，覆盖**全部**输入数字（覆盖不足即整体判失败）；
      ranked = 全部可行候选（rule_ok / cam_x / rms_* 字段），供诊断与调用方自检。

    算法（假设-共识）：
      1) 枚举"某对面板=相邻格"假设（长度带内全部有序对），把其余面板在
         该假设的格阵基下整数化，残差 ≤LATTICE_INLIER_CELL 格距者为内点；
      2) 取内点最多的假设（并列取残差和最小）；对角/跨格假设会被共识
         自动否决（第三块板落不到整数格上）；
      3) 对内点整数坐标枚举 4 个真旋转（非镜像，见本节顶部手性论证），
         硬约束过滤 + 居中先验裁决；多解不猜（判歧义，由调用方前进一步重扫）。
    """
    digits = sorted(points_by_digit)
    if len(digits) < 4:
        return None, f"可见面板仅 {len(digits)} 块（需≥4 才能定朝向）", []
    pts = {d: np.asarray(points_by_digit[d], dtype=np.float64) for d in digits}

    # ---- 1) 假设-共识：找最优格阵基与整数坐标 ----
    best = None  # ((n_inliers, -res_sum), int_coords, inliers)
    for i in digits:
        for j in digits:
            if i == j:
                continue
            v = pts[j] - pts[i]
            L = float(np.linalg.norm(v))
            if not 0.55 * spacing_cm <= L <= 1.7 * spacing_cm:
                continue
            e1 = v / L
            e2 = np.array([-e1[1], e1[0]])
            coords, res = {}, {}
            for d in digits:
                w = (pts[d] - pts[i]) / spacing_cm
                a, b = float(w @ e1), float(w @ e2)
                ia, ib = int(round(a)), int(round(b))
                coords[d] = (ia, ib)
                res[d] = max(abs(a - ia), abs(b - ib))
            inliers = [d for d in digits if res[d] <= LATTICE_INLIER_CELL]
            if len(inliers) < len(digits):
                continue  # 覆盖率门：任一块板落不到整数格 → 假设或观测有误
            intc = {d: coords[d] for d in inliers}
            as_ = [a for a, _ in intc.values()]
            bs = [b for _, b in intc.values()]
            if max(as_) - min(as_) > 2 or max(bs) - min(bs) > 2:
                continue
            if len(set(intc.values())) != len(intc):
                continue  # 两板落同一格 → 假设不成立
            score = (len(inliers), -sum(res[d] for d in inliers))
            if best is None or score > best[0]:
                best = (score, intc, inliers)
    if best is None:
        return (None, "无一致格阵假设（面板相对位置与 33cm 格阵不符，或存在"
                      "坏观测/假阳，需重扫）", [])
    _score, ij, inliers = best

    # ---- 2) 4 个真旋转枚举：硬约束 + 刚体残差门 + 入口侧/列序谓词 ----
    # 行号/列号约定：行0=远排、行2=入口排（格6-8）；列0=入口视角左
    # （标号约定单一真源 = core/ground_homography.ROW0_IS_FAR / COL0_IS_LEFT，
    #  格号构造统一走 cell_index）。
    # 入口侧判定：对每个候选朝向做 2D 刚体 Procrustes（网格系→机器人系），
    # 机器人在网格系的 y 必须小于所有可见面板的网格 y（+半格容差）——
    # 即"机器人从入口侧进入、位于全部可见面板之前"的严格表达。
    # （"入口行均值距离最近"这类启发式在侧偏+大偏航下会误判，弃用）
    # "格6 恒空"是本关规则硬约束，但它与"机位/标号约定"耦合：若 4 个真旋转
    # 里无一满足，则降级接受并打警告，避免约定不符时直接崩溃、白丢整关。
    ds = sorted(ij)                    # 覆盖率门保证 == sorted(digits)
    w_all = np.array([(weights or {}).get(d, 1.0) for d in ds])
    clean_set = set(clean or ())
    feet = []
    for rot in range(4):               # 只枚举真旋转（手性论证见本节顶部）
        mapping = {}
        for d, (a, b) in ij.items():
            aa, bb = a, b
            for _ in range(rot):
                aa, bb = bb, -aa
            mapping[d] = (aa, bb)
        amin = min(a for a, _ in mapping.values())
        bmin = min(b for _, b in mapping.values())
        cells = {d: cell_index(a - amin, b - bmin)
                 for d, (a, b) in mapping.items()}
        if len(set(cells.values())) != len(cells):
            continue  # 两板落同一格 → 该朝向不成立
        gs = np.array([grid_cell_center(cells[d]) for d in ds])
        ps = np.array([pts[d] for d in ds])
        Rm, tt, rms_all, per = _rigid_fit_2d(gs, ps, w_all)
        # 覆盖率门：每块板都必须落在自己格号的 0.35 格距内
        if float(np.max(per)) > LATTICE_INLIER_CELL * spacing_cm:
            continue
        idx = [k for k, d in enumerate(ds) if d in clean_set]
        rms_clean = (float(np.sqrt(np.mean(per[idx] ** 2)))
                     if len(idx) >= 3 else None)
        gate = (LATTICE_RMS_MAX_CM if rms_clean is not None
                else LATTICE_RMS_MAX_ALL_CM)
        if (rms_clean if rms_clean is not None else rms_all) > gate:
            continue
        cam_grid = -Rm.T @ tt
        # 入口侧精确谓词：机器人必须在全部可见面板的入口侧
        if cam_grid[1] >= float(np.min(gs[:, 1])) + GRID_CELL_CM / 2:
            continue  # 机器人不在全部可见面板的入口侧 → 朝向错
        # 列0 必须在机器人系更左（x 更小；列间 66.6cm ≫ 偏航余弦衰减）
        col_x = {}
        for d, cell in cells.items():
            col_x.setdefault(cell % 3, []).append(pts[d][0])
        if 0 in col_x and 2 in col_x \
                and float(np.mean(col_x[0])) > float(np.mean(col_x[2])):
            continue
        feet.append({"rule_ok": 6 not in cells.values(),
                     "cells": {d: int(cells[d]) for d in ds},
                     "cam_x": float(cam_grid[0]), "cam_y": float(cam_grid[1]),
                     "rms_clean": rms_clean, "rms_all": rms_all,
                     "res_max_cm": float(np.max(per))})

    if not feet:
        return None, ("4 个真旋转均不满足约束（无重复格 / 覆盖 0.35 格距门 / "
                      "刚体残差门 / 入口侧 / 列序）——可见子集不对称、观测"
                      "有误或标号约定不符"), []

    # 排序：先满足"格6恒空"（规则），再入口居中先验（场地入口在底边中央
    # x=50），最后比刚体残差。多解且居中度相近 → 判歧义（调用方前进一步重扫）。
    def _rank_key(fc):
        return (not fc["rule_ok"],
                abs(fc["cam_x"] - LATTICE_CENTER_PRIOR_X_CM),
                fc["rms_clean"] if fc["rms_clean"] is not None
                else fc["rms_all"])

    ranked = sorted(feet, key=_rank_key)
    pool = [fc for fc in ranked if fc["rule_ok"]] or ranked
    if len(pool) > 1:
        margin = (abs(pool[1]["cam_x"] - LATTICE_CENTER_PRIOR_X_CM)
                  - abs(pool[0]["cam_x"] - LATTICE_CENTER_PRIOR_X_CM))
        if margin < LATTICE_CENTER_MARGIN_CM \
                and pool[1]["cells"] != pool[0]["cells"]:
            return None, (f"朝向歧义（{len(pool)} 个可行解且居中度相近）"
                          "——前进一步重扫消解"), ranked
    best = pool[0]
    if not best["rule_ok"]:
        return (dict(best["cells"]),
                "格阵拟合成功（警告：格位 6 有面板占据——数字与格位的对应关系"
                "或站位存疑，需现场逐格核对）", ranked)
    if best["rms_clean"] is None:
        info = (f"格阵拟合成功（{len(feet)} 个可行的格阵朝向，"
                "无完整可见子集，改用全部观测的均方根残差判据）")
    else:
        info = (f"格阵拟合成功（{len(feet)} 个可行的格阵朝向，"
                f"完整可见观测的均方根残差 {best['rms_clean']:.1f}cm）")
    return dict(best["cells"]), info, ranked



class NineGridLevel:
    """数字宫格关卡：布局扫描 + 地图定位 + 逐格视觉闭环导航"""

    def __init__(self, state: RobotState, start_cam_xy=(50.0, -20.0),
                 start_bearing_deg=0.0):
        self.state = state
        self.detector = NineGridDetector()
        self.start_cam_xy = np.array(start_cam_xy, dtype=np.float64)
        self.start_bearing_deg = float(start_bearing_deg)
        self.digit_cell = {}        # 数字(1..7) -> 位置编号(0..8)
        self.cell_conflict = set()  # 布局扫时仲裁冲突的格（近距复核）
        self.deadline = None
        # 位姿 (x, y, θrad)：相机光心地面投影 + 机体航向（右正弧度）
        self.pose = np.array([self.start_cam_xy[0], self.start_cam_xy[1],
                              np.radians(self.start_bearing_deg)])
        # 自适应小转状态（整场共享：地面条件一致，一次失效全场大转）
        self._small_turn_deg = SMALL_TURN_INIT_DEG
        self._small_turn_usable = True
        self._small_turn_fail = 0   # 连续失效批次数（>=SMALL_TURN_FAIL_BATCHES 升级）
        self._turn_updates = 0      # EMA 更新次数（前几次用快收敛）
        self._last_turn = None      # (action, times)：定位丢失时撤销转向用
        self._last_big_turn = None  # (方向, 转前|bearing|)：大转防振荡
        self._turn_oscillation = False  # 大转振荡已发生 → 改用航向偏置接近
        # 相机安装/高度常数（机器人级，缺省取 camera_config）；layout_scan
        # 运行时用格阵拟合参数网格自标定刷新，GN 投影随动
        self._pitch_offset_deg = CAM_PITCH_MOUNT_OFFSET_DEG
        self._cam_height_cm = CAM_HEIGHT_CM
        # 到达确认状态（每格重置）
        self._target_seen = False   # 接近/进入段是否检出过目标数字面板
        self._loc_count = 0         # 本格定位次数（时间预算诊断）
        # 转向/离场护栏状态（见 VIS_TURN_* / VIS_FIELD_*；每格重置）
        self._cell_turn_cmd_deg = 0.0   # 本格累计**命令**转角（含搜索/对准/大转）
        self._align_stall = 0       # 连续"转向后 |yaw| 没改善"次数（打转判据）
        self._align_worsen = 0      # 连续"同号误差被转得更大"次数（方向自检）
        self._align_flips = 0       # 死区外左右来回摆的次数（打转判据）
        self._align_ladder = 0      # 打转升级阶梯档位（1 换大转 / 2 放弃对准 / 3 熔断）
        self._align_sign = 1.0      # 对准转向符号；方向自检判反了取 -1（整局保持）
        self._zone_last = None      # 上一次分区判定（迟滞用；每格重置）
        self._tail_rot_blocked = 0  # 收尾禁转拦下的转向次数（活性遥测，见 A/B 工具）
        # MAP-ANCHOR 遥测（诚实记录"锚可用率"——它决定这套机制值不值得留）
        self._anchor_calls = 0      # 调用次数（整局）
        self._anchor_ok = 0         # 成功解出锚的次数（整局）
        self._anchor_log = []       # 锚日志（只留最近若干条，避免日志爆炸）
        self._anchor_drift = []     # 锚位姿 vs 死推位姿的偏差（cm，诊断用）
        self._anchor_last = None    # 最近一次成功的锚（供搜索提示用）
        self._anchor_quiet = False  # True 时 `_anchor_stat` 不计数不打印（逆序补试）
        self._abort_level = None    # 非 None = 整局收手原因（离场护栏）
        # 诚实遥测：本格"到达"的依据 / 交棒 yaw / 落点死推残差（不参与决策）
        self._arrive_evidence = None
        self._cell_handoff_yaw = None
        self._cell_arrive_resid_cm = None
        # 死推判据命中证据（整局累计，不每格清空——用于回答"死推到底在帮倒忙吗"）
        self._dr_hits = []          # ["stop"/"fallback", ...]
        self._dr_hit_landing = []   # 命中时的**真值**离格心距离（cm；真机为空）
        # 几何到达判据证据（WS4；整局累计）
        self._anchor_arrive_hits = 0    # 几何判据成立次数（活性证据）
        self._anchor_arrive_d = []      # 每次锚可用时"实测离格心"的距离（cm）
        # 单格硬熔断状态（每格重置；见 VIS_CELL_HARD_* 常量）
        self._cell_deadline = None  # 本格硬熔断时刻（None = 未开预算，不拦）
        self._cell_t0 = None        # 本格开始时刻（日志用）
        self._cell_frames = 0       # 本格拍照数
        self._cell_actions = 0      # 本格动作数
        self._cell_tripped = None   # 熔断原因（None = 未熔断）
        self.cell_trips = {}        # {数字: 熔断原因}——未确认格的可观测记录
        # FSM 阶段标签（纯诊断：日志/仿真可视化用，不参与任何决策）
        self.phase = "INIT"
        # 逐阶段拍照计数（真机时间预算诊断：拍照 ~0.7s/张，7 格总预算 780s）
        self.phase_frames = {}
        # 逐格**落点真值**留档：{digit: (离格心 cm, 来源)}。来源 "真值"（仿真有
        # state.pos）或 "死推"（真机只有位姿估计）。用于回归时直接抓"假到达"
        # ——视觉判 ✓ 但真值不在格上（2026-09-13 面板3 就是 89.5cm 判 ✓）。
        self.panel_landing = {}

    # =================================================================
    # 单格硬熔断（安全项：宁可早停记未确认，也不要失控）
    # =================================================================

    def _cell_budget_begin(self, digit):
        """开本格预算：返回**软预算** t_end（旧语义），并装好硬熔断闸

        软预算（TARGET_TIME_BUDGET_S）= 各子循环入口的既有超时判据，保持
        不变以最小化行为改动；硬熔断（VIS_CELL_HARD_*）= 新增的、在**每次
        拍照前**都判的细粒度闸，先于软预算生效（70s < 110s），保证任何环节
        卡住都在有限时间内退出。两者都取 min(self.deadline)，绝不越过全局
        看门狗。
        """
        now = time.time()
        if self.deadline is None:       # 直接调用 go_to_panel（测试/工具）时的兜底
            self.deadline = now + TOTAL_TIME_BUDGET_S
        t_soft = min(now + TARGET_TIME_BUDGET_S, self.deadline)
        cells_left = max(1, 8 - int(digit))          # 含本格
        share = (self.deadline - now) / cells_left * VIS_CELL_HARD_BUDGET_FRAC
        hard = float(np.clip(share, VIS_CELL_HARD_TIMEOUT_MIN_S,
                             VIS_CELL_HARD_TIMEOUT_S))
        self._cell_deadline = min(now + hard, t_soft)
        self._cell_t0 = now
        self._cell_frames = 0
        # 单格拍照预算：本格时间预算 ÷ 单张耗时估计（见 VIS_CAPTURE_COST_*）。
        # 真机上它 ≈ 70/3×0.9 = 21 张——与"70s 里真能拍几张"一致，所以它才是
        # 真机真正生效的那道闸；仿真里 state 声明单张≈0 → 该闸不会先于时间闸
        # 触发，于是回归结果不受影响，而"真机跑不完"这件事在仿真里也能被看见。
        self._cell_frame_budget = int(np.clip(
            (self._cell_deadline - now)
            / max(float(getattr(self.state, "capture_cost_s",
                                VIS_CAPTURE_COST_S)), 1e-3)
            * VIS_CAPTURE_COST_SAFETY,
            1.0, float(VIS_CELL_HARD_FRAMES)))
        self._cell_actions = 0
        self._cell_tripped = None
        # 转向护栏 + 诚实遥测（每格重置；_align_sign 是整局标定，刻意不重置）
        self._cell_turn_cmd_deg = 0.0
        self._align_stall = 0
        self._align_worsen = 0
        self._align_flips = 0
        self._align_ladder = 0
        self._zone_last = None      # 迟滞状态每格重置（新格 = 新几何）
        self._arrive_evidence = None
        self._cell_handoff_yaw = None
        self._cell_arrive_resid_cm = None
        print(f"[护栏] 面板{digit} 本格限额：最长 {hard:.0f}s"
              f"（提示阈值 {(t_soft - now):.0f}s，全局剩余 "
              f"{self.deadline - now:.0f}s／{cells_left} 格）"
              f"｜拍照上限 {self._cell_frame_budget} 张"
              f"（按单张 {float(getattr(self.state, 'capture_cost_s', VIS_CAPTURE_COST_S)):.1f}s 折算）")
        return t_soft

    def _cell_expired(self):
        """单格硬熔断判据（**每次拍照/动作前**调用；True = 本格立即收手）

        三重护栏（时间 / 拍照数 / 动作数）任一超限即 True，并把原因记在
        self._cell_tripped（供 run_level 汇总打印与 self.cell_trips 留档）。
        设计上只"允许收手"，不改变任何既有判据的语义——所以它能在不引入
        新死循环的前提下，兜住搜索/对准/接近/低头补步任一环节。
        """
        if self._cell_tripped is not None:      # 已熔断：保持熔断（不反复打印）
            return True
        reason = None
        if self._cell_actions > VIS_CELL_HARD_ACTIONS:
            reason = f"动作次数 {self._cell_actions} 次 > 上限 {VIS_CELL_HARD_ACTIONS} 次"
        elif self._cell_frames > VIS_CELL_HARD_FRAMES:
            reason = f"拍照 {self._cell_frames} 张 > 上限 {VIS_CELL_HARD_FRAMES} 张"
        elif self._cell_frames > self._cell_frame_budget:
            # 与时间预算等价的拍照闸（见 VIS_CAPTURE_COST_S）：真机上"拍满了"
            # 就等于"时间快用完了"，但它在**拍照前**就能判，不必等时间闸响。
            reason = (f"拍照 {self._cell_frames} 张 > 本格上限 "
                      f"{self._cell_frame_budget} 张（按单张 "
                      f"{float(getattr(self.state, 'capture_cost_s', VIS_CAPTURE_COST_S)):.1f}s"
                      " 折算的时间限额）")
        elif self._cell_deadline is not None \
                and time.time() > self._cell_deadline:
            reason = (f"本格已用时 {time.time() - self._cell_t0:.0f}s，"
                      f"超过最长 {VIS_CELL_HARD_TIMEOUT_S:.0f}s")
        if reason is None:
            return False
        self._cell_tripped = reason
        return True

    def _trip_cell(self, reason, abort_level=False):
        """立即熔断本格（安全项统一出口）；abort_level=True 时整局一起收手

        与 _cell_expired 的三重护栏同源：置 _cell_tripped 后，所有子循环在
        下一次 _cell_expired() 处退出，go_to_panel 返回 False，run_level 记
        "未确认"。**绝不"再试一次"**——现场教训：为了"再试一次"继续留在场上
        动，代价是机器人转出场地。
        """
        if self._cell_tripped is None:
            self._cell_tripped = reason
        print(f"[护栏] {reason} → 本格终止，保持站立不动")
        if abort_level and self._abort_level is None:
            self._abort_level = reason
        self.state.act("stand")
        return True

    def _field_guard(self):
        """离场护栏：死推位姿越出场地外框（台面 ±1 格）→ 熔断本格 + 中止整局

        定位是"拦彻底失控"的兜底，不是防跌落预案：死推位姿在形变场景下实测
        能偏 30cm+（到达判据本身有误差，_reanchor_pose 又把它锚到"以为"的
        格心），所以外框放到台面 ±1 格。真正管住"继续动"的是转向预算 360°、
        停转/来回摆判据、前压封顶 45cm 这三条。
        """
        if self._abort_level is not None:
            # 已判定整局收手：保持熔断（新格开预算会清 _cell_tripped，这里补回）
            if self._cell_tripped is None:
                self._cell_tripped = self._abort_level
            return True
        x = float(self.pose[0])
        y = float(self.pose[1])
        if (VIS_FIELD_X_CM[0] <= x <= VIS_FIELD_X_CM[1]
                and VIS_FIELD_Y_CM[0] <= y <= VIS_FIELD_Y_CM[1]):
            return False
        return self._trip_cell(
            f"位姿越界 (x={x:.0f}, y={y:.0f}) 超出 x{VIS_FIELD_X_CM} "
            f"y{VIS_FIELD_Y_CM}", abort_level=True)

    def _capture(self):
        """统一拍照入口：单格拍照计数（硬熔断用）+ 转发 state.capture_frame"""
        self._cell_frames += 1
        self._count_frame()
        return self.state.capture_frame()

    # =================================================================
    # 入口
    # =================================================================

    def run_level(self):
        """布局扫描 → 按 1..7 顺序逐格导航。返回 bool（全部确认到位）

        每格结果同时写入 self.results（[(数字, 是否确认), ...]），供仿真/
        真机日志与诊断使用。
        """
        self.deadline = time.time() + TOTAL_TIME_BUDGET_S
        # 锁定相机白平衡/对焦（可选曝光）：一局开始钉一次，消除 fswebcam 每次
        # 重新测光/白平衡造成的跨帧漂移（现场实测白点 R/B 差 16% → 粉 7 漏检）。
        # 锁不上不影响继续：归一化仍能兜（见 core.robot_core.lock_camera_controls）。
        lock_camera_controls()
        # 自动曝光闭环：把画面均亮拉到目标值。**换灯/换场地后不必手改常数**
        # （实测曝光写死 100 时换灯后均亮只剩 7~22，归一化失效、扫描三轮未定）。
        if CAM_AUTO_EXPOSURE_ENABLED:
            auto_calibrate_exposure(self.state)
        self.layout_scan()
        print(f"[布局] 数字对应格位: {self.digit_cell}  "
              f"存在数字复核冲突的格: {sorted(self.cell_conflict)}")
        done = []
        for k in range(1, 8):
            ok = self.go_to_panel(k)
            done.append((k, ok))
            self.state.act("stand")
            elapsed = TOTAL_TIME_BUDGET_S - (self.deadline - time.time())
            note = ""
            if not ok and self._cell_tripped:
                # 熔断收尾（安全项）：本格记为未确认，继续下一格/收尾，
                # 绝不为了"再试一次"把机器人继续留在场上动。
                note = f"（本格终止原因：{self._cell_tripped}）"
                self.cell_trips[k] = self._cell_tripped
                print(f"[终止] 面板{k} 未确认到位：{self._cell_tripped}"
                      "——记为未确认，不再继续尝试")
            print(f"[进度] 面板{k} {'已到位' if ok else '未确认（以微动开关实际触发为准）'}"
                  f"{note}，已用时 {elapsed:.0f}s")
            # 单格诚实遥测：一行给出现场复盘需要的全部数字（事后不用翻半个日志）
            hy = self._cell_handoff_yaw
            rs = self._cell_arrive_resid_cm
            print(f"[遥测] 面板{k} 用时 {elapsed:.0f}s｜拍照 {self._cell_frames} 张"
                  f"｜动作 {self._cell_actions} 次｜命令转角 {self._cell_turn_cmd_deg:.0f}°"
                  f"｜交接偏角 {'无' if hy is None else f'{hy:+.1f}°'}"
                  f"｜离格心 {'无数据' if rs is None else f'{rs:.1f}cm'}")
            print(f"[遥测] 面板{k} 判定依据: {self._arrive_evidence or '（未到达）'}")
            if self._abort_level:
                # 离场护栏：已经越界，绝不再去"找下一格"——站立收手，保已得分
                print(f"[护栏] 整局终止：{self._abort_level}"
                      "（机器人保持站立，不再执行动作）")
                break
            if time.time() > self.deadline:
                print("[看门狗] 全局时间已耗尽，停止（保住已得分，不再继续）")
                break
        self.results = done
        if self.cell_trips:
            print(f"[诊断] 中途终止的面板: {self.cell_trips}")
        frames = sorted(self.phase_frames.items(), key=lambda kv: -kv[1])
        print(f"[诊断] 各阶段拍照张数: {frames}  合计 {sum(self.phase_frames.values())}")
        return all(ok for _, ok in done)

    # =================================================================
    # 布局扫描（机器人系相对几何格阵拟合，无站位/标定依赖）
    # =================================================================

    def layout_scan(self):
        """头部双俯角宽扫全场 → 机器人系相对几何格阵拟合 → 数字→格 映射

        每帧观测经"机器人系单应"（名义高度+俯仰+头部角，均自身已知）转为
        机器人系地面坐标，按 digit 跨帧聚合（干净观测优先，同色=同板）后做
        格阵拟合（lattice_assign：假设-共识 + 4 真旋转硬约束 + 刚体残差门）；
        布局确定后用"机器人系点 ↔ 场地格心"刚体拟合解出位姿写入 self.pose，
        GN 定位从此自续。全程不依赖站位复位与点击标定。

        扫描终止判据：**未裁切观测覆盖 ≥LAYOUT_MIN_CLEAN_DIGITS 个数字**，
        或扫满一轮（双俯仰×五头部）。为什么不用"见到 7 种数字"：现场照片
        实测单帧常见 7 种数字但只有 3 个未裁切，裁切质心偏差 1.3~8.4cm，
        据此拟合不稳定（2026-09-11 复现）。
        歧义/缺数字/自举自检不过时自动前进一步重扫（平移视差消解朝向歧义；
        也把没入视野的近排带进来），最多 3 轮。
        """
        self.phase = "LAYOUT"
        last_err = ""
        fit = _fit_failure("未执行")
        for attempt in range(3):
            pix_obs = []        # (pitch, head, digit, 观测像素, 裁切?)
            frame_obs = []      # (pitch, head, obs)：仲裁冲突回填写
            for pitch in (PITCH_NAV, PITCH_DOWN):
                self.state.set_pitch(pitch)
                for pulse in (HEAD_CENTER, HEAD_LEFT, HEAD_RIGHT,
                              HEAD_WIDE_LEFT, HEAD_WIDE_RIGHT):
                    self.state.set_head(pulse)
                    frame = self.state.capture_frame()
                    if frame is None:
                        continue
                    # 裁切感知：贴纸小、入口视角大半面板贴画幅边——保留
                    # 裁切面板，用凸包质心观测（拟合时降权，见 _aggregate）
                    # shape=True：颜色贴窗口边界时用数字形状仲裁（C3）——
                    # 布局一次定全局，颜色错判代价最大，这里最该开形状。
                    obs = self.detector.detect_panels(frame, arbitrate=True,
                                                      drop_border=False,
                                                      shape=True)
                    frame_obs.append((pitch, pulse, obs))
                    for o in obs:
                        px = (o.hull_centroid_px if o.clipped
                              else o.center_px)
                        pix_obs.append((pitch, pulse, o.digit, px,
                                        o.clipped))
                    # 提前退出：须同时满足（a）未裁切覆盖 ≥6 个数字、
                    # （b）**两档俯仰都已有观测**。只扫一档会让"安装偏移 vs
                    # 名义俯仰角"退化（实测 (1200,25°)≡(1040,10°)），
                    # 自标定常数无法外推到另一档，且参数网格成功组合太少
                    # （现场照片实测：单档仅 6 个组合 < 多数票门槛）。
                    if len({e[2] for e in pix_obs if not e[4]}) \
                            >= LAYOUT_MIN_CLEAN_DIGITS \
                            and len({e[0] for e in pix_obs}) >= 2:
                        break
                if len({e[2] for e in pix_obs if not e[4]}) \
                        >= LAYOUT_MIN_CLEAN_DIGITS \
                        and len({e[0] for e in pix_obs}) >= 2:
                    break
            self.state.set_head(HEAD_CENTER)
            self.state.set_pitch(PITCH_NAV)

            seen = {e[2] for e in pix_obs}
            clean_digits = {e[2] for e in pix_obs if not e[4]}
            missing = [k for k in range(1, 8) if k not in seen]
            info = (f"缺少数字 {missing}（完整可见的仅 {len(clean_digits)} 个）"
                    if missing else "")
            if not missing:
                # 参数网格自标定 + 格阵拟合（见 _lattice_grid_fit）
                # 颜色歧义表：{数字: {竞争数字}}，供拟合后的格阵共识复核（E）
                ambig = {}
                n_amb = 0
                for _p, _h, obs_list in frame_obs:
                    for o in obs_list:
                        if not o.ambiguous:
                            continue
                        n_amb += 1
                        cands = {k for k in o.candidates if k != o.digit}
                        if cands:
                            ambig.setdefault(o.digit, set()).update(cands)
                if n_amb:
                    print(f"[布局] 颜色有歧义的观测 {n_amb} 个"
                          f"（涉及数字 {sorted(ambig)}），交由数字复核／格阵一致性裁决")
                fit = self._lattice_grid_fit(pix_obs, ambig)
                info = fit.info
                for w in fit.warnings:
                    print(f"[布局] 警告: {w}")
                if fit.cells is not None:
                    worst = sorted(fit.spread_cm.items(),
                                   key=lambda kv: -kv[1])[:3]
                    print(f"[布局] 观测汇总: 完整可见 {len(clean_digits)}/7 "
                          f"个数字；各帧位置最大偏差 {[(d, round(s, 1)) for d, s in worst]} cm")

            if fit.cells is not None and self._pose_bootstrap(fit):
                self.digit_cell = fit.cells
                self._pitch_offset_deg = fit.offset_deg
                self._cam_height_cm = fit.cam_height_cm
                # 仲裁冲突回填：布局已知后才能把冲突面板定位到格
                for _pitch, _head, obs in frame_obs:
                    for o in obs:
                        if o.arb_conflict and o.digit in self.digit_cell:
                            cell = self.digit_cell[o.digit]
                            self.cell_conflict.add(cell)
                            print(f"[布局] 数字复核冲突：格 {cell} 按颜色判为数字 "
                                  f"{o.digit}，数字模型判为 {o.model_digit}"
                                  f"（置信度 {o.model_conf:.2f}）——待近距复核")
                print(f"[布局] {fit.info}；标定结果: 相机相对机体前偏 "
                      f"{self._pitch_offset_deg:+.1f}°、"
                      f"离地 {self._cam_height_cm:.0f}cm"
                      f"（导航档俯仰 {PITCH_NAV} 时实际俯角 "
                      f"{self._effective_pitch_deg(PITCH_NAV):.1f}°）")
                return

            if fit.cells is not None:
                # 布局解出但位姿自举自检没过：归因为自举，别误导成拟合失败
                info = (f"{fit.info}；但由面板反推位姿未通过校验——重新扫描复核"
                        f"（布局 {fit.cells}）")
            last_err = info
            if attempt < 2:
                print(f"[布局] 第 {attempt + 1} 轮未能定出布局（{info}）——"
                      "前进一步后重新扫描（用视差消除歧义）")
                self._act("go_forward_one_step", 1)
        seen_digits = sorted({e[2] for e in pix_obs})
        raise RuntimeError(
            f"布局扫描三轮未定（{last_err}）。可见数字: {seen_digits}")

    def _effective_pitch_deg(self, pitch_pulse):
        """名义脉宽角 + 自标定安装偏移 = 有效俯角（度，日志用）"""
        return ((1500 - pitch_pulse) * SERVO_DEG_PER_US
                + self._pitch_offset_deg)

    def _lattice_grid_fit(self, pix_obs, ambig=None):
        """参数网格自标定 + 格阵拟合 → LatticeFit

        相机安装偏移/高度无法精确预知（装配离散、俯仰随头部姿态微变），在
        (偏移, 高度) 网格上逐组合做"机器人系映射 + 逐数字聚合 + 格阵拟合"。
        格阵归属是离散判定——落在拟合容差谷值内的组合给出同一布局，多数票
        即布局；胜出组合的中位数即自标定常数（写回调用方）。

        pix_obs: [(pitch, head, digit, 观测像素, 裁切?), ...]（跨帧全部观测）

        聚合策略（2026-09-11 现场照片 + 真机布局扫实测驱动）：
          - **最大一致簇取模式**：同一数字的多次观测先按 CLUSTER_RADIUS_CM
            邻域聚类，取点数最多的一簇（真机实测：场内木框被橙色阈值命中、
            蓝地垫被蓝色阈值命中，且多为**未裁切**观测——单纯"干净优先的
            中位数"会被它们带到 40cm 外，格阵拟合整体失败）；
          - 簇内**干净优先**：有未裁切观测就只用未裁切观测（裁切质心偏差
            实测 1.3~8.4cm）；否则用簇内裁切观测并把权重降到
            LATTICE_CLIPPED_WEIGHT；簇外观测计入 dropped 供告警/诊断。
        退化提醒：只有单档俯仰有观测时，安装偏移与名义俯仰角不可分离
        （实测 (pitch1200, offset=25°) 与 (pitch1040, offset=10°) 等价，
        有效俯角都 ≈51.5°），此时自标定常数不可外推到另一档 → warnings。
        """
        warnings = []
        pitches_seen = {e[0] for e in pix_obs}
        if len(pitches_seen) < 2:
            warnings.append(
                f"仅 {sorted(pitches_seen)} 单档俯仰有观测：安装偏移与名义"
                "俯仰角退化，自标定常数不可外推到另一档")
        hg_cache = {}
        obs_by_digit = {}          # digit -> [(pitch, head, px, clipped), ...]
        for _pitch, _head, _d, _px, _cl in pix_obs:
            obs_by_digit.setdefault(_d, []).append(
                (int(_pitch), int(_head), _px, bool(_cl)))

        def _hg(pitch, pulse, off, hcm):
            key = (int(pitch), int(pulse), float(off), float(hcm))
            hg = hg_cache.get(key)
            if hg is None:
                hg = GroundHomography.from_pose(
                    (0.0, 0.0), float(hcm), pitch, head_pulse=pulse,
                    pitch_offset_deg=float(off))
                hg_cache[key] = hg
            return hg

        def _aggregate(off, hcm):
            """逐数字机器人系点聚合 → (med, clean, wts, spread, dropped, sel)

            现场实测（2026-09-11 真机布局扫 photo_1789127899~909）：场内木框
            被橙色阈值命中、蓝地垫被蓝色阈值命中，且它们是**未裁切**观测——
            "干净优先的中位数"会被它们带到 40cm 外，整个格阵拟合失败。
            故先按"最大一致簇"取模式，再在簇内干净优先；簇外观测计 dropped。
            sel[d] = 该数字**入选观测在 obs_by_digit[d] 中的下标**，供像素域
            精修复用（精修必须只用同一批内点，否则假阳会把重投影解带飞）。
            """
            med, clean, wts, spread, dropped, sel = {}, set(), {}, {}, {}, {}
            for d, lst in obs_by_digit.items():
                pts = np.array([_hg(pitch, pulse, off, hcm).pixels_to_ground(
                    [px], head_pulse=pulse)[0]
                    for pitch, pulse, px, _cl in lst])
                flags = np.array([cl for _p, _h, _px, cl in lst])
                if len(pts) > 1:
                    dm = np.linalg.norm(pts[:, None, :] - pts[None, :, :], axis=2)
                    n_in = (dm <= CLUSTER_RADIUS_CM).sum(axis=1)
                    keep = dm[int(np.argmax(n_in))] <= CLUSTER_RADIUS_CM
                else:
                    keep = np.ones(len(pts), dtype=bool)
                n_clean = int(np.count_nonzero(keep & ~flags))
                use_mask = keep & ~flags if n_clean >= 1 else keep
                use = pts[use_mask]
                m = np.median(use, axis=0)
                med[d] = m
                spread[d] = float(np.max(np.linalg.norm(use - m, axis=1)))
                dropped[d] = int(np.count_nonzero(~keep))
                sel[d] = [int(k) for k in np.where(use_mask)[0]]
                if n_clean >= 1:
                    clean.add(d)
                    wts[d] = 1.0
                else:
                    wts[d] = LATTICE_CLIPPED_WEIGHT
            return med, clean, wts, spread, dropped, sel

        votes = {}   # (数字→格)冻结元组 -> [每个成功组合的拟合明细, ...]
        dropped_seen = {}
        for off in np.arange(LAYOUT_OFFSET_MIN_DEG,
                             LAYOUT_OFFSET_MAX_DEG + 1e-9,
                             LAYOUT_OFFSET_STEP_DEG):
            for hcm in np.arange(LAYOUT_HEIGHT_MIN_CM,
                                 LAYOUT_HEIGHT_MAX_CM + 1e-9,
                                 LAYOUT_HEIGHT_STEP_CM):
                med, clean, wts, spread, dropped, sel = _aggregate(off, hcm)
                if len(med) < 7:
                    continue
                for d, n in dropped.items():
                    if n:
                        dropped_seen[d] = max(dropped_seen.get(d, 0), n)
                cells, _info, ranked = lattice_assign(med, weights=wts,
                                                      clean=clean)
                if cells is None or len(cells) != 7 or not ranked:
                    continue
                votes.setdefault(tuple(sorted(cells.items())), []).append({
                    "off": float(off), "hcm": float(hcm), "med": med,
                    "clean": set(clean), "wts": dict(wts),
                    "spread": dict(spread), "sel": sel,
                    "rms_clean": ranked[0]["rms_clean"],
                    "rms_all": ranked[0]["rms_all"],
                    "res_max": ranked[0]["res_max_cm"]})
        if not votes:
            return _fit_failure(
                "全部参数组合均无法一致拟合 33cm 方格阵（观测含异常点、"
                "数字与格位对应关系不符，或可见数字不足）", warnings)
        key, combos = max(votes.items(), key=lambda kv: len(kv[1]))
        n_assign = sum(len(v) for v in votes.values())
        if len(combos) < LAYOUT_VOTE_MIN_FRAC * n_assign \
                or len(combos) < LAYOUT_VOTE_MIN_COMBOS:
            others = sorted((len(v) for k, v in votes.items() if k != key),
                            reverse=True)
            return _fit_failure(
                f"参数网格投票不足（得票 {len(combos)}/{n_assign}，"
                f"次高得票 {others[:2]}）——前进一步后重新扫描以消除歧义",
                warnings)
        cells = dict(key)
        off = float(np.median([c["off"] for c in combos]))
        hcm = float(np.median([c["hcm"] for c in combos]))
        # 取最接近中位数的那个组合的几何数据作为基准（可复现、可诊断）
        pick = min(combos, key=lambda c: (
            abs(c["off"] - off) / LAYOUT_OFFSET_STEP_DEG
            + abs(c["hcm"] - hcm) / LAYOUT_HEIGHT_STEP_CM))
        # 像素域五参数联合精修（关键步骤，见 _pixel_pose_calib）：格阵刚性判据
        # 对 (安装偏移, 相机高度) 只有一条退化谷（sim 实测 (18.5°,56cm) 与
        # (19.5°,59cm) 刚体 RMS 都是 0.30cm），而导航投影对谷内位置很敏感
        # （高度差 3cm → GN 残差 16~23px → 定位风暴）。故用"格心↔像素"重投影
        # 残差（与导航同一残差定义）联合解出 (x, y, θ, 偏移, 高度)。
        ds = sorted(pick["med"])
        gs = np.array([grid_cell_center(cells[d]) for d in ds])
        ps = np.array([pick["med"][d] for d in ds])
        ws = np.array([pick["wts"].get(d, 1.0) for d in ds])
        R0, t0, _rms0, _per0 = _rigid_fit_2d(gs, ps, ws)
        pos0 = -R0.T @ t0
        fwd0 = R0.T @ np.array([0.0, 1.0])
        pose0 = np.array([pos0[0], pos0[1], float(np.arctan2(fwd0[0], fwd0[1]))])
        entries = []
        for d, pos_list in pick["sel"].items():
            if d not in cells:
                continue
            for k in pos_list:
                pitch, head, px, cl = obs_by_digit[d][k]
                entries.append((grid_cell_center(cells[d]), px, head, cl, pitch))
        pose5, rms_all_px, med_px = _pixel_pose_calib(entries, pose0, off, hcm)
        pose = None
        if pose5 is not None and med_px is not None \
                and med_px <= PIXEL_CALIB_MED_MAX_PX:
            o2, h2 = float(pose5[3]), float(pose5[4])
            med2, clean2, wts2, spread2, _dr2, sel2 = _aggregate(o2, h2)
            cells2, _i2, ranked2 = lattice_assign(med2, weights=wts2,
                                                  clean=clean2)
            if cells2 == cells and ranked2:
                off, hcm = o2, h2
                pick = {"off": off, "hcm": hcm, "med": med2, "clean": clean2,
                        "wts": wts2, "spread": spread2, "sel": sel2,
                        "rms_clean": ranked2[0]["rms_clean"],
                        "rms_all": ranked2[0]["rms_all"],
                        "res_max": ranked2[0]["res_max_cm"]}
                pose = np.array([pose5[0], pose5[1], pose5[2]])
                warnings.append(
                    f"像素级校准结果: 相机相对机体前偏 {off:+.1f}°、"
                    f"离地 {hcm:.1f}cm"
                    f"（格心重投影残差 中位 {med_px:.1f}px／均方根 "
                    f"{rms_all_px:.1f}px）")
            else:
                warnings.append("像素级校准所得的相机参数与已确定的布局不一致"
                                "——已忽略本次校准，沿用格阵拟合所得参数")
        else:
            warnings.append(
                "像素级校准未收敛（格心重投影残差中位 "
                f"{'无数据' if med_px is None else format(med_px, '.1f') + 'px'} "
                f"> {PIXEL_CALIB_MED_MAX_PX:.0f}px）——沿用格阵拟合所得参数，"
                "导航精度可能下降")
        clipped_only = sorted(d for d in cells if pick["wts"].get(d, 1.0) < 1.0)
        if clipped_only:
            warnings.append(
                f"数字 {clipped_only} 无完整可见的观测，仅由贴边观测的质心定位"
                f"（偏差可达约 8cm）")
        if dropped_seen:
            warnings.append(
                f"数字 {sorted(dropped_seen)} 的部分观测位置异常，已剔除"
                f"（每号最多 {max(dropped_seen.values())} 帧）；"
                "疑似场内同色物体被误检为面板（木框、地垫）")
        bad_spread = sorted(d for d, s in pick["spread"].items()
                            if s > SPREAD_MAX_CM)
        if bad_spread:
            warnings.append(
                f"数字 {bad_spread} 的观测分散度超过 {SPREAD_MAX_CM:.0f}cm，"
                "观测质量差")
        if 6 in cells.values():
            warnings.append("格位 6 被判为有面板占据：与比赛规则冲突——"
                            "数字与格位的对应关系或站位存疑，需现场逐格核对")
        spread_max = max(pick["spread"].values()) if pick["spread"] else 0.0
        info = (f"参数组合 {len(combos)}/{n_assign} 收敛（{len(pick['clean'])} 个"
                f"数字有完整可见的观测，同一数字各帧偏差 ≤{spread_max:.1f}cm）")
        # 歧义修复（E）：颜色歧义面板（同位置双色命中 / 中位 H 贴窗口边界）
        # 若形状仲裁没能定案，这里用**格阵共识**复核一次——置信数字先定刚体
        # 变换，再看歧义数字的观测点离"本格"还是"竞争数字那格"更近。
        cells, rep_notes = ambiguity_repair(cells, pick, ambig or {})
        for n in rep_notes:
            warnings.append(n)
            print(f"[布局] 歧义修正: {n}")
        return LatticeFit(cells=cells, info=info, offset_deg=off,
                          cam_height_cm=hcm, pts_robot=dict(pick["med"]),
                          clean=set(pick["clean"]), weights=dict(pick["wts"]),
                          rms_clean_cm=pick["rms_clean"],
                          rms_all_cm=pick["rms_all"],
                          spread_cm=dict(pick["spread"]),
                          res_max_cm=pick["res_max"], warnings=warnings,
                          pose=pose)

    def _pose_bootstrap(self, fit):
        """位姿自举 → 直接写 self.pose，返回 bool

        两条路径：
          1) **优先用像素域精修位姿**（fit.pose，见 _pixel_pose_calib）：它由
             "格心↔像素"重投影最小二乘得到，与导航同一残差定义、同一常数，
             精度最高；
          2) 回退用"机器人系点 ↔ 场地格心"2D 刚体拟合（两系同为 z 轴向上的
             地面系，只差一个刚体变换）。
        两条路都不再解"像素↔格心"单应再 decompose——那条路把裁切质心观测
        （偏差实测 1.3~8.4cm）送进无鲁棒最小二乘，会给出非物理 H
        （历史崩溃："相机未俯视地面（光轴无向下分量）"）。
        自检：残差门、机器人在入口侧、位置落在场地合理范围；任一不满足 → False。
        """
        ds = sorted(fit.pts_robot)
        if len(ds) < 4 or not fit.cells or any(d not in fit.cells for d in ds):
            print("[布局] 由面板反推位姿失败：格阵拟合结果不完整，无法反推位姿")
            return False
        gs = np.array([grid_cell_center(fit.cells[d]) for d in ds])
        if fit.pose is not None:
            pos = np.asarray(fit.pose[:2], dtype=np.float64)
            th = float(fit.pose[2])
            gate_txt = "像素级校准所得位姿"
        else:
            ps = np.array([fit.pts_robot[d] for d in ds])
            w = np.array([1.0 if d in fit.clean else LATTICE_CLIPPED_WEIGHT
                          for d in ds])
            R, t, rms_all, per = _rigid_fit_2d(gs, ps, w)
            idx = [k for k, d in enumerate(ds) if d in fit.clean]
            if len(idx) >= 3:
                gate_val = float(np.sqrt(np.mean(per[idx] ** 2)))
                gate_txt = f"刚体残差 干净子集 {gate_val:.1f}cm"
            else:
                gate_val, gate_txt = rms_all, f"刚体残差 全点 {rms_all:.1f}cm"
            if gate_val > POSE_BOOTSTRAP_RMS_MAX_CM:
                print(f"[布局] 由面板反推位姿未通过校验：{gate_txt} > "
                      f"{POSE_BOOTSTRAP_RMS_MAX_CM:.0f}cm（布局或观测存疑）")
                return False
            pos = -R.T @ t                  # 机器人系原点的场地坐标（相机地面投影）
            fwd = R.T @ np.array([0.0, 1.0])   # 机器人系 +y（机体前方）的场地方向
            th = float(np.arctan2(fwd[0], fwd[1]))
        if not (POSE_BOOTSTRAP_X_RANGE[0] <= pos[0] <= POSE_BOOTSTRAP_X_RANGE[1]
                and POSE_BOOTSTRAP_Y_RANGE[0] <= pos[1]
                <= POSE_BOOTSTRAP_Y_RANGE[1]):
            print(f"[布局] 由面板反推位姿未通过校验：位置 ({pos[0]:.1f},{pos[1]:.1f}) "
                  "超出场地合理范围")
            return False
        if pos[1] >= float(np.min(gs[:, 1])) + GRID_CELL_CM / 2:
            print("[布局] 由面板反推位姿未通过校验：机器人不在全部面板的入口一侧")
            return False
        self.pose = np.array([pos[0], pos[1], th])
        print(f"[定位] 机器人位置 ({pos[0]:.1f},{pos[1]:.1f})，"
              f"航向 {np.degrees(th):.1f}°（依据 {gate_txt}，{len(ds)} 个数字）")
        return True

    # =================================================================
    # 定位：Gauss-Newton 地图定位（格心=地图，动作模型=先验）
    # =================================================================

    def predict_pose(self, action, times=1):
        """按名义动作模型推进位姿预测（每步动作后调用）

        小步转向的名义角用 EMA 在线估计值（地面打滑时它更接近真值）。
        """
        kind, step = ACTION_MODEL.get(action, (None, 0.0))
        if action.endswith("_small_step") and kind == "turn":
            step = (self._small_turn_deg if step > 0 else -self._small_turn_deg)
        for _ in range(max(1, times)):
            th = self.pose[2]
            fwd = np.array([np.sin(th), np.cos(th)])
            right = np.array([np.cos(th), -np.sin(th)])
            if kind == "fwd":
                self.pose[:2] += fwd * step
            elif kind == "lat":
                self.pose[:2] += right * step
            elif kind == "turn":
                self.pose[2] += np.radians(step)

    def _capture_corr(self, pitch, arbitrate=False):
        """拍照+检测，返回 (corr, obs, frame)

        corr 元素 = (格心场地坐标, 观测像素, 采集时头部脉宽, 是否被画幅裁切)：
        - 未裁切：观测取对角线交点 center_px（面板中心的精确投影）；
        - 已裁切：观测取颜色掩膜凸包质心 hull_centroid_px（裁切不变）。
        """
        frame = self.state.capture_frame()
        if frame is None:
            return [], None, None
        obs = self.detector.detect_panels(frame, arbitrate=arbitrate)
        head = self.state.current_head_pulse
        corr = []
        for o in obs:
            if o.digit not in self.digit_cell:
                continue
            px = o.hull_centroid_px if o.clipped else o.center_px
            corr.append((grid_cell_center(self.digit_cell[o.digit]),
                         px, head, o.clipped))
        return corr, obs, frame

    def localize(self, pitch=PITCH_NAV, arbitrate=False, min_panels=1):
        """拍照 → 检测 → >=min_panels 面板 GN 精化位姿（门控后写入 self.pose）

        min_panels 缺省 1：近距时目标面板常是唯一可见面板（其它在身后/视野
        外），此时靠弱先验正则（σ=8cm/8°）约束不可观测方向仍可解——只允许
        >=2 会退化成"头部扫→0 点→恢复"的拍照风暴（实测 64% 定位走该分支）。
        面板不足时做头部左右小扫（零身体位移，零风险）把侧向面板转进视野，
        跨帧合并对应点（每点带自己的头部角）再解。
        返回 (obs_list, frame)；失败返回 None（self.pose 保持预测值）。
        """
        self._loc_count += 1
        corr, obs, frame = self._capture_corr(pitch, arbitrate)
        if len(corr) >= min_panels:
            # 单帧优先：无头部斜视角偏差，门控最严、精度最高
            pose = self._gn_localize(self.pose.copy(), corr, pitch)
            if pose is not None:
                self.pose = pose
                return obs, frame
        # 头部左右小扫合并对应点：贴近段面板常被裁切/出画，单帧可能不足
        merged = list(corr)
        for h in (HEAD_LEFT, HEAD_RIGHT):
            self.state.set_head(h)
            more, _, _ = self._capture_corr(pitch, arbitrate)
            merged.extend(more)
        self.state.set_head(HEAD_CENTER)
        if len(merged) < min_panels:
            print(f"[定位] 合并头部扫视后仅 {len(merged)} 个对应点（需 ≥{min_panels} 个）")
            return None
        pose = self._gn_localize(self.pose.copy(), merged, pitch,
                                 gate_px=GN_PIXEL_GATE_MERGED)
        if pose is None:
            return None
        self.pose = pose
        return obs, frame

    def _gn_localize(self, p0, corr, pitch, gate_px=GN_PIXEL_GATE):
        """以 p0=(x,y,θ) 为先验做惰性多起点 GN 定位

        先解先验起点；RMS 已达标（GN_RMS_OK_PX）就不再试扰动起点，否则补
        ±8cm/±10° 起点取最优。门控：RMS(gate_px) + 相对先验跳变。
        失败返回 None（调用方维持预测位姿）。
        """
        starts = [np.array(p0, dtype=np.float64)]
        for dxy in ((8, 0), (-8, 0), (0, 8), (0, -8)):
            st = np.array(p0, dtype=np.float64)
            st[0] += dxy[0]
            st[1] += dxy[1]
            starts.append(st)
        for dth in (np.radians(10), -np.radians(10)):
            st = np.array(p0, dtype=np.float64)
            st[2] += dth
            starts.append(st)
        best = None
        for st in starts:
            out = self._gn_run(st, corr, pitch)
            if out is None:
                continue
            p, rms = out
            if best is None or rms < best[1]:
                best = (p, rms)
            if best[1] <= GN_RMS_OK_PX:
                break
        if best is None:
            return None
        p, rms = best
        if rms > gate_px:
            print(f"[定位] 重投影残差均方根 {rms:.1f}px 超过阈值（{gate_px:.0f}px），本次定位作废")
            return None
        jump = float(np.hypot(p[0] - p0[0], p[1] - p0[1]))
        dth = abs(_wrap_angle(p[2] - np.asarray(p0)[2]))
        if jump > GN_JUMP_CM or dth > GN_JUMP_DEG:
            print(f"[定位] 位置跳变 {jump:.1f}cm、航向跳变 {np.degrees(dth):.0f}° 超过允许范围，本次定位作废")
            return None
        return p

    def _gn_run(self, p0, corr, pitch):
        """单起点鲁棒 GN：裁切感知观测 + IRLS(Cauchy) + 弱先验正则 + 一轮剔除

        返回 (p, rms)；rms 只统计保留对应点的残差（先验行不计），供门控使用。
        """
        # 兼容 3 元组（旧格式/外部调用）：按未裁切处理
        entries = [t if len(t) == 4 else (t[0], t[1], t[2], False)
                   for t in corr]
        cells = np.array([c for c, _, _, _ in entries], dtype=np.float64)
        dets = np.array([d for _, d, _, _ in entries], dtype=np.float64)
        heads = np.array([h for _, _, h, _ in entries], dtype=np.float64)
        clipped = np.array([b for _, _, _, b in entries], dtype=bool)
        used = np.ones(len(entries), dtype=bool)
        p0a = np.array(p0, dtype=np.float64)
        sig_xy = GN_PRIOR_SIGMA_XY_CM
        sig_th = np.radians(GN_PRIOR_SIGMA_TH_DEG)

        def residuals(pp, mask):
            """对应点残差 (n_used, 2)；预测端按裁切与否选中心/裁切质心"""
            idx = np.where(mask)[0]
            out = np.empty((len(idx), 2))
            for k, i in enumerate(idx):
                if clipped[i]:
                    pc = clipped_quad_centroid(
                        cells[i], pp[0], pp[1], pp[2], pitch, heads[i],
                        pitch_offset_deg=self._pitch_offset_deg,
                        cam_height_cm=self._cam_height_cm)
                    if pc is None:
                        return None
                else:
                    pc = project_ground_to_pixel(
                        cells[i], pp[0], pp[1], pp[2], pitch, heads[i],
                        pitch_offset_deg=self._pitch_offset_deg,
                        cam_height_cm=self._cam_height_cm)[0]
                out[k] = pc - dets[i]
            return out

        def solve_once(p):
            r = residuals(p, used)
            if r is None:
                return None
            r = r.ravel()
            n2 = r.size
            for _it in range(GN_MAX_ITERS):
                J = np.zeros((n2 + 4, 3))
                for j in range(3):
                    eps = [0.5, 0.5, np.radians(0.5)][j]
                    pp = p.copy(); pp[j] += eps
                    r1 = residuals(pp, used)
                    pp = p.copy(); pp[j] -= eps
                    r2 = residuals(pp, used)
                    if r1 is None or r2 is None:
                        return None
                    J[:n2, j] = ((r1 - r2) / (2 * eps)).ravel()
                # 弱先验正则：低观测（1~2 点）时把解拉向运动先验
                J[n2, 0] = 1.0 / sig_xy
                J[n2 + 1, 1] = 1.0 / sig_xy
                J[n2 + 2, 2] = 1.0 / sig_th
                rp = np.concatenate([r,
                                     [(p[0] - p0a[0]) / sig_xy,
                                      (p[1] - p0a[1]) / sig_xy,
                                      (p[2] - p0a[2]) / sig_th,
                                      0.0]])
                # Cauchy 鲁棒权重按"点"给（同一面板 x/y 同权），先验行恒权 1
                per = np.linalg.norm(r.reshape(-1, 2), axis=1)
                w = 1.0 / (1.0 + (per / GN_CAUCHY_C_PX) ** 2)
                w_flat = np.concatenate([np.repeat(w, 2), np.ones(4)])
                try:
                    delta = np.linalg.solve(
                        J.T @ (J * w_flat[:, None]) + 1e-6 * np.eye(3),
                        -(J.T @ (rp * w_flat)))
                except np.linalg.LinAlgError:
                    return None
                delta = np.clip(delta, [-15, -15, -np.radians(20)],
                                [15, 15, np.radians(20)])
                p = p + delta
                p[2] = _wrap_angle(p[2])
                r = residuals(p, used)
                if r is None:
                    return None
                r = r.ravel()
                if np.max(np.abs(delta[:2])) < 0.02 \
                        and abs(delta[2]) < np.radians(0.02):
                    break
            return p, r

        p = np.array(p0a, dtype=np.float64)
        out = solve_once(p)
        if out is None:
            return None
        p, r = out

        # 一轮离群剔除（误检防护）：点数 >=5 才做，剔除后仍须 >=2 点
        per_point = np.linalg.norm(r.reshape(-1, 2), axis=1)
        if used.sum() >= 5 and per_point.max() > GN_OUTLIER_PX:
            idx = np.where(used)[0]
            used[idx[per_point > GN_OUTLIER_PX]] = False
            if used.sum() < 2:
                return None
            out = solve_once(p)
            if out is None:
                return None
            p, r = out
            per_point = np.linalg.norm(r.reshape(-1, 2), axis=1)

        rms = float(np.sqrt(np.mean(per_point ** 2))) if per_point.size else 1e9
        return p, rms

    def target_relative(self, digit):
        """目标格心在机器人系的 (纵向, 横向, 航向差)。右正左负。"""
        x, y, th = self.pose
        fwd = np.array([np.sin(th), np.cos(th)])
        right = np.array([np.cos(th), -np.sin(th)])
        body = np.array([x, y]) - fwd * CAMERA_TO_BODY_FORWARD_CM
        d = grid_cell_center(self.digit_cell[digit]) - body
        forward = float(d @ fwd)
        lateral = float(d @ right)
        bearing = float(np.degrees(np.arctan2(lateral, forward)))
        return forward, lateral, bearing

    # =================================================================
    # 单格导航 FSM：视觉伺服 v3（搜索→对准→接近→低头到达→蹭步确认）
    # 地图路径 v2 保留在 _go_to_panel_map / _approach / _enter（应急开关）
    # =================================================================

    def go_to_panel(self, digit):
        """前往第 digit 块面板；返回 bool（视觉到位并完成蹭步）

        **唯一路径 = 统一决策**（`_go_to_panel_unified`）：三档分区 ＋ 一个循环，
        每帧同一套判据、一次决策一个原语。三段式链路已按
        《需求规格-2026-09-25-统一决策重写》§7.1 删除。

        **硬熔断保证**：本函数一定在"单格预算"内返回（见 _cell_budget_begin /
        _cell_expired）。任何子环节卡住，都会在 t_end 或 VIS_CELL_HARD_* 处被
        `_cell_expired` 拦下 → 本格记为未确认（results 里 False、cell_trips 记原因）
        → 立刻返回 False，不再动作。
        """
        try:
            if UNIFIED_NAV_ENABLED:
                return self._go_to_panel_unified(digit)
            return self._go_to_panel_v3(digit)
        finally:
            # 真值落点留档（诊断/回归用，不参与控制）：**必须在返回前记**，
            # 因为调用方随后就会走向下一格，事后再取位置已经不是这一格的落点。
            # SimNineGridRobot 有 .pos（真值），真机 RobotState 两者都没有 →
            # 取不到就留 None，对真机零影响。
            self._record_landing(digit)

    def _record_landing(self, digit):
        """把"跑完本格时机器人离目标格格心的距离"记进 self.panel_landing

        真机（无真值）退化为用死推位姿 self.pose 估计，并在日志里标明来源；
        仿真里 state.pos 是真值，因此这个数字可以用来抓"假到达"。
        """
        cell = self.digit_cell.get(digit)
        if cell is None:
            self.panel_landing[digit] = None
            return
        center = np.asarray(grid_cell_center(cell), float)
        truth = getattr(self.state, "pos", None)
        if truth is not None:
            src, pos = "真值", np.asarray(truth, float)[:2]
        else:
            src, pos = "死推", np.asarray(self.pose, float)[:2]
        self.panel_landing[digit] = (float(np.linalg.norm(pos - center)), src)

    def _go_to_panel_unified(self, digit):
        """★ 统一决策（P1，唯一路径）：三档分区 ＋ 一个循环走完全程

        与旧三段式（`_seek_align_approach` + `_arrive_visual`）的对照：

        | | 三段式（已删） | 本法 |
        |---|---|---|
        | 决策依据 | ALIGN `\\|yaw\\|≤12°` / APPROACH 框宽≥920px / ARRIVE 色占比回落，**三段三套** | **每帧同一套** `_zone_of_px_body` → 直行/横移/旋转 |
        | 交棒 | 有交棒点 ⇒ 交棒 yaw 残余留给低头段兜 | **没有交棒点**，也就没有这个漏 |
        | 每次下发几个原语 | 批量（`n = floor(\\|yaw\\|/步长)`，最多 6） | **恒为 1 个**（用户明确放弃批量） |
        | yaw 的用途 | 数值 → 规划步数 | **只作伺服增益**，判档纯像素 |
        | 死推 | 搜索提示/盲走/护栏都吃它 | **只进遥测**，不进决策 |
        | 取景档 | 导航档/低头档两档切换 | **全程 1040**（用户："1040 是最好的"） |

        到达判据沿用"只看当前帧"的四量（紫/橙/左右不对称/几何锚），
        不含任何历史 ⇒ 原地转身、偏头、遮挡都不会让它误成立。
        """
        t_end = self._cell_budget_begin(digit)
        self._target_seen = False
        self._loc_count = 0
        self._current_digit = digit
        self._turn_updates = 0
        setter = getattr(self.state, "set_deform_digit", None)
        if setter is not None:
            setter(digit)
        color = self._target_color(digit)
        self.phase = f"DRIVE{digit}"
        pitch0 = getattr(self.state, "pitch", None)
        self.state.set_pitch(PITCH_DOWN)
        lost = 0
        turns = 0
        self._reacq_deg = 0.0          # 本轮重捕获已累计转过的角度
        self._reacq_frames = 0
        self._reacq_dir = None         # 本轮重捕获的转向方向（一次定死）
        self._reacq_flipped = False    # 是否已"单向扫够后反向"过一次
        prev_zone = None
        prev_cov = None
        prev_org = None
        stall = 0
        try:
            for _ in range(UNIFIED_MAX_ITERS):
                if time.time() > t_end or self._cell_expired():
                    return False
                p = self._perceive(color)
                if p is None:
                    return False
                self._reacq_frames += 1
                sh = p["shares"]
                # ---- 到达证据（只看当前帧）----
                # ★ 前置条件：**目标必须在画面中央附近**（`VIS_ARRIVE_CENTER_MAX`）。
                # 为什么必须有：四个份额是**整帧**统计量，目标偏在一侧时色块与
                # 分区边界的交叠关系完全变了 —— 实测"面板在正前方"要到 ≤4cm 才成立，
                # 而"面板偏在侧面"时判据会**提前成立**（落点实测差整整一格 33cm，
                # 8 个种子里有 5 个出现 66~71cm 的落点）。
                # 站在格心上时面板必然在正前方 ⇒ 这一条是"压到了"的必要条件，
                # 顺带把"横向没对正就宣布到达"也堵掉。
                if VIS_ARRIVE_REGION_ENABLED and sh is not None:
                    _whole, pur, org, asym = sh
                    _centered = True
                    if p["obs"] is not None and VIS_ARRIVE_CENTER_MAX > 0.0:
                        _dx = abs(p["px"] - self._col_forward(p["w"])) / p["w"]
                        _centered = _dx <= VIS_ARRIVE_CENTER_MAX
                    # ★ 面板必须**够大**（压在脚下）——"假到达"的直接解药，已实测。
                    # 已定位的骗门机制（seed11 d3，站位 (41.4,82.6)、目标在 66cm 外）：
                    # 航向 −40° 时目标是**边缘斜视的残缺投影**（远侧一半出画幅）
                    # ⇒ 橙区拿到 **0.000**（本该 0.48）、紫区拿到 0.637 ⇒ 门成立。
                    # 四个整帧份额在"残缺投影"下全部失真 ⇒ 必须另加**尺度**判据。
                    #
                    # 判据选型（都实测过，别重复走）：
                    #   ✅ **整帧目标色占比 ≥ 0.065**（本行）：真到达 0.078~0.150、
                    #      骗门帧 0.042 ⇒ 4 种子实测**超半格 4→0**、最大落点
                    #      66.9→10.5cm。代价：到达率 96.4%→85.7%、拍照 466→609/局
                    #      （因为"站得稍远一点"的正常到达也会被这条压住）。
                    #   ❌ **目标 hull_area ≥ 300000**：看着更干净（真到达 418288 vs
                    #      骗门帧 210950，差 2 倍），但实测**反而更差** ——
                    #      超半格 5、出现 78~80cm 落点。原因：同一色面板在**邻格**
                    #      被近距离看到时 hull 同样很大，面积判不出"是不是脚下这一块"。
                    #   ❌ **收紧 center_max 到 0.04/0.06/0.08**：到达率掉到 10~21/28
                    #      且**仍有** 78~82cm 落点 ⇒ 方向错。
                    _big = (_whole >= VIS_ARRIVE_MIN_COVER
                            if VIS_ARRIVE_MIN_COVER > 0.0 else True)
                    # 形状门：目标观测 bbox 的**宽/高比上限** —— 专治"斜视/残缺投影"。
                    # ⚠️ 方向与上一版**相反**（上一版用高/宽比下限 0.46，只挡掉 5 帧里的
                    # 2 帧；用真值标定后发现正确方向是"宽/高比不能太大"）。
                    # 标定（tools/_tmp_arrive_gate_probe.py，11 帧真到达 / 5 帧假到达）：
                    #     真到达 宽/高 **1.53 ~ 2.07**（中位 1.66）
                    #     假到达 宽/高 **2.25 ~ 2.49**（全是又扁又斜的残缺投影）
                    #   ⇒ 取 **2.15**（两簇之间，两侧各留 ~0.08 余量）。
                    if VIS_ARRIVE_MAX_BW_OVER_BH > 0.0 and p["obs"] is not None:
                        _bw = float(p["obs"].bbox[2])
                        _bh = float(p["obs"].bbox[3])
                        if _bh > 1.0 and _bw / _bh > VIS_ARRIVE_MAX_BW_OVER_BH:
                            _big = False
                    # ★ 邻近门：像宽 ∝ 1/距离 ⇒ "压到脚下"必然像宽很大。
                    #   标定两簇不重叠（真 1158~1336 ｜ 假 272~1106）⇒ 取 1120。
                    if VIS_ARRIVE_MIN_BOX_PX > 0.0 and p["box"] < VIS_ARRIVE_MIN_BOX_PX:
                        _big = False
                    if _centered and _big and pur >= VIS_ARRIVE_PURPLE_MIN \
                            and org <= VIS_ARRIVE_ORANGE_MAX \
                            and abs(asym) <= VIS_ARRIVE_ASYM_MAX:
                        # ★ 最后一道：**格的同一性核验**（用户方案 ②-a）。
                        # 份额/形状类判据在"站在别格、看到完整同色面板"时全部正常，
                        # 只有"这一帧几何能否被地图解释"能分辨 ⇒ 解一次实测位姿。
                        _verdict, _why = self._on_target_cell(p["frame"], digit)
                        # "no" 一律拒绝；"unknown"（锚弃权）按开关决定
                        # ——默认放行，否则会把大量正常到达一起误杀（锚可用率仅 ~16%）。
                        _ok_cell = (_verdict == "yes"
                                    or (_verdict == "unknown"
                                        and not VIS_ARRIVE_ONCELL_REQUIRE))
                        if not _ok_cell:
                            print(f"[行进] 面板{digit} 色块判据成立但**格的核验否决**"
                                  f"（{_why}）→ 不判到达，继续逼近")
                            prev_cov, prev_org = None, None
                            continue
                        if _verdict == "yes":
                            print(f"[核验] 面板{digit} 格的同一性通过：{_why}")
                        self._arrive_evidence = (
                            f"脚下色块判据：紫区占比 {pur:.3f}（≥"
                            f"{VIS_ARRIVE_PURPLE_MIN}），橙区占比 {org:.3f}（≤"
                            f"{VIS_ARRIVE_ORANGE_MAX}），左右不对称 {asym:+.3f}"
                            f"（≤{VIS_ARRIVE_ASYM_MAX}）"
                            + (f"；格的核验: {_why}" if _verdict != "unknown"
                               else f"；格的核验: 弃权（{_why}）"))
                        print(f"[行进] 面板{digit} 区域判据成立（紫 {pur:.3f}、"
                              f"橙 {org:.3f}、不对称 {asym:+.3f}）→ 判定到达")
                        return True
                o = p["obs"]
                if o is None:
                    lost += 1
                    turns, stepped = self._unified_reacquire(digit, lost, turns, p)
                    if turns < 0:
                        return False
                    self._reacq_deg += abs(stepped)
                    if stepped and (self._reacq_deg > VIS_REACQ_MAX_TURN_DEG
                                    or self._reacq_frames > VIS_REACQ_MAX_FRAMES):
                        print(f"[重捕获] 面板{digit} 已转 {self._reacq_deg:.0f}°"
                              f"／{self._reacq_frames} 帧仍未见到目标 → 放弃本格")
                        return False
                    continue
                lost = 0
                turns = 0
                self._reacq_deg = 0.0
                self._reacq_frames = 0
                self._reacq_dir = None
                self._reacq_flipped = False
                # ---- 三档分区（判档只吃像素）----
                head_pulse = getattr(self.state, "current_head_pulse",
                                     HEAD_CENTER)
                zone, dx_body = self._zone_of_px_body(
                    p["px"], p["py"], p["w"], p["h"], head_pulse,
                    self._zone_last)
                self._zone_last = zone
                # 记"最后一次看到它在哪一侧"——丢失后自转搜索靠它定方向
                self._last_seen_side = (1.0 if p["px"] < p["w"] / 2.0 else -1.0)
                px_body = p["px"] - (self._col_forward(p["w"], head_pulse)
                                     - p["w"] / 2.0)
                act = self._action_for_zone(zone, px_body, p["w"])
                yaw_gain = self._body_yaw_deg(p["px"], p["w"], head_pulse)
                # ---- 前进的**快慢两档**：远距多走几步、近距一步一复测 ----
                # ★ 分档量用**整帧色占比 `whole`**，不用框宽：
                #   ① 框宽在近距会因裁切**塌陷**（实测同一格 1164→676px 跳变），
                #      而 `whole` 单调且与到达门同源（都在同一张掩膜上算）；
                #   ② 这与旧三段式的"框宽 920px 交棒"是同一个量纲错误的反面教材。
                # 实测 `whole`↔距离（低头 1040，正前方）：
                #   60cm→0.056｜50→0.072｜40→0.092｜35→0.103｜30→0.115｜25→0.126
                #   20→0.137｜15→0.147（**此后随裁切不再增**）
                # ⇒ 近距离必判成 1 步：否则一次 5 步（13cm）会直接把机器人送过格心
                #   （实测：5 步批次把"橙 0.158"一步带到"橙 0.034"并冲过格心 28cm，
                #    框宽判据还误报"前进无效"而触发后退）。
                n = 1
                if zone == "move" and sh is not None:
                    cov = float(sh[0])
                    if cov < VIS_FWD_COV_MID:
                        n = VIS_FWD_FAR_STEPS
                    elif cov < VIS_FWD_COV_NEAR:
                        n = VIS_FWD_MID_STEPS
                # ---- 前进无效脱困：**两个量都没进展**才算无效 ----
                # 判据必须用单调量，且**不能只看整帧占比**：面板走到脚下时有一部分
                # 出了画幅，`whole` 会**正常下降**——只看它就会把"正在压上去"误判成
                # "没走近"，于是"前进→后退→再前进"打成一个极限环（实测面板2：
                # 橙在 0.20↔0.10 之间来回，永远差一点够不着 0.10 的到达门）。
                # 正确的无效签名 = 占比不增 **且** 橙也不减（两个距离代理同时躺平）。
                cov_now = float(sh[0]) if sh is not None else 0.0
                org_now = float(sh[2]) if sh is not None else 0.0
                no_progress = (prev_cov is not None
                               and cov_now - prev_cov < VIS_STALL_COV
                               and prev_org is not None
                               and org_now > prev_org - VIS_STALL_COV)
                if zone == "move" and no_progress:
                    stall += 1
                    if stall >= VIS_STALL_PATIENCE:
                        print(f"[行进] 面板{digit} 无进展（占比 "
                              f"{prev_cov:.3f}→{cov_now:.3f}、橙 {prev_org:.3f}→"
                              f"{org_now:.3f}）→ 后退一步重识别")
                        self._act("back_one_step", 1)
                        stall, prev_cov, prev_org, prev_zone = 0, None, None, None
                        continue
                else:
                    stall = 0
                if zone == "move":
                    prev_cov, prev_org = cov_now, org_now
                else:
                    prev_cov, prev_org = None, None
                print(f"[决策] 面板{digit} 档={_ZONE_CN[zone]} "
                      f"偏角 {yaw_gain:+.1f}°｜横偏 {dx_body * 100:.1f}%画幅"
                      f"｜框宽 {p['box']:.0f}px"
                      + (f"｜紫 {sh[1]:.3f} 橙 {sh[2]:.3f}" if sh else "")
                      + f" → {_action_cn(act, n)}")
                self._act(act, n)          # ★ 一次决策只下发一个原语（前进可带步数）
                prev_zone = zone
            print(f"[行进] 面板{digit} 统一循环迭代次数已达上限")
            return False
        finally:
            if pitch0 is not None:
                self.state.set_pitch(pitch0)

    def _visual_heading_delta_deg(self, frame, obs, head_pulse=None):
        """用**同帧可见的已标注面板**重解航向误差（度，右正）；无解返回 None

        为什么需要它（P1 实测卡点）：`_reanchor_pose` 只把**位置**锚到格心，
        **航向保持死推值**（其 docstring 明说），一格走完航向误差实测 8° 并逐格
        累积 ⇒ 到第 3 格时"地图方位"已指错，机器人按它转就是转错方向。

        原理：位置已知（刚锚到格心）⇒ 每个可见面板的**应有方位**可算；把它与
        **画面实测的机体方位**相减，差值就是 pose 航向的误差。取**中位**抗误检。

        ⚠️ 只用 |方位| ≤ `VIS_HEADFIX_MAX_OFFAXIS_DEG` 的面板：`_body_yaw_deg` 的
        `CAMERA_FOV_H_DEG=60` 是**伺服增益**不是真实 FOV（真实半视场 33.7° ⇒
        增益 ≈0.73），偏轴越远画面读数与几何方位差得越多（实测 ±28° 处差 ~10°、
        ±48° 处差 ~27°）⇒ 只用近轴面板才准。
        实测（无 pose 误差、7 面板同帧）：近轴面板给 −0.29/−0.31°，误差 <0.4°。
        """
        if frame is None or not obs:
            return None
        try:
            x, y, th = (float(v) for v in self.pose[:3])
        except Exception:
            return None
        hp = (self.state.current_head_pulse if head_pulse is None
              else head_pulse)
        fwd = np.array([np.sin(th), np.cos(th)])
        right = np.array([np.cos(th), -np.sin(th)])
        # ⚠️ 原点必须与 `target_relative` **逐字一致**（相机前移补偿）：两者口径不同
        # 会引入与位置相关的系统性偏差（实测漏掉它 ⇒ 修正量只剩应有的 ~2/3）。
        base = np.array([x, y]) - fwd * CAMERA_TO_BODY_FORWARD_CM
        deltas = []
        for o in obs:
            d = int(o.color_id)
            if d not in self.digit_cell:
                continue
            p = o.hull_centroid_px if o.clipped else o.center_px
            yaw_body = self._body_yaw_deg(float(p[0]), float(frame.shape[1]), hp)
            if abs(yaw_body) > VIS_HEADFIX_MAX_OFFAXIS_DEG:
                continue
            vec = np.asarray(grid_cell_center(self.digit_cell[d]), float) - base
            true_bearing = np.degrees(np.arctan2(float(vec @ right),
                                                 float(vec @ fwd)))
            # ⚠️ 先把**增益量**换算成真实角度再相减：`yaw_body` 的单位是
            # `CAMERA_FOV_H_DEG` 那条增益（实测 0.39×真实方位），直接相减会让
            # 修正量偏 2.5 倍（曾据此把 10° 的误差"修"成 15°）。
            yaw_true = -yaw_body / VIS_HEADFIX_GAIN
            deltas.append(yaw_true - true_bearing)
        if len(deltas) < 2:
            return None
        return float(np.median(deltas))

    def _fix_pose_heading(self, digit):
        """到达后用视觉重解航向 → 是否成功

        ⚠️ **当前不在任何路径上调用（未通过验证，保留作后续设计参考）**。
        为什么不能用（2026-09-25 实测，两条独立证据）：
          1. **标定口径**：`_body_yaw_deg` 的单位是 `CAMERA_FOV_H_DEG=60` 这条
             **伺服增益**，而画面真实横向标定是 ~154.8px/°（±33.7° 半视场 / 1296px）
             ⇒ 增益 ≈ **0.39**。实测（固定站位只改真航向、跟同一个面板）：
             真航向 −20/0/+20° 对应几何方位 +20.00/0.00/−20.00，而读数
             −7.36/+0.32/+7.99 ⇒ 比值 0.368~0.400。按 0.39 折算后修正仍然不准：
             注入 ±4/±8/±15° 的残余中位 **11.1°**、p90 23.1°。
          2. **几何上就没有近轴面板可用**：站在 33.3cm 格阵的一格上，可见邻格在
             **~45°（斜角）与 ~90°（同排两侧）**，落在 ±20° 内的面板**结构性稀缺**
             ⇒ 70 个测试位置里 **28 个"无解"**（凑不满 2 个可用面板）。
             而偏轴读数恰恰是最不准的（实测 ±28° 处差 ~10°、±48° 处差 ~27°）。
          3. **度量投影路线也走不通**：用 `project_ground_to_pixel` 做 1D 航向搜索，
             42 个位置里 **35 个无解**——因为近距邻格落在相机可见带之外，
             `project_ground_to_pixel` 直接返回 None（当初验证投影模型用的是**远**面板，
             近距这一档从没验过）。
        ⇒ 结论：**"到达后视觉修正航向"这条路在当前相机几何下不成立**。
        航向必须在别处解决：要么让到达时的姿态本身足够准（不依赖航向），
        要么把"找不到目标"的处理改成不依赖方位的确定性全扫（代价是帧数）。
        """
        frame = self._capture()
        if frame is None:
            return False
        try:
            obs = self.detector.detect_panels(frame, drop_border=False)
        except Exception:
            return False
        delta = self._visual_heading_delta_deg(frame, obs)
        if delta is None or abs(delta) > VIS_HEADFIX_MAX_DELTA_DEG:
            print(f"[航向] 面板{digit} 视觉重解航向不可用"
                  f"（{'观测不足' if delta is None else f'偏差 {delta:+.0f}° 过大，疑为误检'}）"
                  f"——保持原航向")
            return False
        self.pose[2] += np.radians(delta)
        print(f"[航向] 面板{digit} 视觉重解航向：修正 {delta:+.1f}°")
        return True

    def _lateral_off_cm(self, px, box, frame_w):
        """目标面板的**横向偏离（cm，绝对值）** —— 单块面板即可算，不需对应点集

        原理：横向偏离 = 深度 × tan(方位角)，而深度可由"面板物理半宽 / 它占的半视场角"
        给出（相似三角形）。两个量都取自**同一块面板**，所以不需要锚、也不需要
        多块面板的对应点 —— 这正是它比 `_map_anchor` 更适合"站在格心上"这种
        近距离情形的原因（那里画面里只有 2~4 块面板、对应点饥饿）。

        ⚠️ 必须用**低阶形式** `h·tan(方位) / tan(半视场)`。
        精确解 `a = h·cos(b)/sin(ps−b)`（b=面板中心方位、ps=观测点方位）
        在近距离会**奇异**（实测给出 685°、−2107° 这种值，因为 ps−b 趋近 0）。

        实测（门成立帧，真值打标）：
            真到达（≤半格）2.5 ~ 6.5cm（中位 4.7）
            假到达        5.3 ~ **159.5**cm（中位 29.9）
        单块面板都取不到时返回 None。
        """
        if frame_w <= 0 or box <= 1.0:
            return None
        try:
            yaw = abs(self._body_yaw_deg(px, frame_w))
            half = box / 2.0
            h_deg = abs(self._body_yaw_deg(px + half, frame_w)
                        - self._body_yaw_deg(px - half, frame_w)) / 2.0
        except Exception:
            return None
        t = math.tan(math.radians(max(h_deg, 0.5)))
        if t < 1e-6:
            return None
        return PANEL_HALF_CM * math.tan(math.radians(yaw)) / t

    def _on_target_cell(self, frame, digit):
        """★ 格的同一性核验（用户方案 ②-a）：实测位姿是否真的落在目标格上？

        返回 (verdict, reason)：
          "yes" = 锚解出的**实测位姿**距目标格心 ≤ `VIS_ARRIVE_ONCELL_TOL_CM` ⇒ 放行
          "no"  = 解出来了、但明显不在目标格 ⇒ **拒绝**（这就是"站在别格"假到达）
          "unknown" = 锚不可用（诚实弃权）⇒ 按 `VIS_ARRIVE_ONCELL_REQUIRE` 决定放不放

        为什么必须靠它（而不是继续加份额/形状阈值）：到达门那六个量都是**单帧
        整帧统计**，在"站在别的格子上、看到一块完整且居中的同色面板"这种视角下
        **全部正常**（实测有一帧 whole 0.082 / 宽高比合规 / 紫橙不对称全合规，
        而真值离目标 **100cm**）。**只有"这一帧的几何能不能被地图解释"才能分辨**
        ——这正是用户方案第 2 条第一项要求的核验。

        实现复用现成件：`_map_anchor`（v2 裁切角点版）解出实测位姿；
        它自带 RANSAC 共识门与诚实弃权，所以"解出来了"本身就是可信的证据。
        """
        if not VIS_ARRIVE_ONCELL_ENABLED:
            return "unknown", "核验开关关闭"
        # ★ 先在**单块面板**上判横向偏离（不需要对应点集，近距离也稳）。
        #   实测门成立帧：真到达 2.5~6.5cm ｜ 假到达 5.3~159.5cm（中位 29.9）
        #   ⇒ 超限即否决，**这一条不需要锚**，因此不受"对应点饥饿"影响。
        obs_here = None
        try:
            obs_here = self.detector.detect_panels(
                frame, colors=[self._target_color(digit)], drop_border=False)
        except Exception:
            obs_here = None
        if obs_here and VIS_ARRIVE_LATERAL_MAX_CM > 0.0:
            o = max(obs_here, key=lambda x: x.hull_area)
            p = o.hull_centroid_px if o.clipped else o.center_px
            box = float(o.bbox[2])
            if o.clipped:
                box = max(box, float(np.sqrt(max(o.hull_area, 1.0))))
            lat = self._lateral_off_cm(float(p[0]), box, float(frame.shape[1]))
            if lat is not None and lat > VIS_ARRIVE_LATERAL_MAX_CM:
                return "no", (f"横向偏离 {lat:.0f}cm > {VIS_ARRIVE_LATERAL_MAX_CM:.0f}cm"
                              f"——目标面板不在正下方，疑为邻格同色面板"
                              f"（单面板判据，无需锚）")
        # ★ 锚解算：**头部扫**以凑足对应点（身体不动 ⇒ 位姿不变）。
        #   动机（实测）：核验帧"对应点饥饿"—— 31 次里 20 次只有 2 对，解不出位姿。
        #   而对应点数**强烈依赖头部档**（站在格心、低头档，逐格实测）：
        #       cell0  中位2 左2 右**6** 宽左2 宽右8
        #       cell3  中位5 左3 右**9** 宽左2 宽右9
        #       cell4  中位**7** 左6 右6 宽左4 宽右4
        #       cell8  中位7 左**10** 右3 宽左8 宽右0
        #   ⇒ 中位解不出时依次试其它头部档；**只动头部**，所以位姿/几何不变。
        #   代价：只在"色块判据已成立"的帧上多拍 1~4 帧（每局约 +7 帧）。
        anc = None
        tried = []
        for hp in ((None,) + VIS_ARRIVE_ONCELL_HEAD_SWEEP
                   if VIS_ARRIVE_ONCELL_HEAD_SWEEP else (None,)):
            if hp is None:
                fr = frame                      # 复用已经拍好的那一帧
            else:
                if self._cell_expired():
                    break
                self.state.set_head(hp)
                fr = self._capture()
                if fr is None:
                    continue
            try:
                full = self.detector.detect_panels(fr, drop_border=False)
            except Exception:
                continue
            anc = self._map_anchor(full, fr, why=f"ONCELL{digit}")
            tried.append(("中位" if hp is None else str(hp), anc is not None))
            if anc is not None:
                break
        if VIS_ARRIVE_ONCELL_HEAD_SWEEP:
            self.state.set_head(HEAD_CENTER)     # 无论成败都复位居中
        if anc is None:
            return "unknown", ("锚不可用（共识不足/对应点不够；已试 %s）"
                               % "、".join("%s%s" % (n, "✓" if ok else "✗")
                                           for n, ok in tried))
        try:
            full = self.detector.detect_panels(frame, drop_border=False)
        except Exception:
            return "unknown", "全色检测异常"
        anc = self._map_anchor(full, frame, why=f"ONCELL{digit}")
        if anc is None:
            return "unknown", "锚不可用（共识不足/对应点不够）"
        cell = self.digit_cell.get(digit)
        if cell is None:
            return "unknown", "无该数字的格位"
        try:
            pos = np.asarray(anc["pose"], float)[:2]
            d = float(np.linalg.norm(pos - np.asarray(
                grid_cell_center(cell), float)))
        except Exception:
            return "unknown", "锚结果无法解读"
        if d <= VIS_ARRIVE_ONCELL_TOL_CM:
            return "yes", f"实测位姿距目标格心 {d:.1f}cm"
        return "no", (f"实测位姿距目标格心 {d:.1f}cm（>{VIS_ARRIVE_ONCELL_TOL_CM:.0f}cm）"
                      f"——目标面板不在脚下，疑为邻格同色面板")

    def _bearing_to_target_deg(self, digit):
        """用**地图 + 当前位姿**估"目标在机体哪一侧"（度，右正）——只用于选转向方向

        返回 None = 拿不到（无地图/无位姿）。
        ⚠️ 用途受严格限制（用户明确放弃死推做导航）：
          · **只决定往哪边转**，绝不产生"到位/到达"结论；
          · 转多少由视觉闭环决定（每步拍照复测）；
          · 它读的 `self.pose` 必须在**到达后经 `_fix_pose_heading` 视觉校正过**，
            否则航向误差会逐格累积（见该函数的说明）。
        """
        try:
            fwd, lat, bearing = self.target_relative(digit)
        except Exception:
            return None
        return float(bearing)

    def _unified_reacquire(self, digit, lost, turns, p):
        """目标丢失后的**重捕获** → 返回 (turns, deg_turned)；返回 <0 表示放弃本格

        纯视觉、逐步转、有上限：
          ① 丢的第 1 帧先只动**头部**扫四档（零身体位移、不烧转向预算、无翻车风险）；
          ② 之后每丢 `UNIFIED_LOSS_TOLERATE` 帧 ⇒ 朝地图方位转**一小步**（一次一个
             原语），每一步都拍照复测，转过冲由下一步反向吸收；
          ③ 累计转过 `VIS_REACQ_MAX_TURN_DEG` 或拍够 `VIS_REACQ_MAX_FRAMES` 仍不见
             ⇒ 放弃本格（交上层记未确认），**绝不无限转**（转向是最便宜的动作，
             没有上限就会"在原地转出场"）。
        """
        if lost == 1:
            for h in (HEAD_WIDE_LEFT, HEAD_LEFT, HEAD_RIGHT, HEAD_WIDE_RIGHT,
                      HEAD_CENTER):
                if self._cell_expired():
                    return -1, turns
                self.state.set_head(h)
                q = self._perceive(self._target_color(digit))
                if q is None:
                    return -1, turns
                if q["obs"] is not None:
                    print(f"[重捕获] 面板{digit} 头部档 {h} 扫到"
                          f"（画面列 {q['px']:.0f}px）→ 复测接手")
                    self.state.set_head(HEAD_CENTER)
                    return 0, 0.0
            self.state.set_head(HEAD_CENTER)
            print(f"[重捕获] 面板{digit} 头部四档未扫到 → 按地图方位逐步转过去")
            return turns, 0.0
        if lost % VIS_REACQ_STRIDE != 0:
            return turns, 0.0
        # ★ 转向方向**一次定死、中途不改**（见上：反复翻向会退化成原地摆动）
        if self._reacq_dir is None:
            bearing = self._bearing_to_target_deg(digit)
            if bearing is not None:
                self._reacq_dir = 1.0 if bearing > 0.0 else -1.0
            else:
                self._reacq_dir = (1.0 if float(getattr(
                    self, "_last_seen_side", 1.0)) >= 0.0 else -1.0)
        if self._reacq_deg >= VIS_REACQ_SWEEP_CAP_DEG \
                and not self._reacq_flipped:
            # 单向扫够额度还没看到 ⇒ 反向再扫（错方向的代价从"转满一圈"降到
            # "转一个上限"）。只允许反一次，避免左右来回摆（那正是第二轮踩过的坑）。
            self._reacq_dir = -(self._reacq_dir or 1.0)
            self._reacq_deg = 0.0
            self._reacq_flipped = True
            print(f"[重捕获] 面板{digit} 单向已扫 "
                  f"{VIS_REACQ_SWEEP_CAP_DEG:.0f}° 未见 → 反向再扫")
        want_left = self._reacq_dir > 0.0
        step = TURN_LEFT_SMALL_DEG if want_left else -TURN_RIGHT_SMALL_DEG
        act = "turn_left_small_step" if want_left else "turn_right_small_step"
        turns += 1
        print(f"[重捕获] 面板{digit} 连续 {lost} 帧未见 → {_action_cn(act)}"
              f"（第 {turns} 步，已转 {self._reacq_deg:.0f}°）")
        self._act(act, 1)
        return turns, step

    def _go_to_panel_v3(self, digit):
        if not VIS_NAV_ENABLED:
            return self._go_to_panel_map(digit)
        t_end = self._cell_budget_begin(digit)
        self._target_seen = False
        self._loc_count = 0
        self._current_digit = digit
        # 仿真接缝：把"当前目标数字"告知 sim，让地板形变可以**按格**注入
        # （见 sim/nine_grid_sim._update_deform 的 step_at_digit 说明）。
        # 真机 RobotState 没有这个方法 → getattr 兜底，对真机零影响。
        setter = getattr(self.state, "set_deform_digit", None)
        if setter is not None:
            setter(digit)
        for attempt in range(RETRY_LIMIT + 1):
            # 双重判据：软预算（旧语义）+ 硬熔断（新增，先到先算）
            if self._cell_expired():
                print(f"[面板{digit}] 本格终止：{self._cell_tripped}")
                return False
            if time.time() > t_end:
                print(f"[面板{digit}] 时间预算已耗尽")
                return False
            if UNIFIED_NAV_ENABLED:
                if self._drive_unified(digit, t_end) \
                        and self._confirm_switch(digit):
                    self._reanchor_pose(digit)
                    if USE_MAP_CORRECTION:
                        self._map_correction()
                    return True
            elif self._seek_align_approach(digit, t_end):
                if self._arrive_visual(digit, t_end) \
                        and self._confirm_switch(digit):
                    self._reanchor_pose(digit)
                    if USE_MAP_CORRECTION:
                        self._map_correction()
                    return True
            if self._cell_expired():
                print(f"[面板{digit}] 本格终止：{self._cell_tripped}")
                return False
            print(f"[面板{digit}] 第 {attempt + 1} 轮未到位")
            if attempt < RETRY_LIMIT:
                self._act("back_one_step", 1)
        return False

    def _drive_unified(self, digit, t_end):
        """★ 三档分区 ＋ 统一决策：**一个循环一路走到目标**（`UNIFIED_NAV_ENABLED`）

        与三段式（对准→接近→到达）的区别 —— 这正是用户指出的那个坏组合：

        | | 现三段式 | 本法（统一决策） |
        |---|---|---|
        | 决策依据 | 三段**各有一套**：ALIGN 用 `|yaw|≤12°`、APPROACH 用框宽 ≥920px、ARRIVE 用色占比回落 | **每帧同一套** `_zone_of(yaw, near)` → 直行/横移/旋转 |
        | 交棒 | 有交棒点 ⇒ **交棒 yaw 残余最大 12°（真实 16.3°）**，只能留给低头段厘米级横移兜 | **没有交棒点**，也就没有这个漏；近距 yaw 残差由蓝档当场吃掉 |
        | 取景档 | ALIGN/APPROACH 用导航档，ARRIVE 切低头档 | 低头档只是**取景**切换（`near` 过门时切一次），**不是控制律切换** |
        | 到达判据 | 色占比回落 / 前压兜底 / 死推 | **沿用同一套**（色占比回落 / 前压兜底），另加几何锚（若开） |

        为什么近距必须靠蓝档而不是旋转（评审 Q3/§6.7）：小转一步实测
        8.625°/5.200° ⇒ 画幅中心 295/177px；295px 在 Z=64.5cm 处 = **9.8cm**
        > 微动开关半宽 **5.5cm** ⇒ 旋转永远做不进开关区，精度只能靠
        **厘米级横移**（2.2/2.5cm 一步）。三段式把这个事实只写在 ARRIVE 段里；
        统一决策把它做成整个行进过程的通则。

        算力：真机实测每帧 0.712s（全色检测 0.089s + 锚 0.040s），
        单格 70s 可拍 ~98 帧，而实际单格最多 ~40 张 ⇒ 不是瓶颈（见方案 §8.8）。
        """
        self.phase = f"DRIVE{digit}"
        color = self._target_color(digit)
        cell_xy = (np.asarray(grid_cell_center(self.digit_cell[digit]), float)
                   if digit in self.digit_cell else None)
        peak = 0.0
        press_cm = 0.0
        lat_fixes = 0
        prev_box = None
        stall = 0
        self._lost = 0          # 连续未检出次数（见"一次拍照两个观测量"那段注释）
        turns = 0               # 连续"看不到就转身"次数（见 VIS_UNIFIED_TURN_MAX）
        prev_yaw, prev_n = None, 0   # 小转每步实际角的 EMA（见旋转档那段）
        pitch = PITCH_DOWN      # ★ 全程低头档（见循环内的说明）
        self.state.set_pitch(pitch)
        anchor_tick = 0
        try:
            for _ in range(UNIFIED_MAX_ITERS):
                if time.time() > t_end or self._cell_expired():
                    return False
                # ---- 取景档：**全程低头档 1040**（用户明确要求，也是实测最优）----
                # 可见地面带实测：1040 → **3.8~85.7cm**；1200 → 只有 18.5cm 以外。
                # ⚠️ 第一版这里是 `PITCH_DOWN if press_cm >= 12cm else PITCH_NAV`，
                # 等于把"接近"又拆成两段——而且前 12cm 用 1200 时，面板已经进到
                # 18.5cm 以内 ⇒ **必然检不出**（那才是"终端段检测不到"的真因，
                # 不是面板钻到机器人下方）。统一决策就该全程同一个取景档。
                # 注：1040 的上限是 85.7cm，目标更远时本轮会走"未检出 → 重搜"
                # （_search_target 会用 1200 + 低头补帧 + 盲走把距离拉近），不需要
                # 在行进循环里再切档。
                # ---- 一次拍照，两个观测量（★ 第二版的关键修正）----
                # 第一版每帧只靠 `_see_target`（要求目标是一块完整的、带数字证据的
                # 面板检测）⇒ 终端段面板钻到机器人下方时必然"丢失"⇒ 重搜 ⇒ 实测
                # 4 局拍到 2452 张（基线 1418）、到达 13/28。三段式的 ARRIVE 之所以
                # 稳，是因为它改用**整帧色占比**——不需要面板是个完整检测。
                # ⇒ 统一决策也必须同时持有两种观测量：
                #     色占比      → 到达证据（终段唯一可靠的量）
                #     面板检测    → 分区决策需要的 (yaw, box)
                self._count_frame()
                self._cell_frames += 1
                frame = self.state.capture_frame()
                if frame is None:
                    return False
                sh = self._region_shares(frame, color)
                ratio = sh[0] if sh is not None else 0.0
                obs_l = self.detector.detect_panels(
                    frame, colors=[color], arbitrate=False, drop_border=False)
                o = (max(obs_l, key=lambda x: x.hull_area) if obs_l else None)
                # ★ 居中头位没看到 ⇒ **先头部扫一遍**再说（目标常常只是偏出视野）：
                #   扫到就**用那一帧**继续（判档时由 `_zone_px_of` 把头部角折算回去）。
                #   实测（面板6/种子11）：少了这一步，目标偏 54~111° 时循环只会
                #   "看不到 → 前压 → 重搜 → 又看不到"，17 轮空转到单格拍照熔断；
                #   而老办法的 `_align_visual` 正是靠 `_see_target_any` 偏头找到它、
                #   再按 yaw 把**身子**转过去的。
                if o is None and self._lost == 0:
                    # 「找回来」这一步用**导航档 1200 + 头部五档扫**，找到就把身子转正
                    # （按 yaw），然后马上切回低头档行进。为什么找的时候不能用 1040：
                    # 低头档可见带只有 3.8~85.7cm，目标又远又偏时（实测面板6：
                    # 75cm、偏 54~111°）根本不在画幅里——1040 扫 127 帧一次没看到，
                    # 1200（18.5~165cm）同一位置一掃就看到。**只是"找"用 1200**，
                    # 行进/前压仍然全程 1040（用户明确要求）。
                    # 只在这一串丢失的第 1 帧扫，避免每帧都付 5 张照片的代价。
                    self.state.set_pitch(PITCH_NAV)
                    seen_any = self._see_target_any(digit, PITCH_NAV)
                    self.state.set_pitch(pitch)
                    if seen_any is not None:
                        o, frame = seen_any[0], seen_any[1]
                        sh = self._region_shares(frame, color)
                        ratio = sh[0] if sh is not None else 0.0
                        print(f"[行进] 面板{digit} 在导航档侧向扫视中找到"
                              f"（方位 {seen_any[2]:+.0f}°，框宽 {seen_any[3]:.0f}px）"
                              " → 按该方位转身正对")
                if ratio > peak:
                    peak = ratio
                # ---- 到达判据：**只看当前这一帧**（用户 2026-09-24 方案）----
                #   紫区份额 ≥ 门（面板已经在我脚下，且颜色主要就在脚下）
                #   橙区份额 ≤ 门（远处没有同一块颜色 ⇒ 脚下这块就是目标本体）
                #   左右溢出不不对称 ≤ 门（站在格子中央，压感才踩得到）
                # 全部是状态量、**不含任何历史**：原地转身/偏头/遮挡都不会让它成立
                # （旧判据"占比跌破峰值"会：实测面板6/种子11 一厘米没动就判到达）。
                if VIS_ARRIVE_REGION_ENABLED and sh is not None:
                    _w, pur, org, asym = sh
                    if pur >= VIS_ARRIVE_PURPLE_MIN \
                            and org <= VIS_ARRIVE_ORANGE_MAX \
                            and abs(asym) <= VIS_ARRIVE_ASYM_MAX:
                        self._arrive_evidence = (
                            f"脚下色块判据：紫区占比 {pur:.3f}（≥"
                            f"{VIS_ARRIVE_PURPLE_MIN}），橙区占比 {org:.3f}（≤"
                            f"{VIS_ARRIVE_ORANGE_MAX}），左右不对称 {asym:+.3f}"
                            f"（绝对值≤{VIS_ARRIVE_ASYM_MAX}）；"
                            f"已前压 {press_cm:.0f}cm，横向修正 {lat_fixes} 次")
                        print(f"[行进] 面板{digit} 区域判据成立（紫区 {pur:.3f}、"
                              f"橙区 {org:.3f}、左右不对称 {asym:+.3f}）→ 判定到达")
                        return True
                # 旧的"峰值回落"判据（VIS_ARRIVE_REGION_ENABLED=False 时才是主判据）
                tail_accept = (
                    not VIS_ARRIVE_REGION_ENABLED
                    and VIS_ARRIVE_TAIL_ACCEPT_FRAC > 0.0
                    and press_cm >= VIS_ARRIVE_PRESS_MAX_CM
                    * VIS_ARRIVE_TAIL_PRESS_FRAC
                    and ratio < VIS_ARRIVE_TAIL_ACCEPT_FRAC * peak)
                if not VIS_ARRIVE_REGION_ENABLED and peak >= VIS_COLOR_SEEN_MIN \
                        and (ratio < VIS_COLOR_DROP_FRAC * peak or tail_accept):
                    self._arrive_evidence = (
                        f"颜色占比回落判据：峰值 {peak:.4f} 降至 {ratio:.4f}"
                        f"（{'前压封顶后兜底判定' if tail_accept else '回落判据'}）；"
                        f"已前压 {press_cm:.0f}cm，横向修正 {lat_fixes} 次，"
                        f"当前{'能看到' if o is not None else '看不到'}目标面板")
                    print(f"[行进] 面板{digit} 判定已越过目标格"
                          f"（颜色占比 {peak:.4f} → {ratio:.4f}）")
                    return True
                # ---- 几何锚（若开）：独立于色占比的第二条通道 ----
                if VIS_ARRIVE_ANCHOR_ENABLED and cell_xy is not None:
                    anchor_tick += 1
                    if anchor_tick % max(1, VIS_ARRIVE_ANCHOR_EVERY) == 0:
                        _ao = self.detector.detect_panels(
                            frame, arbitrate=False, drop_border=False)
                        _anc = self._map_anchor(_ao, frame, why=f"DRIVE{digit}")
                        if _anc is not None:
                            _d = float(np.linalg.norm(
                                np.asarray(_anc["pose"], float)[:2] - cell_xy))
                            self._anchor_arrive_d.append(_d)
                            if _d <= VIS_ARRIVE_ANCHOR_TOL_CM:
                                self._anchor_arrive_hits += 1
                                self._arrive_evidence = (
                                    f"几何位置判据（实测位置距格心 "
                                    f"{_d:.1f}cm）；已前压 {press_cm:.0f}cm")
                                print(f"[行进] 面板{digit} 几何判据成立："
                                      f"实测位置距格心 {_d:.1f}cm")
                                return True
                # ---- 看不到目标：**先转身面向它**（提示来自地图/死推），
                #      方向已差不多时才小步前压，连续丢失才认输去重搜 ----
                # ★ 2026-09-24 实测（面板6，种子11）：旧写法"看不到就前压"在
                #   **目标位于身后 154°** 时等于朝反方向走（75.5→84.6cm），随后
                #   17 轮"压4步+重搜"空转到单格拍照上限（141>140）收手；
                #   老办法同一格 40 帧完成——差别就是老办法有"把身子转过去对准"
                #   这一步（`_align_visual` 用 `_see_target_any` 找到后按 yaw 转身）。
                if o is None:
                    self._lost += 1
                    hint = self._search_hint(digit)
                    if abs(hint) > VIS_UNIFIED_TURN_MIN_DEG \
                            and turns < VIS_UNIFIED_TURN_MAX:
                        # 目标不在（居中头位的）视野里 ⇒ 按提示大小转 1~5 个大步。
                        # 提示是机体系真实方位角（锚优先、死推兜底），转身后由
                        # 下一帧复测收敛——与 `_search_target` 的转向同一套动作。
                        k = int(np.clip(round(abs(hint) / TURN_RIGHT_DEG), 1, 5))
                        act = "turn_right" if hint > 0 else "turn_left"
                        turns += 1
                        self._lost = 0        # 转身是有效动作，不算"丢失"
                        print(f"[行进] 面板{digit} 不在视野内（方位提示 "
                              f"{hint:+.0f}°）→ {act} {k} 次，转身正对"
                              f"（第 {turns}/{VIS_UNIFIED_TURN_MAX} 次）")
                        self._act(act, k)
                        continue
                    if self._lost <= UNIFIED_LOSS_TOLERATE:
                        if press_cm + FORWARD_ONE_STEP_CM \
                                <= VIS_ARRIVE_PRESS_MAX_CM:
                            print(f"[行进] 面板{digit} 未检出（第 {self._lost} 次，"
                                  f"方位提示 {hint:+.0f}°）→ 小步前压")
                            self._act("go_forward_one_step", 1)
                            press_cm += FORWARD_ONE_STEP_CM
                        continue
                    print(f"[行进] 面板{digit} 连续 {self._lost} 次未检出 → 重新搜索")
                    if self._search_target(digit, t_end) is None:
                        print(f"[行进] 面板{digit} 重新搜索未找到目标")
                        return False
                    self._lost = 0
                    turns = 0
                    continue
                self._lost = 0
                turns = 0
                # ---- 分区决策 ----
                # px/py = 目标在**机体方向**上的画面位置（头部角已折算，见 _zone_px_of）
                head_deg = ((self.state.current_head_pulse - HEAD_CENTER)
                            * SERVO_DEG_PER_US)
                px, py, w, h = self._zone_px_of(o, frame, head_deg)
                cx = float((o.hull_centroid_px if o.clipped
                            else o.center_px)[0])
                yaw = -(cx - w / 2.0) / w * CAMERA_FOV_H_DEG + head_deg
                box = float(o.bbox[2])
                if o.clipped:
                    box = max(box, float(np.sqrt(max(o.hull_area, 1.0))))
                near = self._near_of(box, frame)
                zone, off_cm = self._zone_of_h(
                    yaw, self._off_cm_of(o, frame, box), near,
                    px=px, py=py, w=w, h=h)
                # ---- 分区动作（同一套判据走完全程）----
                if zone == "rot":
                    # ⚠️ 必须**在线更新每步实际转角**（EMA）——这段逻辑原本只在
                    # `_align_visual` 里，第一版统一循环漏了它 ⇒ `_small_turn_deg`
                    # 永远是初值 2.0°，而真实小转一步是 8.625°/5.200° ⇒
                    # `n = floor(|yaw|/2.0)` 一次转 6 步 ≈ 52° ⇒ 转过头 → 丢目标
                    # → 重搜。实测表现就是 forward 调用 675 次（基线 337）。
                    if prev_yaw is not None and prev_n:
                        if abs(yaw) < abs(prev_yaw):
                            per = (abs(prev_yaw) - abs(yaw)) / prev_n
                        else:
                            per = (abs(prev_yaw) + abs(yaw)) / prev_n
                        per = float(np.clip(per, 0.3, 10.0))
                        alpha = (TURN_EMA_ALPHA_FAST
                                 if self._turn_updates < TURN_EMA_FAST_UPDATES
                                 else TURN_EMA_ALPHA)
                        self._turn_updates += 1
                        self._small_turn_deg = ((1 - alpha) * self._small_turn_deg
                                                + alpha * per)
                    step = max(self._small_turn_deg, VIS_SMALL_TURN_MIN_STEP_DEG)
                    n = int(np.clip(int(np.floor(abs(yaw) / step)),
                                    1, SMALL_TURN_MAX_STEPS))
                    act = ("turn_left_small_step" if yaw * self._align_sign > 0
                           else "turn_right_small_step")
                    self._act(act, n)
                    print(f"[行进] 旋转档 偏角 {yaw:+.1f}° → {_action_cn(act, n)}"
                          f"（单步估计 {self._small_turn_deg:.1f}°，接近度 {near:.2f}）")
                    prev_yaw, prev_n = yaw, n
                    prev_box = None
                    continue
                if zone == "lat":
                    lat = "left_move" if yaw > 0 else "right_move"
                    self._act(lat, 1)
                    lat_fixes += 1
                    print(f"[行进] 平移档 {_action_cn(lat)}（偏角 {yaw:+.1f}°，"
                          f"横向偏差 {off_cm:+.1f}cm，接近度 {near:.2f}）")
                    prev_box = None
                    continue
                # ---- 直行档：步数按 near 分档（远处赶路、近处精走）----
                if box < 0.6 * VIS_ARRIVE_BOX_PX:
                    n = VIS_BATCH_MAX_STEPS
                elif box < 0.85 * VIS_ARRIVE_BOX_PX:
                    n = 3
                else:
                    n = 1
                if press_cm + n * FORWARD_ONE_STEP_CM \
                        > VIS_ARRIVE_PRESS_MAX_CM:
                    print(f"[行进] 前压已达上限 {press_cm:.0f}cm"
                          f"（上限 {VIS_ARRIVE_PRESS_MAX_CM:.0f}cm）"
                          " → 交回上层复核")
                    return False
                if prev_box is not None and abs(box - prev_box) < VIS_STALL_BOX_PX:
                    stall += 1
                    if stall >= 2:
                        print("[行进] 前进无效（框宽未增大）：后退一步后重新识别")
                        self._act("back_one_step", 1)
                        stall, prev_box = 0, None
                        continue
                else:
                    stall = 0
                prev_box = box
                print(f"[行进] 直行档 框宽 {box:.0f}px（到位线 {VIS_ARRIVE_BOX_PX:.0f}px）"
                      f" → 前进 {n} 步（接近度 {near:.2f}）")
                self._act("go_forward_one_step", n)
                press_cm += n * FORWARD_ONE_STEP_CM
            print(f"[行进] 面板{digit} 循环次数已达上限")
            return False
        finally:
            if pitch != PITCH_NAV:
                self.state.set_pitch(PITCH_NAV)

    def _seek_align_approach(self, digit, t_end):
        """搜索 → 对准 → 接近（框宽达标即返回 True）

        对准期目标短暂丢失（转过冲/近距窄视野）不算失败：重搜一次再试。
        任一子环节熔断 → 直接返回 False（不在这里再重试，交 go_to_panel 收手）。
        """
        if self._search_target(digit, t_end) is None:
            print(f"[搜索] 未找到面板{digit}（可能被遮挡或光照不足）")
            return False
        self._target_seen = True
        for _try in range(2):
            if self._cell_expired():
                return False
            if self._align_visual(digit, t_end) is not None:
                return self._approach_visual(digit, t_end)
            print(f"[对准] 目标{digit}丢失 → 重新搜索一次")
            if self._search_target(digit, t_end) is None:
                break
        # 目标始终不入视野，但死推说到位了：交给低头颜色判据裁决（抗形变、
        # 不需要看见目标数字本身——色块压过与否是机器人与色块的相对关系）。
        if self._cell_expired():
            return False
        if digit in self.digit_cell:
            fwd, lat, _b = self.target_relative(digit)
            if abs(fwd) <= VIS_ARRIVE_FALLBACK_CM and abs(lat) <= 20.0:
                print(f"[对准] 目标{digit}不可见，但按动作推算已到位"
                      f"（纵向 {fwd:+.1f}cm、横向 {lat:+.1f}cm）→ 交由低头档颜色判据裁决")
                self._target_seen = True
                return True
        print(f"[对准] 目标{digit}反复丢失，放弃本轮对准")
        return False

    def _count_frame(self):
        """按当前阶段累计拍照数（诊断；见 run_level 的汇总打印）"""
        self.phase_frames[self.phase] = self.phase_frames.get(self.phase, 0) + 1

    def _target_color(self, digit):
        """数字(1..7) → 检测器颜色名"""
        return ID_TO_COLOR[digit]

    def _see_target(self, digit, pitch=PITCH_NAV, head=None):
        """拍一帧找目标色块 → (obs, frame, yaw_deg, box_px)；没看到返回 None

        yaw 是**机体系**偏角：像素偏移换算（仅作伺服增益，FOV 取名义值不影响
        收敛点）**再加上当前头部角**（左正）——否则在偏头档找到目标后会转错
        角度（实测：宽扫档找到目标、按像素偏移转，目标立刻丢失）。
        box_px 优先取 bbox 宽；被画幅裁切时用 sqrt(hull_area)（等效边长）兜底。
        """
        self._count_frame()
        if head is not None:
            self.state.set_head(head)
        frame = self._capture()
        if frame is None:
            return None
        if MAP_ANCHOR_ENABLED:
            # 全色检测一次：既取目标色，也喂给 MAP-ANCHOR（同一帧，不额外拍照）。
            # 默认关闭时走下面原有的"只检测目标色"路径，行为逐位不变。
            allobs = self.detector.detect_panels(frame, arbitrate=False,
                                                 drop_border=False)
            self._anchor_last = self._map_anchor(
                allobs, frame, why=f"panel{digit}@{self.phase}")
            obs = [o for o in allobs
                   if o.color == self._target_color(digit)]
        else:
            obs = self.detector.detect_panels(frame,
                                              colors=[self._target_color(digit)],
                                              arbitrate=False, drop_border=False)
        if not obs:
            return None
        # 同色择优：优先取"带数字证据"的观测，其次才按面积——现场实测木框被
        # 橙色掩膜命中且比真橙面板还大（93k vs 62k px），纯按面积择大会追着
        # 木框跑（见 nine_grid_detector.DIGIT_EVIDENCE_*）。
        cand = [o for o in obs if o.has_digit_evidence()] or list(obs)
        o = max(cand, key=lambda x: x.hull_area)
        w = float(frame.shape[1])
        center_x = float((o.hull_centroid_px if o.clipped
                          else o.center_px)[0])
        center_y = float((o.hull_centroid_px if o.clipped
                          else o.center_px)[1])
        head_deg = ((self.state.current_head_pulse - HEAD_CENTER)
                    * SERVO_DEG_PER_US)
        # yaw = 横向像素偏移换算的**伺服误差**（名义度，不是真实角度；
        # 真实相机方位角 ≈ 本值 / 0.734，详见 CAMERA_FOV_H_DEG 注释）。
        # 头部档角是真实伺服角，加回来把 yaw 变到"机体系"。
        yaw = -(center_x - w / 2.0) / w * CAMERA_FOV_H_DEG + head_deg
        box = float(o.bbox[2])
        if o.clipped:
            box = max(box, float(np.sqrt(max(o.hull_area, 1.0))))
        return o, frame, float(yaw), box

    def _see_target_any(self, digit, pitch=PITCH_NAV):
        """先在当前头部档找；找不到再头部五档扫（零身体位移）。同 _see_target"""
        seen = self._see_target(digit, pitch)
        if seen is not None:
            return seen
        for head in (HEAD_LEFT, HEAD_RIGHT, HEAD_WIDE_LEFT, HEAD_WIDE_RIGHT):
            seen = self._see_target(digit, pitch, head)
            if seen is not None:
                return seen
        self.state.set_head(HEAD_CENTER)
        return None

    def _align_ladder_step(self, why):
        """打转升级阶梯（打转判据的统一出口）：换策略在先，熔断在最后

        1) 弃用小转、改用大转（小转被地面吞掉是已知现场情形）；
        2) 放弃本次对准（返回 None，让调用方走"死推到位→低头到达"或重搜）；
        3) 仍打转 → 熔断本格。
        返回值：True = 调用方可以继续（已换策略）；False = 调用方应 return None。

        为什么不直接熔断（2026-09-13 仿真复核）：标称场景里一次摆动就熔断会白丢
        整格；打转真正要的结果是"别再原地转"，不是"这格不要了"。而"别再原地转"
        另有 VIS_TURN_BUDGET_DEG(360°) 硬预算兜底，所以这条阶梯不会无限升。
        """
        self._align_stall = 0
        self._align_worsen = 0
        self._align_flips = 0
        self._align_ladder += 1
        if self._align_ladder == 1:
            self._small_turn_usable = False
            print(f"[对准] 原地打转（{why}）→ 措施一：停用小转角，改用大角度转向")
            return True
        if self._align_ladder == 2:
            print(f"[对准] 原地打转（{why}）→ 措施二：放弃本次对准"
                  "（交由按动作推算／低头档路径，不再原地转向）")
            return False
        self._trip_cell(f"打转判据连续触发 3 次（{why}，本格已转 "
                        f"{self._cell_turn_cmd_deg:.0f}°）——判定无法收敛")
        return False

    def _search_target(self, digit, t_end):
        """搜索目标：当前朝向头部五档 → 按死推提示转一步 → 后段前进探测

        地图只用来定"往哪转"（±30° 容差足够，死推位姿每格到达后由
        _reanchor_pose 重置，因此不会漂到不可用）。返回 (obs, frame) 或 None。
        """
        self.phase = f"SEARCH{digit}"
        frames = 0
        blind_cm = 0.0
        for rnd in range(VIS_SEARCH_MAX_ROUNDS):
            if time.time() > t_end or frames >= VIS_SEARCH_MAX_FRAMES \
                    or self._cell_expired():
                break
            for head in (HEAD_CENTER, HEAD_LEFT, HEAD_RIGHT,
                         HEAD_WIDE_LEFT, HEAD_WIDE_RIGHT):
                if time.time() > t_end or frames >= VIS_SEARCH_MAX_FRAMES \
                        or self._cell_expired():
                    break
                seen = self._see_target(digit, PITCH_NAV, head)
                frames += 1
                if seen is not None:
                    self.state.set_head(HEAD_CENTER)
                    print(f"[搜索] 面板{digit} 已找到（第 {rnd + 1} 轮，"
                          f"用掉 {frames} 帧）")
                    return seen[0], seen[1]
            self.state.set_head(HEAD_CENTER)
            # 补一帧**低头档**（2026-09-13 形变场景）：导航档可见地面带在形变后
            # 会整体移走（h=56cm 时 45.5°→18.5~165cm；形变到 60° 时约 11~96cm），
            # 目标可能正好落在导航档之外、低头档之内（**3.8~85.7cm**，2026-09-24
            # 按现行常数复算；旧注释的 0.16~1.47m 是按 h=39cm 推的，已作废）。
            # 只在导航档整轮没找到时补 1 帧（真机 ~0.7s + 两次俯仰伺服）：
            # 比"整轮五档低头扫"便宜 5 倍。
            self.state.set_pitch(PITCH_DOWN)
            seen_down = self._see_target(digit, PITCH_DOWN, HEAD_CENTER)
            frames += 1
            self.state.set_pitch(PITCH_NAV)
            if seen_down is not None:
                print(f"[搜索] 面板{digit} 在低头档找到（第 {rnd + 1} 轮，"
                      f"用掉 {frames} 帧）")
                return seen_down[0], seen_down[1]
            # 按死推提示转向（提示无效时固定左转）：**按提示大小转足**，
            # 一次转 1~5 个大转步（22~129°）——动作不花帧，只有头部扫花帧，
            # 这样"目标在身后 180°"也能两轮内覆盖到。
            hint = self._search_hint(digit)
            if abs(hint) < 5.0:
                hint = -TURN_LEFT_DEG      # 负 = 目标在左侧 → 左转
            k = int(np.clip(round(abs(hint) / TURN_RIGHT_DEG), 1, 5))
            self._act("turn_right" if hint > 0 else "turn_left", k)
            frames += 1
            # 盲走近目标（死推指引，动作不花帧）：地板形变会把可见地面带整体
            # 推走（±15° → 可见带在 0~50cm 与 19~184cm 之间摆动），此时目标
            # 可能压根不在任何俯仰档的视野里，只能先走近再由视觉接管。
            if digit in self.digit_cell:
                fwd = self.target_relative(digit)[0]
                if fwd > VIS_SEARCH_BLIND_CM:
                    if blind_cm >= VIS_SEARCH_BLIND_TOTAL_CM:
                        print(f"[搜索] 面板{digit} 按动作推算已盲走累计 {blind_cm:.0f}cm 仍未入"
                              f"视野（上限 {VIS_SEARCH_BLIND_TOTAL_CM:.0f}cm）"
                              "→ 终止（不再继续盲走，位姿提示已不可信）")
                        break
                    n = int(np.clip(round((fwd - VIS_SEARCH_BLIND_CM) / 4.0
                                          / FORWARD_ONE_STEP_CM),
                                    1, VIS_SEARCH_BLIND_MAX_STEPS))
                    print(f"[搜索] 面板{digit} 未进入视野（按动作推算纵向 {fwd:.0f}cm）"
                          f"→ 盲走 {n} 步")
                    self._act("go_forward_one_step", n)
                    blind_cm += n * FORWARD_ONE_STEP_CM
        print(f"[搜索] 面板{digit} 搜索次数用尽（共 {frames} 帧）")
        return None

    def _off_cm_of(self, obs, frame, box):
        """跨越偏差（cm）= 目标横向像素偏移 / 框宽 × PANEL_WIDTH_CM

        投影不变量：等于"横向物理偏移 ÷ 面板物理宽"，与相机高度/俯仰/地板形变
        全无关（同 _arrive_visual 的 dx_cm）。
        ⚠️ 只用于**日志/遥测**，不参与分区判据：面板被画幅裁切时框宽只剩可见窄条
        ⇒ 它会系统性高估（现场 74% 观测是裁切的）。详见 VIS_ZONE_MOVE_DEG 说明。
        """
        w = float(frame.shape[1])
        center_x = float((obs.hull_centroid_px if obs.clipped
                          else obs.center_px)[0])
        if box <= 1.0:
            return 0.0
        return (center_x - w / 2.0) / box * PANEL_WIDTH_CM

    def _near_of(self, box, frame):
        """目标"够近"的尺度不变量 = 框宽 / 画幅高（见 VIS_ZONE_MOVE_DEG 说明）

        框宽是投影不变量（∝1/深度），除以画幅高后无量纲 ⇒ 换分辨率、换俯仰档
        都不用改阈值，也不受地板形变影响。远处值小 → 只许旋转；近处值大 → 允许
        横移。这正是用户图里蓝/橙之间那条**水平分界线**的物理含义。
        """
        H = float(frame.shape[0])
        return float(box) / H if H > 0 else 0.0

    # ---------------- MAP-ANCHOR（见文件头常量块的说明） ----------------

    def _clip_sides_of(self, obs, frame):
        """由 bbox 与画幅判定"贴了哪几条画幅边"（原生 px，与 detector 同口径）"""
        H = float(frame.shape[0])
        W = float(frame.shape[1])
        m = MAP_ANCHOR_CORNER_MARGIN_PX
        x, y, w, h = (float(v) for v in obs.bbox)
        sides = []
        if x <= m:
            sides.append("L")
        if y <= m:
            sides.append("T")
        if x + w >= W - m:
            sides.append("R")
        if y + h >= H - m:
            sides.append("B")
        return sides, W, H

    def _anchor_corr(self, obs, frame, swap_corners=False):
        """本帧观测 → (对应点, 观测) 列表（v2：未裁切用中心，裁切用**真实角点对**）

        v1 只收未裁切观测，原因是裁切观测的 `center_px`（对角线交点）量的是可见
        残片、偏差 1.3~8.4cm。但那条限制让可用率极低（整关实测 ≥4 对应的帧只占
        **14.7%**）。v2 的观察是：**被裁切的面板仍然贡献它未被裁掉的那两个真实
        角点**——那些是精确对应点，不是残片质心。

        判据（本轮 140 面板-帧普查：裁切面板中 **78%** 满足）：
          - 只贴**一条**画幅边（贴两条 = 角点被裁，无法确定是哪两个角 → 弃权）
          - `hull_poly` 中距四条边都 ≥ MAP_ANCHOR_CORNER_MARGIN_PX 的顶点 ≥2 个
        场地坐标由裁边决定（`h = PANEL_HALF_CM`，色块半边长）：

          | 裁边 | 可见的是 | 场地坐标 |
          |---|---|---|
          | B（下沿） | 远角对 | (cx±h, cy+h) |
          | T        | 近角对 | (cx±h, cy−h) |
          | L        | 右角对 | (cx+h, cy±h) |
          | R        | 左角对 | (cx−h, cy±h) |

        配对方式：图像点与场地点**各自按 x 排序**后一一配对；整帧共识不足时调用方
        用 `swap_corners=True` 再跑一次（交换所有角点对的配对顺序），由 RANSAC
        的共识来裁决——不做任何"猜哪一对"的启发式。

        实测（整关 4 种子 477 帧）：≥4 对应的帧 14.7% → **46.1%**、
        ≥5 对应 5.5% → **34.0%**（3.1×）。
        """
        corr, keep = [], []
        for o in obs:
            if o.digit not in self.digit_cell:
                continue
            g = np.asarray(grid_cell_center(self.digit_cell[o.digit]), float)
            if not o.clipped:
                corr.append((g, np.asarray(o.center_px, float)))
                keep.append(o)
                continue
            # ---- 裁切：尝试用两个真实角点 ----
            sides, W, H = self._clip_sides_of(o, frame)
            if len(sides) != 1:
                continue
            m = MAP_ANCHOR_CORNER_MARGIN_PX
            inner = [(float(p[0]), float(p[1])) for p in (o.hull_poly or ())
                     if m < float(p[0]) < W - m and m < float(p[1]) < H - m]
            if len(inner) < 2:
                continue
            # 取该裁边"对面"那一对角的两个图像点：按远离被裁边的方向排序取前 2
            # （下沿被裁 → 取图像里最靠上的两个内顶点；左沿被裁 → 取最靠右的两个）
            if sides[0] == "B":
                inner.sort(key=lambda p: p[1])
            elif sides[0] == "T":
                inner.sort(key=lambda p: -p[1])
            elif sides[0] == "L":
                inner.sort(key=lambda p: -p[0])
            else:                                   # "R"
                inner.sort(key=lambda p: p[0])
            pair = inner[:2]
            pair.sort(key=lambda p: p[0])           # 图像侧按 x 排序
            h = PANEL_HALF_CM
            if sides[0] == "B":
                gp = [(g[0] - h, g[1] + h), (g[0] + h, g[1] + h)]
            elif sides[0] == "T":
                gp = [(g[0] - h, g[1] - h), (g[0] + h, g[1] - h)]
            elif sides[0] == "L":
                gp = [(g[0] + h, g[1] - h), (g[0] + h, g[1] + h)]
            else:                                   # "R"
                gp = [(g[0] - h, g[1] - h), (g[0] - h, g[1] + h)]
            gp.sort(key=lambda p: p[0])             # 场地侧同样按 x 排序
            if swap_corners:
                gp = gp[::-1]
            for gpt, ppt in zip(gp, pair):
                corr.append((np.asarray(gpt, float), np.asarray(ppt, float)))
                keep.append(o)
        return corr, keep

    def _map_anchor(self, obs, frame, why=""):
        """地图锚定的逐帧自标定 → AnchorResult 或 None（诚实弃权）

        返回 dict：hg / pose(场地系 x,y,θ) / cam_height_cm / inliers(下标集) /
                   resid_px(逐点残差) / n_pts / n_inliers / digits

        角点配对有**两种假设**（正序/逆序），二者只有一个能与其余观测自洽：
        先按正序求共识，共识不足时交换全部角点对再跑一次，取共识更大的那个。
        ⇒ 不做任何"猜哪一对是远角"的启发式，让 RANSAC 的共识来裁决。
        """
        best_all = None
        for swapped in (False, True):
            self._anchor_quiet = bool(swapped)
            out = self._map_anchor_once(obs, frame, why, swapped)
            if out is not None and (best_all is None
                                    or out["n_inliers"] > best_all["n_inliers"]):
                best_all = out
            if best_all is not None and not swapped:
                # 正序已解出且共识达标 ⇒ 不必再试逆序（省一半算力）
                break
        self._anchor_quiet = False
        return best_all

    def _map_anchor_once(self, obs, frame, why="", swap_corners=False):
        corr, keep = self._anchor_corr(obs, frame, swap_corners=swap_corners)
        n = len(corr)
        if n < MAP_ANCHOR_MIN_PTS:
            if not swap_corners:        # 只在第一遍记日志，避免重复刷屏
                self._anchor_stat("弃权(对应点不足)", n, why)
            return None
        gd = np.array([c[0] for c in corr])
        px = np.array([c[1] for c in corr])

        # ---- RANSAC：枚举 4 子集求最大共识 ----
        # 为什么枚举而不是 cv2.RANSAC：`GroundHomography.solve` 走的是仓库唯一的
        # 去畸变+单应链路（`_undistort_to_norm`），复用它才能保证与导航同一残差
        # 定义；子集只有 C(9,4)=126 个、每个都是 4 点小解，代价可忽略。
        idx_all = list(range(n))
        combos = list(combinations(idx_all, 4))
        if len(combos) > MAP_ANCHOR_MAX_COMBOS:
            step = len(combos) / float(MAP_ANCHOR_MAX_COMBOS)
            combos = [combos[int(i * step)] for i in range(MAP_ANCHOR_MAX_COMBOS)]
        best = None
        for sub in combos:
            sub = list(sub)
            try:
                hg = GroundHomography.solve(px[sub], gd[sub], PITCH_NAV, HEAD_CENTER)
            except Exception:
                continue
            try:
                pred = hg.ground_to_pixels(gd)
            except Exception:
                continue
            res = np.linalg.norm(np.asarray(pred, float) - px, axis=1)
            inl = res <= MAP_ANCHOR_INLIER_PX
            k = int(inl.sum())
            key = (k, -float(res[inl].max() if k else 1e9))
            if best is None or key > best[0]:
                best = (key, inl.copy(), res.copy())
        if best is None:
            self._anchor_stat("弃权(单应求解全部失败)", n, why)
            return None
        (k_best, _neg), inl, res = best
        if k_best < MAP_ANCHOR_MIN_INLIERS:
            self._anchor_stat(f"弃权(共识仅{k_best}<{MAP_ANCHOR_MIN_INLIERS})",
                              n, why)
            return None
        # ---- 用全部内点重解一次（提高精度；仍是同一链路）----
        try:
            hg = GroundHomography.solve(px[inl], gd[inl], PITCH_NAV, HEAD_CENTER)
            pred = hg.ground_to_pixels(gd)
            res = np.linalg.norm(np.asarray(pred, float) - px, axis=1)
            inl2 = res <= MAP_ANCHOR_INLIER_PX
            if int(inl2.sum()) >= MAP_ANCHOR_MIN_INLIERS:
                inl, res = inl2, res
        except Exception:
            pass
        # ---- 合理性守卫（荒谬解一律弃权，绝不"先信了再说"）----
        try:
            pos, fwd = hg.ground_pose()
        except Exception as e:
            self._anchor_stat(f"弃权(位姿分解失败:{type(e).__name__})", n, why)
            return None
        R, t, C, col_diff = hg.decompose()
        hcm = float(C[2])
        if not (MAP_ANCHOR_H_RANGE_CM[0] <= hcm <= MAP_ANCHOR_H_RANGE_CM[1]):
            self._anchor_stat(f"弃权(反解高度{hcm:.0f}cm越界)", n, why)
            return None
        if float(col_diff) > MAP_ANCHOR_COL_DIFF_MAX:
            self._anchor_stat(f"弃权(H列模长差{col_diff:.3f}过大)", n, why)
            return None
        if float(np.linalg.norm(np.asarray(pos, float) - np.array([50.0, 50.0]))) \
                > MAP_ANCHOR_POSE_TOL_CM + 100.0:
            self._anchor_stat(f"弃权(位姿({pos[0]:.0f},{pos[1]:.0f})荒谬)", n, why)
            return None
        theta = float(np.arctan2(fwd[0], fwd[1]))
        # 与死推位姿的**独立对照**（只记日志，不参与决策）：这是现场唯一能
        # 量化"死推到底漂了多少"的证据，而现有所有遥测都只有死推自身。
        dr = np.asarray(self.pose, float)
        drift = float(np.linalg.norm(np.asarray(pos, float) - dr[:2]))
        self._anchor_stat("OK", n, why, n_in=int(inl.sum()), h=hcm,
                          drift=drift)
        return {
            "hg": hg, "pose": np.array([float(pos[0]), float(pos[1]), theta]),
            "cam_height_cm": hcm,
            "deadreckon_drift_cm": drift,
            "head": int(getattr(self.state, "current_head_pulse", HEAD_CENTER)),
            "hidden": np.array([o.digit for o in keep])[~inl],
            "inliers": [keep[i] for i in range(n) if inl[i]],
            "outliers": [keep[i] for i in range(n) if not inl[i]],
            "resid_px": res, "n_pts": n, "n_inliers": int(inl.sum()),
            "digits": [o.digit for o in keep],
        }

    def _anchor_stat(self, verdict, n, why="", n_in=0, h=None, drift=None):
        """锚的诚实遥测（默认只在真的开锚时打印，避免默认路径多出日志）

        `_anchor_quiet`：角点逆序那一遍是"补试"，不重复计数也不打印——
        `_anchor_calls` 是**可用率的分母**，一次调用只能算一次。
        """
        if self._anchor_quiet:
            return
        self._anchor_calls += 1
        if self._anchor_ok is None:
            self._anchor_ok = 0
        if verdict == "OK":
            self._anchor_ok += 1
            if drift is not None:
                self._anchor_drift.append(float(drift))
        if not MAP_ANCHOR_ENABLED:
            return
        msg = (f"[几何锚] {verdict}｜对应 {n} 个数字，有效点 {n_in} 个"
               f"{'' if h is None else f'，相机离地 {h:.0f}cm'}"
               f"{'' if drift is None else f'，与按动作推算的位置相差 {drift:.1f}cm'}"
               f"{'' if not why else f'（{why}）'}")
        self._anchor_log.append(msg)
        if len(self._anchor_log) > 40:
            del self._anchor_log[:-40]
        print(msg)

    def _search_hint(self, digit):
        """搜索转向提示（机体系方位角，度）：**锚优先，死推兜底**

        用户构想 ②-d"根据图像里有的内容反推位置，启发下一次的搜索"的可执行形式：
        锚给出的是**本帧实测位姿**（实测 0.2~0.9cm 级），而死推位姿在形变/失败
        搜索后实测可偏 30~112cm。锚不可用时**原样回退**，不改变默认行为。
        只在头部中位档采到的锚才用于提示（H 已吸收头部角，但"机体系方位角"
        要求相机轴 = 机体轴，否则会少补一个头部角）。
        """
        a = self._anchor_last
        if MAP_ANCHOR_ENABLED and a is not None and digit in self.digit_cell \
                and a.get("head") == HEAD_CENTER:
            try:
                _f, _l, bearing = a["hg"].target_in_robot_frame(
                    grid_cell_center(self.digit_cell[digit]))
                return float(bearing)
            except Exception:
                pass
        return (self.target_relative(digit)[2] if digit in self.digit_cell else 0.0)

    def _region_masks(self, w, h):
        """把示意图四块区域栅格化成布尔掩膜（按画幅尺寸缓存，只算一次）

        上(远) ┌───────────────┐
               │ 橙 │  绿  │ 橙 │   绿 = 走廊内 且 紫区高度**以上**
               ├────┼─────┼────┤   紫 = 走廊内 且 紫区高度**以内**
               │ 橙 │蓝│紫│蓝│ 橙│   蓝 = 蓝区高度内 且 走廊外、蓝外沿以内
               └───────────────┘   橙 = 其余
        下(近)
        「走廊」= |dx| ≤ 绿半宽(t)（上窄下宽的斜线）；紫区的横向边界**就是**走廊，
        不另设宽度（见 VIS_ZONE_PURPLE_HEIGHT 注释）。蓝左/蓝右按画幅中线切开，
        供"左右溢出不对称"（站在格子中央的判据）用。
        """
        key = (int(w), int(h))
        cache = getattr(self, "_region_cache", None)
        if cache is not None and cache[0] == key:
            return cache[1]
        xs = np.arange(w, dtype=np.float32)
        ys = np.arange(h, dtype=np.float32)
        dx = np.abs(xs - w / 2.0) / w                       # (w,)
        t = ys / h                                          # (h,)
        half_green = (VIS_ZONE_GREEN_TOP
                      + (VIS_ZONE_GREEN_BOT - VIS_ZONE_GREEN_TOP) * t)
        in_corr = dx[None, :] <= half_green[:, None]        # (h,w) 走廊
        ph = float(VIS_ZONE_PURPLE_HEIGHT)
        below_p = t >= (1.0 - ph)
        purple = in_corr & below_p[:, None]
        green = in_corr & (~below_p)[:, None]
        bh = float(VIS_ZONE_BLUE_HEIGHT)
        below_b = t >= (1.0 - bh)
        u = (np.clip((t - (1.0 - bh)) / bh, 0.0, 1.0) if bh > 0
             else np.ones_like(t))
        half_blue = (VIS_ZONE_BLUE_TOP
                     + (VIS_ZONE_BLUE_BOT - VIS_ZONE_BLUE_TOP) * u)
        blue = below_b[:, None] & (~in_corr) & (dx[None, :] <= half_blue[:, None])
        orange = ~(green | purple | blue)
        left = (xs < w / 2.0)[None, :]
        out = {"green": green, "purple": purple, "blue": blue, "orange": orange,
               "blueL": blue & left, "blueR": blue & (~left)}
        self._region_cache = (key, out)
        return out

    # =================================================================
    # ★ 统一决策（P1 重写，2026-09-25）——三档分区 ＋ 一个循环走完全程
    # =================================================================
    # 需求真相源：docs/关卡算法/彩色数字九宫格-nine_grid/
    #             需求规格-2026-09-25-统一决策重写.md
    #   · 三档分区（绿直行 / 蓝横移 / 橙旋转）= 用户方案第 3 条，按**画面位置**判档；
    #   · 统一决策 = 不分三段、没有交棒点，**每帧同一套判据**；
    #   · 一次决策只下发**一个**原语（用户明确放弃"批量转弯"）；
    #   · 不用 yaw 的**数值**做规划（只留伺服增益），不把死推位姿接进决策。

    def _body_yaw_deg(self, px, frame_w, head_pulse=None):
        """画面列 → **机体系方位角**（右正，度）

        头部不在中位时，画面列要按头部角折算回"头回中位时它该在的列"——否则
        偏头找到的目标（头右偏 40° 时它在画面正中）会被误判成"正前方"。

        ⚠️ **不要在这里补 `self._pitch_offset_deg`**（曾这么以为，已实测否证）：
        该量在投影模型里只进**俯角** `alpha = (1500-pulse)*SERVO_DEG_PER_US +
        pitch_offset_deg`（见 `project_ground_to_pixel` / `GroundHomography.from_pose`），
        物理上是"相机比名义再低头多少度"，**不含任何方位（yaw）信息**。
        仿真实测：偏移取 0° 与 19°，对"面板正前方 40/60/80cm"的**横向**像素预测
        误差都是 **0.3px**（零影响）。而日志里那句"相机相对机体**前偏** +19.0°"
        是**措辞错误**（应为"前倾/下俯偏移"），照它做横向补偿会凭空注入
        ≈19°×19.7px/° ≈ **374px** 的偏置——比它想修的那点误差大一个量级。

        若将来现场**确实**标定出相机-机体**方位**安装偏差（当前模型没有这个参数，
        仿真里 CAM_BODY_OFFSET=0 且实测面板正前方落在 1283px vs 中线 1296px，
        即 13px ≈ 0.7°），应当：① 给投影模型加一个 yaw 安装参数；
        ② 在 `_col_forward` 里按它平移中线。**不许**挪用 `_pitch_offset_deg`。

        ⚠️ 返回值是**伺服增益量**（`CAMERA_FOV_H_DEG` 是 60° 的增益标定，不是真实
        FOV —— 见该常量注释与《完整方案》§8.2），只用于"往哪边转/偏多少"，
        **不许拿它反推角度数值去做步数规划**。
        """
        hp = (self.state.current_head_pulse if head_pulse is None
              else head_pulse)
        head_deg = (hp - HEAD_CENTER) * SERVO_DEG_PER_US
        return -((float(px) - frame_w / 2.0) / frame_w * CAMERA_FOV_H_DEG
                 - head_deg)

    def _col_forward(self, frame_w, head_pulse=None):
        """"机体正前方"落在画面里的列（px）——判档中线的位置

        只有头部角一项（符号与 `_zone_px_of` 的头部折算一致：脉宽大 = 头左转）；
        **不含** `_pitch_offset_deg`，理由见 `_body_yaw_deg` 的实测说明。
        """
        hp = (self.state.current_head_pulse if head_pulse is None
              else head_pulse)
        head_deg = (hp - HEAD_CENTER) * SERVO_DEG_PER_US
        return frame_w / 2.0 + head_deg * frame_w / CAMERA_FOV_H_DEG

    def _zone_of_px_body(self, px, py, w, h, head_pulse=None, prev=None):
        """按**机体系**判档：(px, py) → ("move"|"lat"|"rot", dx_frac)

        与 `_zone_of_px`（画幅中线版）的唯一区别：中线取 `_col_forward()`，
        即把**头部角**折算掉。用户示意图的三块区域是按"机体正前方"画的，
        而偏头拍摄时"画面正中"不是"机体正前方"。

        注：当前投影模型里**没有**相机-机体**方位**安装参数（见 `_body_yaw_deg`），
        故中线除头部角外没有别的平移项。
        """
        px_body = float(px) - (self._col_forward(w, head_pulse) - w / 2.0)
        zone = self._zone_of_px(px_body, py, w, h, prev)
        dx = abs(px_body - w / 2.0) / w if w > 0 else 1.0
        return zone, dx

    def _action_for_zone(self, zone, px_body, w):
        """档位 → 动作名（**一次决策只下发一个原语**）

        绿 = 直行；蓝 = 横移（目标在左→左移）；橙 = 旋转（小转）。
        动作名一律是"单步"原语：批量由调用方的循环次数体现，不由 `times` 参数。
        """
        if zone == "move":
            return "go_forward_one_step"
        if zone == "lat":
            return "left_move" if px_body < w / 2.0 else "right_move"
        return ("turn_left_small_step" if px_body < w / 2.0
                else "turn_right_small_step")

    def _perceive(self, color, pitch=None):
        """★ 一次拍照 → 三个观测量（统一决策的**唯一**感知入口）

        返回 dict 或 None（帧拿不到/预算耗尽）：
          obs     : 目标色最佳观测（`clipped` 时取凸包质心）或 None
          px, py  : 观测在画面里的位置（原生 px）
          w, h    : 画幅尺寸
          shares  : (whole, purple, orange, asym) 四区份额
          box     : 目标框宽（裁切时用 sqrt(hull_area) 兜底）
          frame   : 帧本身（调试/可视化用）

        为什么"一次拍照取三个量"：判档要**目标位置**，到达要**整帧色占比**——
        分开拍两次不仅慢一倍，而且两个量来自不同时刻，判档与判据会打架。
        """
        if self._cell_expired():
            return None
        self._count_frame()
        self._cell_frames += 1
        frame = self.state.capture_frame()
        if frame is None:
            return None
        sh = self._region_shares(frame, color)
        obs_l = self.detector.detect_panels(
            frame, colors=[color], arbitrate=False, drop_border=False)
        o = max(obs_l, key=lambda x: x.hull_area) if obs_l else None
        out = {"obs": o, "frame": frame, "shares": sh,
               "w": float(frame.shape[1]), "h": float(frame.shape[0]),
               "px": None, "py": None, "box": 0.0}
        if o is not None:
            p = o.hull_centroid_px if o.clipped else o.center_px
            out["px"], out["py"] = float(p[0]), float(p[1])
            box = float(o.bbox[2])
            if o.clipped:
                box = max(box, float(np.sqrt(max(o.hull_area, 1.0))))
            out["box"] = box
        return out

    def _region_shares(self, frame, color):
        """整帧色占比 + 分区份额 → (whole, 紫, 橙, 不对称)

        与 `NineGridDetector.color_ratio` **同一条光照归一化链路**（否则阈值不可
        比），但**一次掩膜**同时算出四块区域的份额，不重复归一化。
        「份额」= 该区域内的目标色像素 ÷ **全帧**目标色像素总数
        （所以紫+橙+绿+蓝 = 1；这也是为什么紫门 0.35 与橙门 0.10 可以并列）。
        拿不到帧/掩膜时返回 None。
        """
        if frame is None or frame.size == 0:
            return None
        try:
            ww = int(self.detector.work_width)
            scale = frame.shape[1] / float(ww)
            work = cv2.resize(frame, (ww, int(round(frame.shape[0] / scale))))
            work, self.detector.last_norm = normalize_illumination(work)
            hsv = cv2.cvtColor(work, cv2.COLOR_BGR2HSV)
            mask = build_color_mask(hsv, color)
        except Exception:
            return None
        tot = int(cv2.countNonZero(mask))
        if tot <= 0:
            return 0.0, 0.0, 0.0, 0.0
        m = mask.astype(bool)
        regs = self._region_masks(mask.shape[1], mask.shape[0])
        n = {k: int(m[v].sum()) for k, v in regs.items()}
        return (tot / float(mask.size), n["purple"] / tot, n["orange"] / tot,
                (n["blueL"] - n["blueR"]) / tot)

    def _zone_px_of(self, obs, frame, head_deg=0.0):
        """取"目标在**机体方向**上的画面位置" → (px, py, 画幅宽, 画幅高)

        `head_deg` = 当前头部偏角（左正，来自脉宽）。示意图的三块区域是按
        **机体方向**画的（相机轴 = 机体轴），所以头部不在中位时，画面里的列要
        减去头部角折算的列数，才是"头回中位时目标该在的列"——不折算的话，
        偏头找到的目标（例如头右偏 40° 时它在画面正中）会被误判成"正前方"。

        位置取点与 `_see_target` 取横向偏移时同一个点：**裁切时用凸包质心**
        （框心会被裁掉的边拉偏），否则用框心。
        """
        p = obs.hull_centroid_px if obs.clipped else obs.center_px
        px = float(p[0]) - float(head_deg) * frame.shape[1] / CAMERA_FOV_H_DEG
        return (px, float(p[1]),
                float(frame.shape[1]), float(frame.shape[0]))

    def _zone_of(self, yaw, off_cm=0.0, near=1.0):
        """分区判定 → (zone, off_cm)

        zone ∈ {"move" 直行, "lat" 横移, "rot" 旋转}（对应图的绿/蓝/橙）。
        VIS_ZONE_ENABLED=False 时**完全等价于原二值死区判据**（返回 "move"/"rot"，
        从不返回 "lat"），保证默认行为逐位不变。
        """
        if not VIS_ZONE_ENABLED:
            return ("move", off_cm) if abs(yaw) <= VIS_ALIGN_TOL_DEG \
                else ("rot", off_cm)
        if abs(yaw) <= VIS_ZONE_MOVE_DEG:
            return "move", off_cm
        if abs(yaw) <= VIS_ZONE_ROT_DEG and near >= VIS_ZONE_ROT_NEAR:
            return "lat", off_cm
        return "rot", off_cm

    def _zone_of_px(self, px, py, w, h, prev=None):
        """★ 按示意图判档：绿/蓝/橙三块**画在画面里**，看目标落在哪一块

        只用目标在画面里的位置 (px, py)，不用角度、不用框宽：
            t  = py / h            （0 = 画幅顶边(远)，1 = 画幅底边(近)）
            dx = |px − w/2| / w    （横向偏移占画幅宽的比例）
            绿半宽 = 绿上沿 + (绿下沿 − 绿上沿)·t      —— 斜线（上窄下宽）
            dx ≤ 绿半宽                        → "move"（直行）
            否则若 t ≥ 1 − 蓝区高（在蓝区高度内）：
                蓝半宽 = 蓝上宽 + (蓝下宽 − 蓝上宽)·u，u = 在蓝区内的归一化高度
                dx ≤ 蓝半宽                    → "lat"（横移）
            其余                                → "rot"（旋转）

        迟滞（VIS_ZONE_HYST_DEG，只放宽"离开"条件）按 `度/画幅角` 折算成横向比例，
        语义与旧规则一致：已在本档时边界放宽一点点，避免一两像素抖动来回切档。
        """
        if w <= 0 or h <= 0:
            return "rot"
        t = float(np.clip(py / h, 0.0, 1.0))
        dx = abs(float(px) - w / 2.0) / w
        hy = (VIS_ZONE_HYST_DEG / CAMERA_FOV_H_DEG) if VIS_ZONE_HYST_DEG > 0 else 0.0
        half_green = VIS_ZONE_GREEN_TOP \
            + (VIS_ZONE_GREEN_BOT - VIS_ZONE_GREEN_TOP) * t
        if prev == "move":
            half_green += hy
        if dx <= half_green:
            return "move"
        bh = float(VIS_ZONE_BLUE_HEIGHT)
        if t >= 1.0 - bh:
            u = (t - (1.0 - bh)) / bh if bh > 0 else 1.0
            half_blue = VIS_ZONE_BLUE_TOP \
                + (VIS_ZONE_BLUE_BOT - VIS_ZONE_BLUE_TOP) * u
            if prev == "lat":
                half_blue += hy
            if dx <= half_blue:
                return "lat"
        return "rot"

    def _zone_of_h(self, yaw, off_cm=0.0, near=1.0, px=None, py=None,
                   w=None, h=None):
        """带迟滞的分区判定（`_zone_of` + VIS_ZONE_HYST_DEG）

        **只放宽"离开"条件，不放宽"进入"条件**（见 VIS_ZONE_HYST_DEG 注释）：
        名义门值不被污染，只是同一个门不会因为一两度的抖动而反复切换。
        `VIS_ZONE_ENABLED=False` 或 `VIS_ZONE_HYST_DEG<=0` 时**逐位等价于 `_zone_of`**。

        给了 (px,py,w,h) 且 `VIS_ZONE_PX_ENABLED` 时走**示意图五参数**（迟滞在
        `_zone_of_px` 内部处理）；否则退回旧三阈值（带迟滞），两条路径都只放宽
        "离开"条件。VIS_ZONE_ENABLED=False 时**两条都不用**，逐位等于原二值死区。
        """
        if VIS_ZONE_ENABLED and VIS_ZONE_PX_ENABLED and px is not None:
            zone = self._zone_of_px(px, py, w, h, self._zone_last)
            self._zone_last = zone
            return zone, off_cm
        zone, off = self._zone_of(yaw, off_cm, near)
        prev = self._zone_last
        if VIS_ZONE_ENABLED and VIS_ZONE_HYST_DEG > 0 and prev is not None:
            if prev == "move":
                # 已在窄区：要明显越界才离开
                if abs(yaw) <= VIS_ZONE_MOVE_DEG + VIS_ZONE_HYST_DEG:
                    zone = "move"
            elif prev == "lat" and zone != "move":
                # 已在中间档：门限放宽 HYST 度才掉回旋转档；
                # 'near' 条件**不放宽**（太远时横移没有权威，见 Q3 条件 3）
                if abs(yaw) <= VIS_ZONE_ROT_DEG + VIS_ZONE_HYST_DEG \
                        and near >= VIS_ZONE_ROT_NEAR:
                    zone = "lat"
        self._zone_last = zone
        return zone, off

    def _align_visual(self, digit, t_end, max_iters=6, first_seen=None,
                      no_rot=False):
        """闭环对准（误差源 = 像素 yaw）→ (obs, frame, box) 或 None

        误差来自画面偏移而不是地图方位——形变不影响它。
        **小转角闭环（2026-09-11 真机"转向精度太粗/找下一格异常"重设计）**：
        只要误差在大转分界（VIS_BIG_TURN_DEG）以内，就永远走"小步多次逼近"，
        每轮重新拍帧复测 yaw，规划步数 = floor(|yaw| / max(EMA估计, 下限))。
        为什么不沿用"小转被吞就全局弃用小转、全走大转"：真机日志正是这条
        升级链把整局带偏——弃用小转后只剩 22°/25.7° 量化大转，在 8°（现 3.5°）
        死区外反复过冲 → _big_turn 判"振荡"后干脆**不动** → 对准循环空转
        （日志连打"大转修正 yaw -34.2°"却没有任何动作）→ 丢目标 → 重搜。
        "走到数字 2 之后找数字 3 异常"与"其它异常行动"都出自这里。
        仿真标定的"小转 1.7°/次"只作规划参考（且有下限保护），现场以闭环
        收敛为准：不依赖固定 °/次 常数，估计偏大偏小都由下一轮复测吸收。
        first_seen：调用方刚拍到的那一帧（搜索/接近的观测）可直接复用，
        省一次拍照（真机 ~0.7s/张）。
        """
        self.phase = f"ALIGN{digit}"
        prev_yaw, prev_n = None, 0
        last_act, last_n = None, 0
        for _ in range(max_iters):
            if time.time() > t_end or self._cell_expired():
                return None
            if first_seen is not None:
                seen, first_seen = first_seen, None
            else:
                seen = self._see_target_any(digit)
            if seen is None:
                if last_act is not None:
                    undo = {"turn_left": "turn_right",
                            "turn_right": "turn_left",
                            "turn_left_small_step": "turn_right_small_step",
                            "turn_right_small_step": "turn_left_small_step"}[last_act]
                    print(f"[对准] 目标{digit}丢失：回退 "
                          f"{_action_cn(undo, max(1, last_n // 2))} 后重试")
                    self._act(undo, max(1, last_n // 2))
                    last_act, last_n = None, 0
                    continue
                return None
            obs, frame, yaw, box = seen
            # 用"转过前后 yaw 的变化"更新单次小转实际角（过冲按 |a|+|b| 折算，
            # 否则 per_step 变负 → EMA 崩向 0 → 下一轮请求更多步 → 更过冲）。
            # 注意：EMA 只用于**规划步数**，不再用它决定"是否弃用小转"。
            if prev_yaw is not None and prev_n:
                if abs(yaw) < abs(prev_yaw):
                    per = (abs(prev_yaw) - abs(yaw)) / prev_n
                else:
                    per = (abs(prev_yaw) + abs(yaw)) / prev_n
                per = float(np.clip(per, 0.3, 10.0))
                alpha = (TURN_EMA_ALPHA_FAST
                         if self._turn_updates < TURN_EMA_FAST_UPDATES
                         else TURN_EMA_ALPHA)
                self._turn_updates += 1
                self._small_turn_deg = ((1 - alpha) * self._small_turn_deg
                                        + alpha * per)
                # 仍记录"被地面吞掉"的次数（v2 do_turn 会据此升级大转，
                # 日志诊断也需要），但 v3 对准**不再因为这条就弃用小转**。
                if per < MIN_EFFECTIVE_TURN_DEG:
                    self._small_turn_fail += 1
                    if self._small_turn_fail >= SMALL_TURN_FAIL_BATCHES:
                        self._small_turn_usable = False
                else:
                    self._small_turn_fail = 0
                # ---- 打转判据（2026-09-13 现场"在死区里打转"）----
                # 转过一次之后 |yaw| 反而没变小 → 记一次；连续 VIS_TURN_STALL_TURNS
                # 次都没变小 = 这套闭环在这一格收敛不了（机械步长吃掉误差/打滑/
                # 目标不稳）：先试**一次**大转兜底（小转被地面吞掉是已知现场情形），
                # 再不动就熔断本格——绝不再"再转一次试试"。
                if abs(yaw) < abs(prev_yaw) - 0.5:
                    self._align_stall = 0
                    self._align_worsen = 0
                else:
                    self._align_stall += 1
                    # 方向自检：同号误差被**转得更大**（>VIS_ALIGN_WORSEN_DEG）
                    # = 转向方向反了（左右约定/头部符号）。连续 2 次就翻符号重试；
                    # 翻错也只是再错 2 次，被停转判据兜住。
                    if abs(yaw) > abs(prev_yaw) + VIS_ALIGN_WORSEN_DEG \
                            and (yaw > 0) == (prev_yaw > 0):
                        self._align_worsen += 1
                    else:
                        self._align_worsen = 0
                    if self._align_worsen >= 2:
                        self._align_sign = -self._align_sign
                        self._align_stall = 0
                        self._align_worsen = 0
                        print(f"[对准] 方向校验：按同方向继续转向后误差反而增大"
                              f"（{prev_yaw:+.1f}°→{yaw:+.1f}°）→ 反转转向符号"
                              f"（现 {self._align_sign:+.0f}）")
                    elif self._align_stall >= VIS_TURN_STALL_TURNS:
                        if no_rot:
                            # 收尾段禁用旋转：**连"大转兜底"这条侧门也要堵**
                            # （它在本判据里绕过了下面的分区档——只禁分区档
                            # 不等于真的禁了转向）。
                            print("[对准] 判定为原地打转 → 收尾阶段禁止转向，不再以大角度转向兜底"
                                  "（改由横移档修正）")
                            self._align_stall = 0
                            self._tail_rot_blocked += 1
                        elif self._align_ladder_step(
                                f"连续{self._align_stall}次转向 |yaw| 无改善"
                                f"（{abs(prev_yaw):.1f}°→{abs(yaw):.1f}°）"):
                            self._big_turn(-yaw * self._align_sign)
                            prev_yaw, prev_n = None, 0
                            continue
                        else:
                            return None
                # 左右来回摆（误差跨过 0、两边都还在死区外）= 打转的直接证据
                # （现场"在死区莫名其妙打转"的另一半：步长 > 误差，一步就过冲）
                if (yaw > 0) != (prev_yaw > 0) \
                        and abs(yaw) > VIS_ALIGN_TOL_DEG:
                    self._align_flips += 1
                    if self._align_flips > VIS_ALIGN_MAX_FLIPS:
                        if not self._align_ladder_step(
                                f"死区外左右来回摆 {self._align_flips} 次"
                                f"（{prev_yaw:+.1f}°→{yaw:+.1f}°）"):
                            return None
            # ---- 分区判定：**一次算好、后面复用**（2026-09-24 修正）----
            # 旧代码把"是否已对准"写成裸死区 `abs(yaw) <= VIS_ALIGN_TOL_DEG`
            # **或** `_zone_of(...)=="move"`：VIS_ZONE_ENABLED=True 时，|yaw| 落在
            # 6~12°（正是蓝档该生效的区间）会让第一个析取项先成立 ⇒ 立刻"已对准"
            # 返回 ⇒ 下面的横移档**在数学上不可达**（走到横移档必须 |yaw|>12°，
            # 而那时 _zone_of 只会返回 'rot'）。实测：开/关分区两臂的动作计数
            # **逐项完全相同**，而 'lat' 被算了 50 次全被丢弃。
            # 现在统一走 `_zone_of_h`（带迟滞）；VIS_ZONE_ENABLED=False 时
            # `_zone_of` 内部退化为原来的二值判据 ⇒ 默认路径逐位不变。
            _hd = ((self.state.current_head_pulse - HEAD_CENTER)
                   * SERVO_DEG_PER_US)
            _px, _py, _w, _h = self._zone_px_of(obs, frame, _hd)
            zone, off_cm = self._zone_of_h(
                yaw, self._off_cm_of(obs, frame, box),
                self._near_of(box, frame),
                px=_px, py=_py, w=_w, h=_h)
            if zone == "move":
                print(f"[对准] 已对准（偏角 {yaw:+.1f}°，框宽 {box:.0f}px）")
                return obs, frame, box
            # ---- 三档分区的中间档：横移（厘米级，最准）----
            # VIS_ZONE_ENABLED=False 时 `_zone_of` 只会返回 move/rot
            # ⇒ 这里永不进入 ⇒ 默认行为零变化。
            # no_rot（收尾段禁用旋转，见 VIS_ZONE_NO_ROT_TAIL）：把 'rot' 也当
            # 横移处理——近距离一步旋转 = 9.8cm > 开关容差 5.5cm，做不进开关区。
            if zone == "lat" or (no_rot and zone == "rot"):
                lat = "left_move" if yaw > 0 else "right_move"
                self._act(lat, 1)
                last_act, last_n = lat, 1
                print(f"[对准] 平移档 {_action_cn(lat)}（偏角 {yaw:+.1f}°，"
                      f"off {off_cm:+.1f}cm"
                      f"{'，收尾禁转' if zone == 'rot' else ''}）")
                # ★ 必须更新 prev_yaw：打转判据比的是"上一步之后 |yaw| 有没有变小"，
                # 横移是**有效动作**（把目标拉回中央）；不更新会让判据拿两步前的值
                # 比、把横移序列误判成"连续无改善"→ 假熔断。
                prev_yaw, prev_n = yaw, 1
                continue
            # 大转**只作兜底**：① 误差本来就大（>30°）；② 大转振荡记忆未生效时
            # 才用。振荡已发生时不再调 _big_turn（它会直接 return，等于空转），
            # 落到下面的小转闭环——保证每一轮都发出**真实动作**，不会空转。
            if abs(yaw) > VIS_BIG_TURN_DEG and not self._turn_oscillation:
                print(f"[对准] 以大角度转向兜底修正，偏角 {yaw:+.1f}°")
                # _big_turn 用"右正"约定，故取负；_align_sign 见方向自检
                self._big_turn(-yaw * self._align_sign)
                prev_yaw, prev_n = None, 0
                continue
            # 小转角闭环：floor 保证"规划转角 ≤ 剩余误差"（不计划性过冲）；
            # 估计角有下限保护（见 VIS_SMALL_TURN_MIN_STEP_DEG），
            # 真实收敛靠下一轮复测。
            step = max(self._small_turn_deg, VIS_SMALL_TURN_MIN_STEP_DEG)
            n = int(np.clip(int(np.floor(abs(yaw) / step)),
                            1, SMALL_TURN_MAX_STEPS))
            # yaw > 0 = 目标在画面左侧 → 左转（符号由方向自检标定）
            action = ("turn_left_small_step" if yaw * self._align_sign > 0
                      else "turn_right_small_step")
            self._act(action, n)
            self._last_turn = (action, n)
            last_act, last_n = action, n
            print(f"[对准] 小转角转向 {n} 次（偏角 {yaw:+.1f}°，估计 "
                  f"{self._small_turn_deg:.1f}°/次）")
            prev_yaw, prev_n = yaw, n
        return None

    def _approach_visual(self, digit, t_end, max_iters=60):
        """接近：目标框宽达 VIS_ARRIVE_BOX_PX 即交棒低头段

        距离只用框宽（相对量，抗形变）；卡滞判据用"框宽是否还在涨"
        （参考实现：Δproximity < 5 → 后退一步重识别）。
        """
        self.phase = f"APPROACH{digit}"
        arr = float(VIS_ARRIVE_BOX_PX)
        prev_box = None
        stall = 0
        for _ in range(max_iters):
            if time.time() > t_end or self._cell_expired():
                return False
            seen = self._see_target(digit)
            # ★ 2026-09-23：这里原来写死 `abs(yaw) <= VIS_ALIGN_TOL_DEG`，会在
            # **咨询分区之前**就直接放行前进 —— 结果 yaw 落在 6~12°（正是蓝档
            # "该横移"的区间）时分区律根本没被问到，中间档不可达（实测：8 局
            # 56 格里 _zone_of 返回 'lat' 0 次）。改成走同一套 `_zone_of` 判据
            # 后，"直行"的定义在 ALIGN 与 APPROACH 两段才真正统一。
            # VIS_ZONE_ENABLED=False 时 `_zone_of` 退化为原来的二值判据，
            # 行为逐位不变。
            # ★ 2026-09-24：改用 `_zone_of_h`（带迟滞）并**把 near 传下去**——
            # 收尾段（目标已够近）禁用旋转，见 VIS_ZONE_NO_ROT_TAIL。
            if seen is None:
                got = self._align_visual(digit, t_end, first_seen=seen)
                if got is None:
                    print(f"[接近] 目标{digit}丢失，交回搜索段")
                    return False
                box = got[2]
            else:
                near_now = self._near_of(seen[3], seen[1])
                _hd = ((self.state.current_head_pulse - HEAD_CENTER)
                       * SERVO_DEG_PER_US)
                _px, _py, _w, _h = self._zone_px_of(seen[0], seen[1], _hd)
                zone_now, _off = self._zone_of_h(
                    seen[2], self._off_cm_of(seen[0], seen[1], seen[3]),
                    near_now, px=_px, py=_py, w=_w, h=_h)
                # 收尾禁转**不挂在 VIS_ZONE_ENABLED 上**（否则它永远无法与
                # 二值基线做 A/B——只能跟分区臂比，就分不清是谁的功劳）。
                tail = (VIS_ZONE_NO_ROT_TAIL
                        and near_now >= VIS_ZONE_ROT_NEAR)
                if zone_now == "move":
                    # 已对准：直接前进，**不再多拍一帧**（收尾禁转只影响"没对准"
                    # 时用什么手段修正，不改变"已对准就前进"这条语义）
                    box = seen[3]
                else:
                    got = self._align_visual(digit, t_end, first_seen=seen,
                                             no_rot=tail)
                    if got is None:
                        print(f"[接近] 目标{digit}丢失，交回搜索段")
                        return False
                    box = got[2]
            print(f"[接近] 框宽 {box:.0f}px（到位线 {arr:.0f}px）")
            if box >= arr:
                # 交棒 yaw 只作遥测：死区 12° 下它最大可到 ~12°，
                # 由此产生的横向残余由低头段的厘米级横移纠偏吸收。
                self._cell_handoff_yaw = float(seen[2]) if seen is not None \
                    else None
                if self._cell_handoff_yaw is not None:
                    print(f"[接近] 交接时残余偏角 {self._cell_handoff_yaw:+.1f}°"
                          f"（死区 {VIS_ALIGN_TOL_DEG:.0f}°，"
                          "横向残余交低头段纠）")
                return True
            if prev_box is not None and abs(box - prev_box) < VIS_STALL_BOX_PX:
                stall += 1
                if stall >= 2:
                    print("[接近] 前进无效（框宽未增大）：后退一步后重新识别")
                    self._act("back_one_step", 1)
                    stall, prev_box = 0, None
                    continue
            else:
                stall = 0
            prev_box = box
            if box < 0.6 * arr:
                n = VIS_BATCH_MAX_STEPS
            elif box < 0.85 * arr:
                n = 3
            else:
                n = 1
            self._act("go_forward_one_step", n)
        print("[接近] 循环次数已达上限")
        return False

    def _arrive_visual(self, digit, t_end):
        """低头到达：颜色占比"出现 → 消失"判定压过目标格（尺度无关版）

        判据 = 记录本次接近的占比峰值，峰值过绝对下限后占比跌破峰值的
        VIS_COLOR_DROP_FRAC → 已压过该格。它描述的是"色块从机器人视野里
        由出现到消失"这一**机器人与色块的相对几何关系**，与相机高度/俯仰
        无关 → 抗地板形变。
        **横向纠偏是厘米级的**（2026-09-13 接线修正）：dx/box_w×PANEL_WIDTH_CM
        是投影不变量，换算成横向厘米后用 left/right_move 一步 2.2cm 直接消掉，
        而不是"小转 1 步"（2° 在 35cm 上只挪 1.2cm，纠 7cm 要 6 次＝等于没纠）。
        纠偏**不再限制在"见到颜色之前"**：交棒点死区 12° → 横向残余可达
        35·tan12° ≈ 7cm，这段正是"踩不到微动开关"的来源；只要还在前进前压
        阶段，就允许继续纠（总次数上限 VIS_LAT_MAX_CORRECTIONS）。
        前压总量封顶 VIS_ARRIVE_PRESS_MAX_CM（45cm）：压满仍未判到回落就交
        死推兜底复核，绝不一路压出去。
        **到达证据门（2026-09-13 假到达修复）**：见 VIS_ARRIVE_EVIDENCE_* 常量
        注释。"占比峰值→回落"只是"整帧色像素变少"，必须叠加"本次接近里见过
        一块形状/尺度都像面板的同色区域"，才允许判"压过"；另有与前压量挂钩的
        物理合理性上限 VIS_ARRIVE_PRESS_PLAUSIBLE_CM。被拒的次数与原因进
        遥测——现场靠它区分"视觉没到位"和"门太严"。
        """
        self.phase = f"ARRIVE{digit}"
        self.state.set_pitch(PITCH_DOWN)
        color = self._target_color(digit)
        peak = 0.0
        prev_ratio = None
        lat_fixes = 0
        press_cm = 0.0
        # 到达证据门：峰值帧的"面板级"证据 + 拒因（诚实遥测）
        peak_cover = -1.0       # 占比峰值那一帧的面板 hull / 画幅（-1 = 未测到）
        ev_cover_best = 0.0     # 本次接近里见过的最大 hull/画幅（仅遥测）
        ev_aspect_best = 0.0    # 上述那帧的 h/w（仅遥测）
        ev_reject = 0           # 因证据不足被拒的"回落"次数（诚实遥测）
        ev_reasons = []         # 去重后的拒因
        # 时间预算自适应：剩余时间不足时收缩迭代上限（真机拍照 ~0.7s/张，见
        # VIS_CAPTURE_COST_S；仿真里动作/拍照是瞬时的，因此这条只影响真机行为）
        iters_max = VIS_ARRIVE_MAX_ITERS
        cells_left = max(1, 8 - digit)
        if (self.deadline - time.time()) / cells_left < 90.0:
            iters_max = max(12, int(iters_max * 0.6))
        # 几何到达判据（WS4）：每 VIS_ARRIVE_ANCHOR_EVERY 帧用 MAP-ANCHOR 解一次
        # 实测位姿，直接看"我离目标格心多远"——不依赖色占比、也不依赖死推。
        cell_xy = (np.asarray(grid_cell_center(self.digit_cell[digit]), float)
                   if digit in self.digit_cell else None)
        anchor_tick = 0
        try:
            for _ in range(iters_max):
                if time.time() > t_end:
                    return False
                self._count_frame()
                self._cell_frames += 1      # 低头段不走 _capture()，这里补记
                frame = self.state.capture_frame()
                if frame is None:
                    return False
                # ---- 几何到达判据（默认关；见 VIS_ARRIVE_ANCHOR_ENABLED）----
                if VIS_ARRIVE_ANCHOR_ENABLED and cell_xy is not None:
                    anchor_tick += 1
                    if anchor_tick % max(1, VIS_ARRIVE_ANCHOR_EVERY) == 0:
                        _ao = self.detector.detect_panels(
                            frame, arbitrate=False, drop_border=False)
                        _anc = self._map_anchor(
                            _ao, frame, why=f"ARRIVE{digit}")
                        if _anc is not None:
                            _d = float(np.linalg.norm(
                                np.asarray(_anc["pose"], float)[:2] - cell_xy))
                            self._anchor_arrive_d.append(_d)
                            if _d <= VIS_ARRIVE_ANCHOR_TOL_CM:
                                self._anchor_arrive_hits += 1
                                self._arrive_evidence = (
                                    f"几何到达判据（几何锚实测距格心 {_d:.1f}cm"
                                    f"≤{VIS_ARRIVE_ANCHOR_TOL_CM}cm）；"
                                    f"有效点 {_anc['n_inliers']}/{_anc['n_pts']}"
                                    f"，反解相机离地 {_anc['cam_height_cm']:.0f}cm，"
                                    f"已前压 {press_cm:.0f}cm"
                                    f"（颜色占比峰值 {peak:.4f}）")
                                print(f"[到达] 几何判据成立：实测位置距格心 "
                                      f"{_d:.1f}cm（有效点 {_anc['n_inliers']}/"
                                      f"{_anc['n_pts']}）→ 判定到达")
                                return True
                            print(f"[到达] 几何锚可用：实测位置距格心 {_d:.1f}cm"
                                  f"（阈值 {VIS_ARRIVE_ANCHOR_TOL_CM:.1f}cm，"
                                  f"有效点 {_anc['n_inliers']}/{_anc['n_pts']}）")
                ratio = self.detector.color_ratio(frame, color)
                # 峰值帧也升格（见 VIS_ARRIVE_EVIDENCE_MIN_COVER 注释）：峰值出现
                # 的那一帧才是"面板在画面里最大/最完整"的一帧，它的面板级面积
                # 才是该用来验证"这个峰值真的来自一块面板"的证据。
                if ratio > peak:
                    peak = ratio
                    peak_cover = -1.0
                print(f"[到达] 颜色占比 {ratio:.4f}（峰值 {peak:.4f}，"
                      f"判据 <{VIS_COLOR_DROP_FRAC * peak:.4f}）")
                # 证据门素材：同一帧里找"最像面板"的同色区域（保留观测里的
                # 最大 hull）。它在后面既给"是否见过面板"作证，也决定能不能
                # 用它的质心做横移纠偏（擦边条不是合格的控制对象）。
                obs = self.detector.detect_panels(frame, colors=[color],
                                                  arbitrate=False,
                                                  drop_border=False)
                frame_area = float(frame.shape[0] * frame.shape[1])
                ev = max(obs, key=lambda x: x.hull_area) if obs else None
                # 证据门素材：本次接近里见过的**最大**面板级同色区域（单调不减，
                # 只会因为有东西真的靠近而变大）；以及"当前帧的最大观测是不是
                # 画幅下沿的擦边条"（只影响横移控制与临门帧的形状审查）。
                ev_cover_now = 0.0
                ev_strip_now = False
                if ev is not None:
                    bw = max(float(ev.bbox[2]), 1.0)
                    bh = max(float(ev.bbox[3]), 1.0)
                    ev_cover_now = float(ev.hull_area) / max(frame_area, 1.0)
                    if ev_cover_now > ev_cover_best:
                        ev_cover_best = ev_cover_now
                        ev_aspect_best = bh / bw
                    ev_strip_now = (int(ev.clipped) == 0
                                    and bh / bw < VIS_ARRIVE_EVIDENCE_MIN_ASPECT)
                if peak == ratio:       # 本帧就是峰值帧：钉住它的面板级证据
                    peak_cover = max(peak_cover, ev_cover_now)
                # ★ 前压到底的兜底回落（见 VIS_ARRIVE_TAIL_ACCEPT_FRAC）：
                #   默认 0 ⇒ tail_accept 恒 False ⇒ 判据与原来逐位相同。
                tail_accept = (
                    VIS_ARRIVE_TAIL_ACCEPT_FRAC > 0.0
                    and press_cm >= VIS_ARRIVE_PRESS_MAX_CM
                    * VIS_ARRIVE_TAIL_PRESS_FRAC
                    and ratio < VIS_ARRIVE_TAIL_ACCEPT_FRAC * peak)
                if peak >= VIS_COLOR_SEEN_MIN \
                        and (ratio < VIS_COLOR_DROP_FRAC * peak or tail_accept):
                    # ① 证据门：**峰值那一帧**必须真见过"大到像面板"的同色区域，                    #    不能只靠整帧色像素变少（后者可能是侧滑出画/别的同色块
                    #    离开视野）。用峰值帧而不是"历史最大"：形变会把整条曲线
                    #    的尺度一起改掉（同一面板在不同俯仰下 box 面积差 30%），
                    #    只有跟着峰值自身的语义走才不引入新的尺度依赖。
                    if peak_cover < VIS_ARRIVE_EVIDENCE_MIN_COVER:
                        ev_reject += 1
                        why = (f"峰值帧面板证据仅占画幅 {peak_cover:.3f}"
                               f"<{VIS_ARRIVE_EVIDENCE_MIN_COVER}")
                        if why not in ev_reasons:
                            ev_reasons.append(why)
                        print(f"[到达] 占比已回落，但证据不足（{why}）"
                              "→ 不判到达（继续前压/兜底）")
                    # ② 物理合理性：前压超过"交棒 + 一格"就不可能是在压目标
                    elif press_cm > VIS_ARRIVE_PRESS_PLAUSIBLE_CM:
                        why = (f"前压{press_cm:.0f}cm>"
                               f"{VIS_ARRIVE_PRESS_PLAUSIBLE_CM:.0f}cm")
                        ev_reject += 1
                        if why not in ev_reasons:
                            ev_reasons.append(why)
                        print(f"[到达] 占比已回落，但{why}（已越过一整格）"
                              "→ 不判到达（继续前压/兜底）")
                    else:
                        self._arrive_evidence = (
                            f"低头颜色占比由峰值 {peak:.4f} 回落至 {ratio:.4f}"
                            f"（判据 <{VIS_COLOR_DROP_FRAC * peak:.4f}"
                            f"{'，前压封顶后兜底' if tail_accept else ''}）；"
                            f"已前压 {press_cm:.0f}cm，横向修正 {lat_fixes} 次｜"
                            f"证据 峰值帧色块占画幅 {peak_cover:.3f}"
                            f"（高宽比 {ev_aspect_best:.2f}，阈值"
                            f"{VIS_ARRIVE_EVIDENCE_MIN_COVER}）"
                            f"｜证据门拒止 {ev_reject} 次"
                            + (f"（{'；'.join(ev_reasons)}）"
                               if ev_reasons else ""))
                        print(f"[到达] 颜色占比由峰值 {peak:.4f} 降至 {ratio:.4f}"
                              f"（证据 峰值帧色块占画幅 {peak_cover:.3f}）"
                              "→ 判定已越过目标格")
                        return True
                if ev is not None and lat_fixes < VIS_LAT_MAX_CORRECTIONS:
                    o = ev
                    bw = max(float(o.bbox[2]), 1.0)
                    bh = max(float(o.bbox[3]), 1.0)
                    # 横移控制的对象健全性（2026-09-13 实测）：擦边条（细长）的
                    # 凸包质心不是合理的面板中心估计，拿它做横移会把目标推出
                    # 画幅——阶跃场景的假到达正是"用 1100×380 的擦边条做 2 次
                    # ×3 步横移"。遇到这种对象就**先前进**，让观测变干净再纠横。
                    if ev_strip_now:
                        print(f"[到达] 观测呈细长条（高宽比 {bh / bw:.2f}"
                              f"<{VIS_ARRIVE_EVIDENCE_MIN_ASPECT}，完整可见）"
                              "→ 跳过横移纠偏，先前压取干净观测")
                        o = None
                    if o is not None:
                        px = o.hull_centroid_px if o.clipped else o.center_px
                        box = max(float(o.bbox[2]), 1.0)
                        dx_cm = ((float(px[0]) - frame.shape[1] / 2.0) / box
                                 * PANEL_WIDTH_CM)
                        if abs(dx_cm) > VIS_LAT_TOL_CM:
                            if VIS_ARRIVE_LAT_VIA_SIDESTEP:
                                step_cm = (RIGHT_MOVE_CM if dx_cm > 0
                                           else LEFT_MOVE_CM)
                                n_lat = int(np.clip(
                                    round(abs(dx_cm) / step_cm),
                                    1, VIS_ARRIVE_LAT_MAX_STEPS))
                                print(f"[到达] 横向偏差 {dx_cm:+.1f}cm → 以平移修正 "
                                      f"{'右' if dx_cm > 0 else '左'}{n_lat}步"
                                      f"（{lat_fixes + 1}/{VIS_LAT_MAX_CORRECTIONS}）")
                                self._act("right_move" if dx_cm > 0
                                          else "left_move", n_lat)
                            else:
                                print(f"[到达] 横向偏差 {dx_cm:+.1f}cm → 以小转角转向修正"
                                      f"（{lat_fixes + 1}/{VIS_LAT_MAX_CORRECTIONS}）")
                                self._act("turn_right_small_step" if dx_cm > 0
                                          else "turn_left_small_step", 1)
                            lat_fixes += 1
                            continue
                # 第二个独立判据：**死推到位即停压**（见 VIS_ARRIVE_STOP_FWD_CM）。
                # 它让"踩到格心"这件事不完全依赖颜色曲线的形状——相机俯仰被地板
                # 形变改掉时，颜色判据可能永远不回落（实测前压 44cm 仍不回落），
                # 而死推距离不受俯仰影响。任一判据成立即到位，依据写清哪一条。
                if digit in self.digit_cell:
                    fwd_now, lat_now, _bn = self.target_relative(digit)
                    if abs(fwd_now) <= VIS_ARRIVE_STOP_FWD_CM \
                            and abs(lat_now) <= VIS_ARRIVE_FALLBACK_LAT_CM:
                        self._note_dr_hit("stop", digit, fwd_now, lat_now)
                        ev_txt = (f"峰值帧色块占画幅 {peak_cover:.3f}"
                                  f"（高宽比 {ev_aspect_best:.2f}）")
                        self._arrive_evidence = (
                            f"按动作推算已到位（纵向 {fwd_now:+.1f}、"
                            f"横向 {lat_now:+.1f}cm；已前压 {press_cm:.0f}cm；"
                            f"颜色占比峰值 {peak:.4f} 未回落｜"
                            f"{ev_txt}｜证据门拒止 {ev_reject} 次）")
                        print(f"[到达] 按动作推算已到位（纵向 {fwd_now:+.1f} "
                              f"横向 {lat_now:+.1f}cm）→ 判定到达")
                        return True
                # 步长自适应：占比**还在涨**时用 3 步批量（6cm）赶路，一旦不再涨
                # （到峰/过峰）改单步（2cm）精停。实测：用"与峰值比"判据会
                # 在爬升段误判成"接近峰值"而一路 2cm 挪（占比 0.06→0.13 花了
                # 18 次迭代＝低头段占了全程 61% 的拍照）。
                rising = prev_ratio is None or ratio >= prev_ratio
                prev_ratio = ratio
                press_steps = (VIS_ARRIVE_PRESS_COARSE_STEPS if rising
                               else VIS_ARRIVE_PRESS_FINE_STEPS)
                if press_cm + press_steps * FORWARD_ONE_STEP_CM \
                        > VIS_ARRIVE_PRESS_MAX_CM:
                    print(f"[到达] 前压已达上限 {press_cm:.0f}cm"
                          f"（{VIS_ARRIVE_PRESS_MAX_CM:.0f}cm）且占比未回落"
                          " → 交由按动作推算兜底复核")
                    break
                press_cm += press_steps * FORWARD_ONE_STEP_CM
                self._act("go_forward_one_step", press_steps)
            print(f"[到达] 循环次数／前压额度用尽（峰值占比 {peak:.4f}，"
                  f"已前压 {press_cm:.0f}cm）")
            # 兜底：视觉判据没走完（例如峰值后占比掉得不够）时，用**死推距离**
            # 复核——位姿每格到达后已重置，短程死推（≤1格）精度足够。
            fwd, lat, _b = self.target_relative(digit)
            if abs(fwd) <= VIS_ARRIVE_FALLBACK_CM \
                    and abs(lat) <= VIS_ARRIVE_FALLBACK_LAT_CM:
                self._note_dr_hit("fallback", digit, fwd, lat)
                self._arrive_evidence = (
                    f"按动作推算距离兜底（纵向 {fwd:+.1f}、横向 {lat:+.1f}cm；"
                    f"已前压 {press_cm:.0f}cm 后占比仍未回落，"
                    f"峰值 {peak:.4f}）")
                print(f"[到达] 按动作推算距离兜底判定到位（纵向 {fwd:+.1f} "
                      f"横向 {lat:+.1f}cm）")
                return True
            return False
        finally:
            self.state.set_pitch(PITCH_NAV)

    def _note_dr_hit(self, kind, digit, fwd, lat):
        """记录"死推判据命中"这一事件，并留下**真值落点**（若可得）

        为什么需要它（2026-09-24）：本关到达段有两条**死推**判据
        （循环内 `VIS_ARRIVE_STOP_FWD_CM` ±2cm/±5cm；循环后
        `VIS_ARRIVE_FALLBACK_CM` ±6cm/±5cm）。而死推位姿的实测剖面是：
        距上次重锚 ≤7 个动作时中位 ≤2.2cm，但 8~15 个动作升到 6.8cm(P90 18.7)、
        16~31 个动作 9.9cm(P90 32.2)；**到达段本身要 30~50 个动作**。
        ⇒ 在它最该被信任的地方恰恰最不可信。这两条判据到底是"救回了不少格"
        还是"制造了假到达"，只能靠"命中时的真值落点"来判——本函数就是那个证据。
        真机没有 `state.pos`，记 None（不影响真机行为）。
        """
        self._dr_hits.append(kind)
        truth = getattr(self.state, "pos", None)
        if truth is not None and digit in self.digit_cell:
            c = np.asarray(grid_cell_center(self.digit_cell[digit]), float)
            d = float(np.linalg.norm(np.asarray(truth, float)[:2] - c))
            self._dr_hit_landing.append(d)
            # 只有落点明显偏（> 开关半宽）时才出声，避免正常格刷屏
            if d > 5.5:
                print(f"[到达] 警告：按动作推算的判据（{kind}）成立，但真实位置距格心 {d:.1f}cm"
                      f"（>5.5cm 开关半宽）——纵向 {fwd:+.1f} 横向 {lat:+.1f}cm")

    def _confirm_switch(self, digit):
        """到达收尾：蹭步压微动开关 + 仲裁冲突近距复核

        **诚实声明（2026-09-13）**：微动开关是场地侧器件（计分由 ESP32 读），
        Pi 侧**读不到它的状态**——本函数只能保证"机器人已按判据压过格心一遍"，
        不能保证按钮真的触发。因此日志打印**依据**（到达判据 + 落点死推残差）
        而不是无条件"到达 ✓"；残差大时明确打警告，供赛后与计分表核对。
        """
        self.phase = f"CONFIRM{digit}"
        self._act("back_one_step", 1)
        self._act("go_forward_one_step", 1)
        cell = self.digit_cell.get(digit)
        if cell in self.cell_conflict:
            loc = self.localize(PITCH_DOWN, arbitrate=True)
            if loc:
                for o in loc[0]:
                    if o.digit == digit:
                        verdict = "一致" if o.model_digit == digit \
                            else "仍冲突（以颜色为准，赛后人工核对）"
                        print(f"[复核] 格{cell} 近距数字模型判定为 {o.model_digit}"
                              f"({o.model_conf:.2f}) vs 颜色={digit}——{verdict}")
        self.state.act("stand")
        # 落点残差：位姿此刻仍是死推值（_reanchor_pose 在返回后才重置），
        # 所以这是"机器人与期望格心的差距"的独立估计，不是自证。
        resid = None
        if digit in self.digit_cell:
            fwd, lat, _b = self.target_relative(digit)
            resid = float(np.hypot(fwd, lat))
            self._cell_arrive_resid_cm = resid
        shaky = "  警告: 距格心超过半格，按钮可能未压到" \
            if (resid is not None and resid > GRID_CELL_CM / 2) else ""
        resid_txt = "无数据（无格心映射）" if resid is None else f"{resid:.1f}cm"
        print(f"[确认] 面板{digit} 已压过格心｜判定依据: {self._arrive_evidence or '无'}"
              f"｜距格心 {resid_txt}{shaky}")
        print("[确认] 微动开关状态在 Pi 侧不可读——是否触发以场地计分为准")
        return True

    def _reanchor_pose(self, digit):
        """到达后把死推位姿锚到该格格心（消除逐格漂移，保搜索提示可用）

        航向保持死推值（视觉对准已把目标对正，残余误差只影响粗提示）。
        位置断言来自"到达判定成立"（机器人压在该色块上），同时打印**残差**
        （到达时的死推距离）——它是"这次锚定有多可信"的唯一现场证据。
        试过"残差超半格就不锚定"：标称场景直接打挂（面板6 未确认）——因为标称
        场景里残差大恰恰是**死推漂移**造成的，而锚定正是修它的手段。所以锚定
        照旧，但把残差写进遥测，让现场一眼看出哪一格的"到达"不可信。
        """
        if digit not in self.digit_cell:
            return
        resid = self._cell_arrive_resid_cm
        c = grid_cell_center(self.digit_cell[digit])
        self.pose = np.array([c[0], c[1], self.pose[2]])
        print(f"[锚定] 按动作推算的位置重置到格 {self.digit_cell[digit]}"
              f"（格心场地坐标 {c[0]:.0f},{c[1]:.0f}"
              f"{'' if resid is None else f'，距格心 {resid:.1f}cm'}）")

    def _map_correction(self):
        """可选的地图 GN 校正：成功才采纳，失败只打一行日志

        地板形变会让相机常数失配 → 残差超门控。这是**预期**行为而非错误：
        因此这里静默跳过，绝不触发恢复链（v2 的"定位风暴"根因）。
        """
        loc = self.localize(PITCH_DOWN)
        if loc is None:
            print("[校正] 跳过地图校正（残差超过阈值或面板数量不足——存在地板形变时属预期）")
            return
        print(f"[校正] 采纳地图校正: ({self.pose[0]:.1f},{self.pose[1]:.1f}) "
              f"{np.degrees(self.pose[2]):.1f}°")

    def _go_to_panel_map(self, digit):
        """v2 地图 GN 路径（VIS_NAV_ENABLED=False 时的应急回退）"""
        t_end = min(time.time() + TARGET_TIME_BUDGET_S, self.deadline)
        self._target_seen = False
        self._loc_count = 0
        self._current_digit = digit
        self.phase = f"SEEK{digit}"
        for attempt in range(RETRY_LIMIT + 1):
            if time.time() > t_end:
                print(f"[面板{digit}] 时间预算已耗尽")
                return False
            if self._approach(digit, t_end) and self._enter(digit, t_end):
                return True
            if self._loc_count > LOC_BUDGET_PER_TARGET:
                print(f"[面板{digit}] 定位次数 {self._loc_count} 超过提示阈值"
                      f"（{LOC_BUDGET_PER_TARGET}）——真机时间预算可能不够")
            if attempt < RETRY_LIMIT:
                print(f"[面板{digit}] 未到位，后退一格重试（第 {attempt + 1}/{RETRY_LIMIT} 次）")
                self._act("back_one_step", 2)
        return False

    def _approach(self, digit, t_end):
        """前视闭环接近：对准→横偏→前进，至 MID_DIST 内交棒 ENTER

        卡滞判据用"本次定位 vs 上次动作前的定位"，不再在动作后额外补一帧
        定位（旧实现每次动作 2 次定位，真机拍照 ~0.7s/张也扛不住）。
        """
        self.phase = "APPROACH"
        stall = 0
        prev_fwd = None
        fails = 0
        while time.time() < t_end:
            loc = self.localize(PITCH_NAV)
            if loc is None:
                fails += 1
                if not self._recover(fails):
                    return False
                continue
            fails = 0
            obs, _frame = loc
            if any(o.digit == digit for o in obs):
                self._target_seen = True
            fwd, lat, bearing = self.target_relative(digit)
            print(f"[接近] 纵向 {fwd:+.1f}cm、横向 {lat:+.1f}cm、航向差 {bearing:+.1f}°（单位 cm／度）")

            # 卡滞守卫：与上一次"动作前"定位比较（零额外拍照）
            if prev_fwd is not None and abs(bearing) <= ALIGN_TOL_DEG \
                    and abs(lat) <= LAT_TOL_CM:
                if prev_fwd - fwd < STALL_EPS_CM:
                    stall += 1
                    if stall >= STALL_CONSEC:
                        print(f"[接近] 连续 {STALL_CONSEC} 次改善不足 {STALL_EPS_CM}cm，"
                              "判定卡滞：后退一步脱离")
                        self._act("back_one_step", 1)
                        stall = 0
                        prev_fwd = None
                        continue
                else:
                    stall = 0

            if abs(bearing) > ALIGN_TOL_DEG:
                if self._turn_oscillation \
                        and abs(bearing) < BIG_TURN_OSC_ACCEPT_DEG:
                    # 大转量化振荡：接受残余航向差，靠横移纠偏继续接近
                    pass
                else:
                    if self._turn_oscillation:
                        self._turn_oscillation = False  # 误差已大，重新允许转向
                    self.do_turn(bearing, digit, fwd)
                    prev_fwd = None
                    continue
            if abs(lat) > LAT_TOL_CM and fwd < 2 * FAR_DIST_CM:
                self.do_sidestep(lat)
                prev_fwd = None
                continue
            if fwd <= MID_DIST_CM:
                return True  # 交棒 ENTER

            prev_fwd = fwd
            # 前进：一律 go_forward_one_step（本场地禁用 go_forward）。
            # 远距+对准良好才小批量，上限 BATCH_MAX_STEPS 步（3×2cm=6cm）。
            if fwd > FAR_DIST_CM and abs(bearing) <= BATCH_MAX_ANGLE_DEG \
                    and abs(lat) <= LAT_TOL_CM:
                n = min(BATCH_MAX_STEPS,
                        max(1, int((fwd - MID_DIST_CM) // FORWARD_ONE_STEP_CM)))
            else:
                n = 2 if fwd > 2 * MID_DIST_CM else 1
            self._act("go_forward_one_step", n)
        print("[接近] 时间预算已耗尽")
        return False

    def _enter(self, digit, t_end):
        """低头精细进入：横移+单步，至中心进入脚下判定带

        纵向 < ENTER_BEARING_GATE_CM 后不再按 bearing 转向：目标中心几乎
        在脚下时方位角病态（实测 2cm 处可跳到 24°），转向只会触发
        "退格再转"空耗；此时只用横移纠偏。
        """
        self.phase = "ENTER"
        self.state.set_pitch(PITCH_DOWN)
        stall = 0
        prev_fwd = None
        fails = 0
        try:
            while time.time() < t_end:
                loc = self.localize(PITCH_DOWN)
                if loc is None:
                    # 低头视野窄可能面板不足：借前视补一次
                    self.state.set_pitch(PITCH_NAV)
                    loc = self.localize(PITCH_NAV)
                    self.state.set_pitch(PITCH_DOWN)
                if loc is None:
                    fails += 1
                    if fails >= ENTER_FAIL_LIMIT:
                        print("[进入] 连续定位失败，后退一格重试")
                        return False
                    self._act("back_one_step", 1)
                    continue
                fails = 0
                obs, _frame = loc
                if any(o.digit == digit for o in obs):
                    self._target_seen = True
                fwd, lat, bearing = self.target_relative(digit)
                print(f"[进入] 纵向 {fwd:+.1f}cm、横向 {lat:+.1f}cm、航向差 {bearing:+.1f}°（单位 cm／度）")

                if abs(bearing) > ENTER_ALIGN_TOL_DEG \
                        and fwd > ENTER_BEARING_GATE_CM:
                    self.do_turn(bearing, digit, fwd)
                    prev_fwd = None
                    continue
                if abs(lat) > CONFIRM_LAT_MAX_CM:
                    self.do_sidestep(lat)
                    prev_fwd = None
                    continue
                if fwd > ENTER_TOL_CM:
                    # 卡滞守卫（仅前进迭代，与上一次动作前比较）
                    if prev_fwd is not None \
                            and prev_fwd - fwd < STALL_EPS_CM:
                        stall += 1
                        if stall >= STALL_CONSEC + 1:
                            print("[进入] 前进受阻：后退一步脱离")
                            self._act("back_one_step", 1)
                            stall = 0
                            prev_fwd = None
                            continue
                    else:
                        stall = 0
                    prev_fwd = fwd
                    self._act("go_forward_one_step", 1)
                elif fwd < ENTER_MIN_CM:
                    print("[进入] 已越过目标：后退微调")
                    self._act("back_one_step", 1)
                    prev_fwd = None
                else:
                    return self._confirm(digit)
            print("[进入] 时间预算已耗尽")
            return False
        finally:
            self.state.set_pitch(PITCH_NAV)

    def _confirm(self, digit):
        """到达确认：位姿"脚下覆盖中心"主判 + 接近段检出过目标 + 蹭步压开关

        为什么不用"低头色占比"主判：pitch 1040 时画面下沿对应地面 15.8cm，
        站在面板中心时面板远边仅 14cm——目标面板整个在视野外（实测占比
        0.003，旧阈值 0.10 永远达不到）。参考方案的"出现→压过→消失"是
        过渡判据，不是"站上仍可见"。
        判据：位姿（相机在面板中心 ±4cm 内）+ 接近段确实检出过目标数字面板，
        再用 back(3.2cm)+forward(2.0cm) 蹭步确保压到微动开关。
        """
        self.phase = "CONFIRM"
        fwd, lat, _bearing = self.target_relative(digit)
        on_panel = abs(fwd) <= ENTER_TOL_CM and abs(lat) <= LAT_TOL_CM
        if not on_panel:
            print(f"[确认] 位置未覆盖格心（纵向 {fwd:+.1f}cm、横向 {lat:+.1f}cm）")
            return False
        if not self._target_seen:
            print(f"[确认] 位置已到格心，但接近段未检出面板{digit}"
                  "（颜色阈值/遮挡？），交回导航重试")
            return False

        # 蹭步：后退3.2 + 前进2.0，来回覆盖中心点，确保触发微动开关
        self._act("back_one_step", 1)
        self._act("go_forward_one_step", 1)

        # 仲裁冲突格：低头近距复核一次（只记录，不改主判）
        cell = self.digit_cell.get(digit)
        if cell in self.cell_conflict:
            loc = self.localize(PITCH_DOWN, arbitrate=True)
            if loc:
                for o in loc[0]:
                    if o.digit == digit:
                        verdict = "一致" if o.model_digit == digit \
                            else "仍冲突（以颜色为准，赛后人工核对）"
                        print(f"[复核] 格{cell} 近距数字模型判定为 {o.model_digit}"
                              f"({o.model_conf:.2f}) vs 颜色={digit}——{verdict}")
        self.state.act("stand")
        # v2 路径的"到达"本身就是位姿判据（上面 on_panel 已卡 ±4cm）：
        # 记残差 0 让 _reanchor_pose 的锚定门放行（保持 v2 原有行为）。
        self._cell_arrive_resid_cm = float(np.hypot(fwd, lat))
        print(f"[确认] 面板{digit} 位置覆盖格心（纵向 {fwd:+.1f} "
              f"横向 {lat:+.1f}cm）——到位；微动开关状态在 Pi 侧不可读")
        return True

    # =================================================================
    # 运动原语（白名单 + 自适应转向 + 预测推进）
    # =================================================================

    def _act(self, action, times=1):
        """动作执行 + 位姿预测推进（GN 先验的基础）

        白名单硬门：本场地禁用的大步幅动作（go_forward / go_forward_fast）
        直接拒绝，避免后续改动误用导致摔倒。

        **转向护栏（2026-09-13 真机"一直转 → 转出场地"）**：转向是最便宜的
        动作（不拍照、不耗帧），旧实现没有任何"转够了就停"的概念，对准与搜索
        可以互相接管、在死区里无限转下去。这里累计单格**命令**转角，超预算就
        **拒绝执行**这次转向并熔断本格（安全项，宁可本格记未确认）。
        **离场护栏**：动作执行后统一检查死推位姿是否越出场地外框。
        """
        if action in DISABLED_ACTIONS:
            raise ValueError(
                f"本关卡禁用动作 {action}（小面板+打滑地板易摔倒）；"
                f"前进请用 go_forward_one_step 小批量")
        if action not in ACTION_MODEL:
            raise ValueError(f"未登记的动作: {action}（动作白名单见 ACTION_MODEL）")
        if self._field_guard():
            # 已经判定越界（整局收手）：拒绝再动，只保持站立
            return
        kind, delta = ACTION_MODEL[action]
        req = abs(float(delta)) * int(times)
        if kind == "turn" \
                and self._cell_turn_cmd_deg + req > VIS_TURN_BUDGET_DEG:
            self._trip_cell(
                f"单格累计命令转角 {self._cell_turn_cmd_deg:.0f}°+{req:.0f}° "
                f"超上限 {VIS_TURN_BUDGET_DEG:.0f}°（防原地打转/转出场地）")
            return
        self.state.act(action, times=times)
        # 单格动作计数（硬熔断第三重 + 遥测）：按**实际执行的原语数**记
        # （times 批量算 times 次）——2026-09-13 发现这个计数从来没被累加过，
        # 也就是说 VIS_CELL_HARD_ACTIONS（300）此前是死判据，遥测里恒显示 0。
        self._cell_actions += max(1, int(times))
        self.predict_pose(action, times)
        if kind == "turn":
            self._cell_turn_cmd_deg += req
        else:
            # 期间发生平移：旧转向不可盲目撤销，大转振荡记忆也失效
            self._last_turn = None
            self._last_big_turn = None
        self._field_guard()

    def do_turn(self, bearing, digit, fwd_cm=None):
        """按航向差转向（右正）。近目标先退格再转（防面板边缘转向）。"""
        if fwd_cm is not None and abs(fwd_cm) < TURN_NEAR_LIMIT_CM:
            print("[转向] 距目标过近：先后退一格再转向")
            self._act("back_one_step", 2)

        if abs(bearing) > BIG_TURN_THRESHOLD_DEG or not self._small_turn_usable:
            self._big_turn(bearing)
            return
        # 小转批量（在线估计单次角度）
        n = int(np.clip(round(abs(bearing) / self._small_turn_deg),
                        1, SMALL_TURN_MAX_STEPS))
        action = "turn_right_small_step" if bearing > 0 else "turn_left_small_step"
        self._act(action, n)
        self._last_turn = (action, n)
        # 在线估计实际单次转角（EMA）；定位失败则保持旧估计
        loc = self.localize(PITCH_NAV)
        if loc is not None:
            new_bearing = self.target_relative(digit)[2]
            # 单次实际角估计：过冲时用"已转过+过冲量"折算（否则 per_step 变负，
            # EMA 崩向 0 → 下一轮请求更多小转步 → 更过冲，恶性循环）。
            if abs(new_bearing) < abs(bearing):
                per_step = (abs(bearing) - abs(new_bearing)) / n
            else:
                per_step = (abs(bearing) + abs(new_bearing)) / n
            per_step = float(np.clip(per_step, 0.3, 10.0))
            alpha = (TURN_EMA_ALPHA_FAST
                     if self._turn_updates < TURN_EMA_FAST_UPDATES
                     else TURN_EMA_ALPHA)
            self._turn_updates += 1
            self._small_turn_deg = ((1 - alpha) * self._small_turn_deg
                                    + alpha * per_step)
            if per_step < MIN_EFFECTIVE_TURN_DEG:
                self._small_turn_fail += 1
                if self._small_turn_fail >= SMALL_TURN_FAIL_BATCHES:
                    print(f"[转向] 小转角转向连续 {self._small_turn_fail} 批被地面打滑吞掉"
                          f"（{per_step:.2f}°/次），升级为大角度转向")
                    self._small_turn_usable = False
                    self._big_turn(new_bearing)
            else:
                self._small_turn_fail = 0
                print(f"[转向] 小转角转向 {n} 次，剩余 {new_bearing:+.1f}° "
                      f"估计 {self._small_turn_deg:.1f}°/次")

    def _big_turn(self, bearing):
        """大步转向兜底：量化到 22°/25.7°，过冲由下一轮闭环吸收

        防振荡：大转步长（22/25.7°）大于死区（8°）的两倍时，小误差会在
        ±死区外来回转（9°→-13°→9°…）。若上一次大转后误差符号翻转且幅度
        没有明显改善，停止转向，改用"带航向偏置的接近"（横偏交给 sidestep）。
        """
        if abs(bearing) <= ALIGN_TOL_DEG:
            return
        if self._last_big_turn is not None:
            last_sign, last_abs = self._last_big_turn
            if last_sign * bearing < 0 and last_abs <= abs(bearing) + 1.0:
                print(f"[转向] 大角度转向出现振荡（{last_abs:.0f}° → {abs(bearing):.0f}°），"
                      "停止转向，改带航向偏置接近")
                self._turn_oscillation = True
                return
        step = TURN_RIGHT_DEG if bearing > 0 else TURN_LEFT_DEG
        n = int(np.clip(round(abs(bearing) / step), 1, 3))
        action = "turn_right" if bearing > 0 else "turn_left"
        self._act(action, n)
        self._last_turn = (action, n)
        self._last_big_turn = (1 if bearing > 0 else -1, abs(bearing))
        print(f"[转向] 大角度转向 {_action_cn(action, n)}（航向差 {bearing:+.1f}°）")

    def do_sidestep(self, lat):
        """横移纠偏。右正。"""
        n = int(np.clip(round(abs(lat) / RIGHT_MOVE_CM), 1, 3))
        action = "right_move" if lat > 0 else "left_move"
        self._act(action, n)
        print(f"[横移] {_action_cn(action, n)}（横向偏差 {lat:+.1f}cm）")

    def _recover(self, fails):
        """定位丢失恢复（按失败次数逐级升级）；返回 False = 放弃本段

        每级动作后由调用方重试定位：成功则 fails 归零；仍失败则升级下一级。
        fails==2 的"朝目标转"是关键：目标在身后时，转身过程中可能出现
        "整帧看不到任何面板"的方位（实测格心朝南 0 个对应点），此时只能用
        运动先验位姿（动作模型推算，仍可用）算目标方位，把视角转回有面板
        的方向——纯头部扫（±40.5°）救不了。
        """
        self.phase = f"RECOVER{fails}"
        if fails > RECOVER_LIMIT:
            print(f"[恢复] 连续 {fails} 次定位失败，放弃本段处理")
            return False
        if fails == 1:
            print("[恢复] 切换低头档补扫")
            self.state.set_pitch(PITCH_DOWN)
            loc = self.localize(PITCH_DOWN)
            self.state.set_pitch(PITCH_NAV)
            if loc is not None:
                print("[恢复] 低头档补扫成功")
        elif fails == 2:
            digit = getattr(self, "_current_digit", None)
            if digit is not None and digit in self.digit_cell:
                bearing = self.target_relative(digit)[2]
                if abs(bearing) > ALIGN_TOL_DEG:
                    print(f"[恢复] 按动作先验朝目标转向 {bearing:+.0f}° 后重新扫描")
                    self._big_turn(bearing)
                else:
                    print("[恢复] 按动作先验已朝向目标，右转 22° 更换视角后重新扫描")
                    self._act("turn_right", 1)
            else:
                print("[恢复] 右转 22° 更换视角后重新扫描")
                self._act("turn_right", 1)
        elif fails == 3:
            print("[恢复] 后退一步后重新扫描")
            self._act("back_one_step", 1)
        elif fails == 4:
            # 运动先验盲走一步（不依赖定位，零解算风险），把视角带离死区
            print("[恢复] 按动作先验盲走一步后重新扫描")
            self._act("go_forward_one_step", 1)
        elif fails == 5 and self._last_turn is not None:
            # 大转过冲可能把场地转出视野——撤销上次转向回到可定位姿态
            action, n = self._last_turn
            undo = {"turn_left": "turn_right", "turn_right": "turn_left",
                    "turn_left_small_step": "turn_right_small_step",
                    "turn_right_small_step": "turn_left_small_step"}[action]
            print(f"[恢复] 撤销上次转向 {_action_cn(action, n)} → {_action_cn(undo, n)}")
            self._act(undo, n)
            self._last_turn = None
        return True


# =====================================================================
# 投影与工具
# =====================================================================

# 画幅矩形（裁切预测用；与 camera_config 的原生分辨率一致）
_IMAGE_RECT = np.array([[0.0, 0.0], [CAMERA_WIDTH, 0.0],
                        [CAMERA_WIDTH, CAMERA_HEIGHT],
                        [0.0, CAMERA_HEIGHT]], dtype=np.float32)


def _camera_rotation(th_rad, pitch_pulse, head_pulse,
                     pitch_offset_deg=CAM_PITCH_MOUNT_OFFSET_DEG):
    """世界->相机旋转矩阵（行 = 相机三轴在世界系方向）

    有效俯仰 = 舵机名义角 + 安装下俯偏移（2026-09-11 现场实测：名义 27°
    实际 ≈45°+，见 camera_config.CAM_PITCH_MOUNT_OFFSET_DEG）。
    头部偏航：脉宽左转(>1500)为正，相机方位角 = 机体航向 − 头部角
    （与 core/robot_core.pulse_to_angle、单测验证的补偿模型一致）。
    """
    a = np.radians((1500 - pitch_pulse) * SERVO_DEG_PER_US + pitch_offset_deg)
    f = th_rad - np.radians((head_pulse - HEAD_CENTER) * SERVO_DEG_PER_US)
    sa, ca = np.sin(a), np.cos(a)
    sf, cf = np.sin(f), np.cos(f)
    return np.vstack([np.array([cf, -sf, 0.0]),                    # 图像右
                      np.array([-sa * sf, -sa * cf, -ca]),         # 图像下
                      np.array([ca * sf, ca * cf, -sa])])          # 视轴


def project_ground_to_pixel(pts_ground, x, y, th_rad, pitch_pulse,
                            head_pulse=HEAD_CENTER,
                            pitch_offset_deg=CAM_PITCH_MOUNT_OFFSET_DEG,
                            cam_height_cm=CAM_HEIGHT_CM):
    """格心(场地系 cm) → 像素：位姿 (x,y,θ) + 俯仰/头部档 + 真实内参/畸变"""
    R = _camera_rotation(th_rad, pitch_pulse, head_pulse, pitch_offset_deg)
    pts = np.atleast_2d(np.asarray(pts_ground, dtype=np.float64))
    if pts.shape[1] == 2:
        pts = np.column_stack([pts, np.zeros(len(pts))])  # 地面 z=0
    diff = pts - np.array([x, y, cam_height_cm])  # 相机光心高度
    p_cam = (R @ diff.T).T
    norm = p_cam[:, :2] / p_cam[:, 2:3]
    pts3 = np.column_stack([norm, np.ones(len(norm))]).reshape(-1, 1, 3)
    pix, _ = cv2.projectPoints(pts3.astype(np.float32), np.zeros(3),
                               np.zeros(3), CAMERA_INTRINSIC,
                               CAMERA_DISTORTION)
    return pix[:, 0, :]


def clipped_quad_centroid(center_xy, x, y, th_rad, pitch_pulse,
                          head_pulse=HEAD_CENTER, half_cm=PANEL_HALF_CM,
                          pitch_offset_deg=CAM_PITCH_MOUNT_OFFSET_DEG,
                          cam_height_cm=CAM_HEIGHT_CM):
    """裁切感知预测：面板四角投影 → 与画幅求交 → 交多边形面积质心

    与检测端 hull_centroid_px 同定义（都是"可见区域"的面积质心），
    因此被画幅裁切时仍然成立；未裁切时也成立（只是精度略低于中心模型）。
    面板角点落到相机背后（z<=0.05）或投影非有限时返回 None（该起点判无效）；
    面板在画外时返回"四角钳到画幅后的均值"，保持数值雅可比连续。
    """
    if cv2 is None:
        return None
    R = _camera_rotation(th_rad, pitch_pulse, head_pulse)
    cx, cy = float(center_xy[0]), float(center_xy[1])
    corners = np.array([[cx - half_cm, cy - half_cm],
                        [cx + half_cm, cy - half_cm],
                        [cx + half_cm, cy + half_cm],
                        [cx - half_cm, cy + half_cm]], dtype=np.float64)
    pts = np.column_stack([corners, np.zeros(4)])
    p_cam = (R @ (pts - np.array([x, y, cam_height_cm])).T).T
    if np.any(p_cam[:, 2] <= 0.05):
        return None
    norm = p_cam[:, :2] / p_cam[:, 2:3]
    pts3 = np.column_stack([norm, np.ones(len(norm))]).reshape(-1, 1, 3)
    pix, _ = cv2.projectPoints(pts3.astype(np.float32), np.zeros(3),
                               np.zeros(3), CAMERA_INTRINSIC,
                               CAMERA_DISTORTION)
    pix = pix[:, 0, :]
    if not np.all(np.isfinite(pix)):
        return None
    # 画外角点投影可达 1e5+（面板近边贴相机平面），这是合法输入——
    # 交给 intersectConvexConvex 裁到画幅即可；只防 float32 溢出。
    pix = np.clip(pix, -1e6, 1e6)
    area, inter = cv2.intersectConvexConvex(pix.astype(np.float32),
                                            _IMAGE_RECT)
    if inter is not None and len(inter) >= 3 and area > 1e-9:
        m = cv2.moments(inter)
        if m["m00"] > 1e-9:
            return np.array([m["m10"] / m["m00"], m["m01"] / m["m00"]])
    # 投影与画幅无交集（或退化）：返回"四角钳到画幅后的均值"作极限。
    # 必须连续——数值雅可比对位姿扰动 ±0.5cm/±0.5° 时，边缘处的交集可能
    # 一步消失；若直接返回 None 会让整个起点解算失败（实测某位姿 6 点全丢）。
    return np.clip(pix, [0.0, 0.0],
                   [CAMERA_WIDTH, CAMERA_HEIGHT]).mean(axis=0)


def _wrap_angle(a):
    """角度弧度归一化到 (-π, π]"""
    while a > np.pi:
        a -= 2 * np.pi
    while a <= -np.pi:
        a += 2 * np.pi
    return a


# =====================================================================
# 关卡入口（main.py 注册）
# =====================================================================

def run_level(state: RobotState):
    """数字宫格关卡入口：python main.py nine_grid"""
    level = NineGridLevel(state)
    return level.run_level()
